INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-2-u4-C1','kor',1,2,'u4',3,'이야기의 인물과 인물이 한 일 알기 — 「미역도 맛있어」를 들으며 등장하는 인물(주원·서윤·선생님)을 찾고, 인물의 생각이나 말, 행동을 보고 누가 무엇을 했는지 알기, 이야기에 없는 일은 넣지 않기',ARRAY['2국01-01']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-2-u4-C2','kor',1,2,'u4',6,'시간을 나타내는 말로 일의 차례 정리하기 — 「소금을 만드는 맷돌」에서 어느 날 아침·저녁·깊은 밤처럼 일이 일어난 때를 알려 주는 말을 찾고, 누가 무엇을 했는지 생각하며 일이 일어난 차례 정리하기',ARRAY['2국01-01']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-2-u4-C3','kor',1,2,'u4',6,'큰따옴표와 작은따옴표 알기 — 인물이 소리 내어 한 말은 큰따옴표 “ ”, 마음속으로 한 말은 작은따옴표 ‘ ’, 칸 안 알맞은 자리에 바르게 쓰기',ARRAY['2국01-01']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-2-u4-C4','kor',1,2,'u4',8,'만화 영화를 보고 있었던 일 정리하기 — 「빨간 모자가 된 아이쿠」에 나오는 인물을 먼저 알고, 인물의 말·표정·몸짓을 살피며 있었던 일을 차례대로 정리하기',ARRAY['2국06-01']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-2-u4-C5','kor',1,2,'u4',10,'감동적인 장면에 대해 이야기 나누기 — 「아기 거북이가 숲으로 왔어요!」에서 일어난 일을 정리하고, 재미있거나 감동적인 장면을 까닭과 함께 내 말로 말하기, 사람마다 감동이 다름을 알고 존중하기, 나라면 어떻게 했을지 말하기',ARRAY['2국05-02']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-2-u4-C6','kor',1,2,'u4',12,'감동적인 장면을 그림으로 나타내고 감상하기 — 이야기하기→그리기→전시하고 감상하기, 인물과 인물이 한 말·행동이 드러나게 그리고 어떤 장면인지 글로 쓰기, 입술책·역할놀이, 친구 그림을 비교하며 존중하기',ARRAY['2국06-01']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-2-u4-C7','kor',1,2,'u4',14,'동작을 나타내는 말 알기 — 읽습니다·씻습니다·먹습니다·닦습니다·찹니다·그립니다처럼 누가 무엇을 하는지 나타내는 말을 문장에 넣기(기초 다지기)',ARRAY['2국01-01']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u4-X01','kor',1,'u4',ARRAY['K1-2-u4-C1','K1-2-u4-C4']::text[],'인물이 무엇을 했는지를 생각·말·행동이 아니라 목소리 크기·옷·겉모습으로 찾으려 한다','「목소리가 크다고 무엇을 했는지 알 수 있나요?」 인물이 한 말 한 줄, 한 행동 한 줄을 손가락으로 짚게 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u4-X02','kor',1,'u4',ARRAY['K1-2-u4-C1','K1-2-u4-C2','K1-2-u4-C4']::text[],'이야기에 없던 일을 있었던 일로 넣거나 인물이 한 일을 바꾼다','「그 일이 글 어디에 있나요?」 글에서 그 줄을 찾아 보게 하고, 없으면 넣지 않기로 약속하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u4-X03','kor',1,'u4',ARRAY['K1-2-u4-C1','K1-2-u4-C4','K1-2-u4-C5']::text[],'이야기나 만화 영화에 나오지 않는 사람이나 물건을 인물이라고 한다','인물 이름을 글에서 동그라미 치게 하고 「이 사람이 이야기에 나오나요?」 되묻기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u4-X04','kor',1,'u4',ARRAY['K1-2-u4-C2']::text[],'시간을 나타내는 말이 아닌 것(시장·궁궐·맷돌 같은 곳이나 물건)을 때를 알려 주는 말로 고른다','「언제?」 하고 물었을 때 대답이 되는 말인지 확인하게 하기 — 「시장에」는 「어디에서」의 대답') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u4-X05','kor',1,'u4',ARRAY['K1-2-u4-C2','K1-2-u4-C4','K1-2-u4-C5']::text[],'먼저 있었던 일과 나중에 있었던 일을 바꾸어 늘어놓는다','아침·저녁·밤 카드를 먼저 줄 세우고, 「무슨 일 때문에 다음 일이 일어났지?」 물으며 일을 붙이게 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u4-X06','kor',1,'u4',ARRAY['K1-2-u4-C3']::text[],'큰따옴표와 작은따옴표를 바꾸어 쓴다(마음속 말에 큰따옴표)','「입으로 소리 냈나요, 마음속으로 했나요?」 입을 가리키면 큰따옴표, 가슴을 가리키면 작은따옴표로 몸으로 익히기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u4-X07','kor',1,'u4',ARRAY['K1-2-u4-C3']::text[],'따옴표를 쓰는 자리나 모양을 틀린다(한쪽만 쓰거나 아무 데나 쓴다)','따옴표는 말의 앞과 뒤에 열고 닫는 두 짝을 함께 쓴다는 것을 따라 쓰며 익히기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u4-X08','kor',1,'u4',ARRAY['K1-2-u4-C4','K1-2-u4-C5']::text[],'만화 영화를 볼 때 영상 길이·화면 색처럼 이야기와 상관없는 것을 살핀다','「그걸 알면 무슨 일이 있었는지 알 수 있나요?」 인물과 인물이 한 일로 다시 눈을 돌리게 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u4-X09','kor',1,'u4',ARRAY['K1-2-u4-C4','K1-2-u4-C2']::text[],'있었던 일을 정리할 때 누가·무엇을 했는지 가운데 하나를 빠뜨린다','두 손가락(누가·무엇을)을 펴고 한 칸씩 접으며 빠진 칸 찾기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u4-X10','kor',1,'u4',ARRAY['K1-2-u4-C5']::text[],'「재미있었다」·「감동적이었다」 한마디만 말하고 어떤 장면인지, 왜 그런지 말하지 않는다','「어떤 장면이? 왜?」 하고 되물어 인물이 한 일에서 까닭 한 가지를 찾게 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u4-X11','kor',1,'u4',ARRAY['K1-2-u4-C5']::text[],'친구가 말한 느낌을 그대로 따라 말하거나 인물의 말을 외워서 말한다','「네 마음은 어디에서 움직였어?」 친구와 다른 장면을 골라도 된다고 먼저 말해 주기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u4-X12','kor',1,'u4',ARRAY['K1-2-u4-C5','K1-2-u4-C6']::text[],'나와 다른 장면을 고른 친구에게 틀렸다고 하거나 고치려 한다','「사람마다 마음이 움직이는 곳이 달라요」 — 친구에게 왜 그 장면인지 물어보게 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u4-X13','kor',1,'u4',ARRAY['K1-2-u4-C5']::text[],'감동의 까닭을 인물이 한 일이 아니라 영상 길이·색깔·그림 솜씨에서 찾는다','「그 인물이 무엇을 했길래 마음이 움직였나요?」 까닭을 인물의 말·행동에서 찾게 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u4-X14','kor',1,'u4',ARRAY['K1-2-u4-C6']::text[],'감동적인 장면을 그릴 때 예쁘게 그리기·꾸미기에만 힘써 장면이 드러나지 않는다','「이 그림만 보고 어떤 장면인지 알 수 있나요?」 인물과 한 일이 보이면 된다고 짚어 주기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u4-X15','kor',1,'u4',ARRAY['K1-2-u4-C6']::text[],'그림에 인물과 인물이 한 일이 드러나지 않는다(배경만·물건만)','그림 옆에 「누가 무엇을 하는 장면」 한 줄을 먼저 쓰고 그리게 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u4-X16','kor',1,'u4',ARRAY['K1-2-u4-C6']::text[],'친구 그림을 볼 때 누가 더 잘 그렸는지 고르거나 흉을 본다','「어떤 장면을 골랐는지, 왜 골랐는지」 한 가지씩 물어보게 하고 견주는 말은 받지 않기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u4-X17','kor',1,'u4',ARRAY['K1-2-u4-C7']::text[],'동작을 나타내는 말과 아닌 말(물건 이름·모양 말)을 가르지 못하거나 그림에 맞지 않는 동작 말을 넣는다','「몸으로 해 볼 수 있나요?」 동작 말은 몸으로 흉내 내 보게 하기 — 「책상」은 못 하지만 「닦습니다」는 할 수 있다') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L01_basic#1','kor',1,2,'u4','L01','g1_2_kor_u4_L01_basic','lesson_basic','K1-2-u4-C5',1,'mc','auto','『국어』 111쪽 생각 열기 — 그림 속 아기 거북은 무엇을 하고 있나요?',ARRAY['K1-2-u4-X03']::text[],false,'{"seq":1,"concept":"K1-2-u4-C5","difficulty":1,"kind":"mc","stem":"『국어』 111쪽 생각 열기 — 그림 속 아기 거북은 무엇을 하고 있나요?","options":[{"t":"알에서 깨어나고 있어요","correct":true},{"t":"밥을 먹고 있어요","mis":"K1-2-u4-X03"},{"t":"맷돌을 들고 달리고 있어요","mis":"K1-2-u4-X03"}],"explanation":["아기 거북이 알에서 깨어나고 있어요.","밥을 먹는 것은 아이들, 맷돌을 든 것은 다른 그림이에요.","111쪽 그림을 떠올려요."],"asset":{"type":"scene","icon":"🐢🥚","text":"알에서 깨어나는 아기 거북"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L01_basic#2','kor',1,2,'u4','L01','g1_2_kor_u4_L01_basic','lesson_basic','K1-2-u4-C1',1,'mc','auto','『국어』 111쪽 생각 열기 — 그림 속 아이들은 무엇을 하고 있나요?',ARRAY['K1-2-u4-X02']::text[],false,'{"seq":2,"concept":"K1-2-u4-C1","difficulty":1,"kind":"mc","stem":"『국어』 111쪽 생각 열기 — 그림 속 아이들은 무엇을 하고 있나요?","options":[{"t":"급식을 먹고 있어요","correct":true},{"t":"공을 차고 있어요","mis":"K1-2-u4-X02"},{"t":"잠을 자고 있어요","mis":"K1-2-u4-X02"}],"explanation":["아이들이 밥을 먹고 있어요.","그림 속에서 누가 무엇을 하는지 살펴봐요.","111쪽 그림이에요."],"asset":{"type":"scene","icon":"🍱👧👦","text":"급식 시간"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L01_basic#3','kor',1,2,'u4','L01','g1_2_kor_u4_L01_basic','lesson_basic','K1-2-u4-C4',1,'mc','auto','이 단원에서 공부할 내용은?',ARRAY['K1-2-u4-X08']::text[],false,'{"seq":3,"concept":"K1-2-u4-C4","difficulty":1,"kind":"mc","stem":"이 단원에서 공부할 내용은?","options":[{"t":"만화 영화를 보고 생각이나 느낌 나누기","correct":true},{"t":"만화 영화의 길이 재기","mis":"K1-2-u4-X08"},{"t":"만화 영화를 만든 회사 알기","mis":"K1-2-u4-X08"}],"explanation":["만화 영화를 보고 생각이나 느낌을 나누어요.","이야기를 듣거나 읽고 일의 차례도 정리해요.","단원 학습 내용이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
