INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L01_basic#5','kor',1,2,'u4','L01','g1_2_kor_u4_L01_basic','lesson_basic','K1-2-u4-C5',2,'mc','auto','『국어』 113쪽 2번 — 기억에 남는 장면을 바르게 쓴 것은?',ARRAY['K1-2-u4-X10','K1-2-u4-X08']::text[],false,'{"seq":5,"concept":"K1-2-u4-C5","difficulty":2,"kind":"mc","stem":"『국어』 113쪽 2번 — 기억에 남는 장면을 바르게 쓴 것은?","options":[{"t":"주인공이 친구들과 간식을 나누어 먹는 장면","correct":true},{"t":"재미있다","mis":"K1-2-u4-X10"},{"t":"파란색","mis":"K1-2-u4-X08"}],"explanation":["누가 무엇을 하는 장면인지 써요.","한마디나 색깔만으로는 어떤 장면인지 몰라요.","113쪽 2번이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L01_basic#6','kor',1,2,'u4','L01','g1_2_kor_u4_L01_basic','lesson_basic','K1-2-u4-C5',2,'mc','auto','장면이 기억에 남는 까닭을 말할 때 알맞은 것은?',ARRAY['K1-2-u4-X10','K1-2-u4-X13']::text[],false,'{"seq":6,"concept":"K1-2-u4-C5","difficulty":2,"kind":"mc","stem":"장면이 기억에 남는 까닭을 말할 때 알맞은 것은?","options":[{"t":"누가 무엇을 하는 장면을 볼 때 어떤 생각이 들었는지 말해요","correct":true},{"t":"그냥 좋았다고만 말해요","mis":"K1-2-u4-X10"},{"t":"만화 영화가 몇 분인지 말해요","mis":"K1-2-u4-X13"}],"explanation":["「누가 무엇을 하는 장면을 볼 때 ~한 생각이 들어서」처럼 말해요.","까닭은 인물이 한 일에서 찾아요.","지도서 179쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
