INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L01_challenge#5','kor',1,2,'u4','L01','g1_2_kor_u4_L01_challenge','lesson_challenge','K1-2-u4-C4',3,'mc','auto','만화 영화를 떠올릴 때 먼저 생각할 것은?',ARRAY['K1-2-u4-X08']::text[],false,'{"seq":5,"concept":"K1-2-u4-C4","difficulty":3,"kind":"mc","stem":"만화 영화를 떠올릴 때 먼저 생각할 것은?","options":[{"t":"누가 나오고 어떤 일이 있었는지","correct":true},{"t":"화면이 몇 가지 색이었는지","mis":"K1-2-u4-X08"},{"t":"몇 분짜리였는지","mis":"K1-2-u4-X08"}],"explanation":["인물과 있었던 일을 떠올려요.","색깔이나 길이는 이야기가 아니에요.","112쪽 1번이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L01_challenge#6','kor',1,2,'u4','L01','g1_2_kor_u4_L01_challenge','lesson_challenge','K1-2-u4-C5',3,'mc','auto','까닭을 넣어 기억에 남는 장면을 말한 것은?',ARRAY['K1-2-u4-X01','K1-2-u4-X13']::text[],false,'{"seq":6,"concept":"K1-2-u4-C5","difficulty":3,"kind":"mc","stem":"까닭을 넣어 기억에 남는 장면을 말한 것은?","options":[{"t":"주인공이 친구를 도와주는 장면을 보니 나도 친구를 돕고 싶었어","correct":true},{"t":"주인공은 파란 옷을 입었어","mis":"K1-2-u4-X01"},{"t":"그 만화 영화는 길었어","mis":"K1-2-u4-X13"}],"explanation":["어떤 장면인지와 그때의 생각이 들어 있어요.","옷이나 길이는 까닭이 아니에요.","지도서 179쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L01_challenge#7','kor',1,2,'u4','L01','g1_2_kor_u4_L01_challenge','lesson_challenge','K1-2-u4-C5',3,'ox','auto','기억에 남는 장면을 말할 때 정답은 하나뿐이에요.',ARRAY['K1-2-u4-X12']::text[],false,'{"seq":7,"concept":"K1-2-u4-C5","difficulty":3,"kind":"ox","stem":"기억에 남는 장면을 말할 때 정답은 하나뿐이에요.","answer":"X","reason_options":[{"t":"사람마다 기억에 남는 장면이 달라서 여러 가지 답이 있으니까","correct":true},{"t":"선생님이 정한 장면만 맞으니까","mis":"K1-2-u4-X12"}],"mis":"K1-2-u4-X12","explanation":["같은 만화 영화라도 장면은 다를 수 있어요.","서로의 생각을 존중해요.","113쪽 3번이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L01_challenge#8','kor',1,2,'u4','L01','g1_2_kor_u4_L01_challenge','lesson_challenge','K1-2-u4-C5',4,'sa','auto','『국어』 113쪽 — 기억에 남는 장면을 정리하는 표에서 첫째 칸에 쓰는 것은 무엇인가요?','{}'::text[],false,'{"seq":8,"concept":"K1-2-u4-C5","difficulty":4,"kind":"sa","stem":"『국어』 113쪽 — 기억에 남는 장면을 정리하는 표에서 첫째 칸에 쓰는 것은 무엇인가요?","answer":["제목"],"explanation":["첫째 칸에는 제목을 써요.","둘째 칸에는 기억에 남는 장면을 써요.","113쪽 2번이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L01_challenge#9','kor',1,2,'u4','L01','g1_2_kor_u4_L01_challenge','lesson_challenge','K1-2-u4-C5',4,'essay','teacher','자신이 본 만화 영화의 제목과 기억에 남는 장면을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K1-2-u4-C5","difficulty":4,"kind":"essay","stem":"자신이 본 만화 영화의 제목과 기억에 남는 장면을 쓰세요.","answer_guide":{"answer":"예: 제목 「○○○」 — 주인공이 친구들과 간식을 나누어 먹는 장면 — 제목과 누가 무엇을 하는 장면인지 있으면 맞아요.","scoring_points":["제목을 썼는가","누가 무엇을 하는 장면인지 썼는가","문장이 자연스러운가"]},"explanation":["재미있게 본 만화 영화를 떠올려요.","누가 무엇을 하는 장면인지 써요.","113쪽 2번이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L01_challenge#10','kor',1,2,'u4','L01','g1_2_kor_u4_L01_challenge','lesson_challenge','K1-2-u4-C5',4,'essay','teacher','그 장면이 기억에 남는 까닭을 「누가 무엇을 하는 장면을 볼 때 ~해서」 틀로 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K1-2-u4-C5","difficulty":4,"kind":"essay","stem":"그 장면이 기억에 남는 까닭을 「누가 무엇을 하는 장면을 볼 때 ~해서」 틀로 쓰세요.","answer_guide":{"answer":"예: 주인공이 넘어진 친구를 일으켜 주는 장면을 볼 때 마음이 따뜻해져서 기억에 남아요. — 장면과 까닭이 있으면 맞아요.","scoring_points":["장면이 드러나는가","까닭을 썼는가","틀에 맞게 썼는가"]},"explanation":["그때 든 생각이나 느낌을 떠올려요.","까닭은 인물이 한 일에서 찾아요.","지도서 179쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L03_basic#1','kor',1,2,'u4','L03','g1_2_kor_u4_L03_basic','lesson_basic','K1-2-u4-C1',1,'mc','auto','『국어』 115쪽 2번 — 「미역도 맛있어」는 언제 일어난 일인가요?',ARRAY['K1-2-u4-X02']::text[],false,'{"seq":1,"concept":"K1-2-u4-C1","difficulty":1,"kind":"mc","stem":"『국어』 115쪽 2번 — 「미역도 맛있어」는 언제 일어난 일인가요?","options":[{"t":"오늘 점심시간","correct":true},{"t":"어제 저녁","mis":"K1-2-u4-X02"},{"t":"아침 등굣길","mis":"K1-2-u4-X02"}],"explanation":["「오늘 점심시간에」라고 했어요.","점심 급식에 미역무침이 나왔어요.","첫째 줄이에요."],"asset":{"type":"passage","lines":["오늘 점심시간에 급식 반찬으로 미역무침이 나왔다.","나는 미역을 가장 싫어한다. 하지만 내 친구 서윤이는 미역무침이 맛있다고 했다.","“너도 한번 먹어 봐. 새콤달콤한 맛이 얼마나 좋은데.”","서윤이는 미역무침을 맛있게 먹었다.","나는 그 모습을 보고도 먹을 용기가 나지 않아 고개를 절레절레 저었다.","하지만 주위를 둘러보니 친구들이 모두 맛있게 미역무침을 먹고 있었다.","‘그럼 나도 한번 먹어 볼까?’"],"title":"『국어』 114쪽 — 미역도 맛있어 (1)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L03_basic#2','kor',1,2,'u4','L03','g1_2_kor_u4_L03_basic','lesson_basic','K1-2-u4-C1',1,'mc','auto','주원이에게 미역무침을 먹어 보라고 한 사람은?',ARRAY['K1-2-u4-X02','K1-2-u4-X03']::text[],false,'{"seq":2,"concept":"K1-2-u4-C1","difficulty":1,"kind":"mc","stem":"주원이에게 미역무침을 먹어 보라고 한 사람은?","options":[{"t":"친구 서윤이","correct":true},{"t":"선생님","mis":"K1-2-u4-X02"},{"t":"엄마","mis":"K1-2-u4-X03"}],"explanation":["서윤이가 「너도 한번 먹어 봐.」라고 했어요.","선생님은 나중에 칭찬해 주셨어요.","셋째 줄이에요."],"asset":{"type":"passage","lines":["오늘 점심시간에 급식 반찬으로 미역무침이 나왔다.","나는 미역을 가장 싫어한다. 하지만 내 친구 서윤이는 미역무침이 맛있다고 했다.","“너도 한번 먹어 봐. 새콤달콤한 맛이 얼마나 좋은데.”","서윤이는 미역무침을 맛있게 먹었다.","나는 그 모습을 보고도 먹을 용기가 나지 않아 고개를 절레절레 저었다.","하지만 주위를 둘러보니 친구들이 모두 맛있게 미역무침을 먹고 있었다.","‘그럼 나도 한번 먹어 볼까?’"],"title":"『국어』 114쪽 — 미역도 맛있어 (1)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L03_basic#3','kor',1,2,'u4','L03','g1_2_kor_u4_L03_basic','lesson_basic','K1-2-u4-C1',1,'mc','auto','주원이가 가장 싫어하는 음식은?',ARRAY['K1-2-u4-X02']::text[],false,'{"seq":3,"concept":"K1-2-u4-C1","difficulty":1,"kind":"mc","stem":"주원이가 가장 싫어하는 음식은?","options":[{"t":"미역","correct":true},{"t":"김치","mis":"K1-2-u4-X02"},{"t":"브로콜리","mis":"K1-2-u4-X02"}],"explanation":["「나는 미역을 가장 싫어한다.」라고 했어요.","글에 없는 음식은 고르지 않아요.","둘째 줄이에요."],"asset":{"type":"passage","lines":["오늘 점심시간에 급식 반찬으로 미역무침이 나왔다.","나는 미역을 가장 싫어한다. 하지만 내 친구 서윤이는 미역무침이 맛있다고 했다.","“너도 한번 먹어 봐. 새콤달콤한 맛이 얼마나 좋은데.”","서윤이는 미역무침을 맛있게 먹었다.","나는 그 모습을 보고도 먹을 용기가 나지 않아 고개를 절레절레 저었다.","하지만 주위를 둘러보니 친구들이 모두 맛있게 미역무침을 먹고 있었다.","‘그럼 나도 한번 먹어 볼까?’"],"title":"『국어』 114쪽 — 미역도 맛있어 (1)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L03_basic#4','kor',1,2,'u4','L03','g1_2_kor_u4_L03_basic','lesson_basic','K1-2-u4-C1',1,'mc','auto','미역무침의 맛은 어떠했나요?',ARRAY['K1-2-u4-X02']::text[],false,'{"seq":4,"concept":"K1-2-u4-C1","difficulty":1,"kind":"mc","stem":"미역무침의 맛은 어떠했나요?","options":[{"t":"입안에 새콤함이 가득해지는 맛","correct":true},{"t":"너무 매운 맛","mis":"K1-2-u4-X02"},{"t":"아무 맛도 없는 맛","mis":"K1-2-u4-X02"}],"explanation":["계속 먹다 보니 입안에 새콤함이 가득해졌어요.","글에 없는 맛은 고르지 않아요.","셋째 줄이에요."],"asset":{"type":"passage","lines":["나는 눈을 질끈 감고 미역무침을 한번 먹어 보았다.","입을 살짝 벌려 미역무침을 조금 먹어 보았더니 생각보다 맛이 좋았다.","계속 먹다 보니 입안에 새콤함이 가득해졌다. 어느새 미역무침을 모두 다 먹었다.","“주원이는 반찬을 골고루 잘 먹는구나.”","선생님께서도 나를 칭찬해 주시며 박수도 쳐 주셨다.","나는 어깨가 으쓱해지고 자꾸만 웃음이 나왔다.","‘다음에도 새로운 음식 먹기에 도전해 봐야지.’"],"title":"『국어』 114쪽 — 미역도 맛있어 (2)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L03_basic#5','kor',1,2,'u4','L03','g1_2_kor_u4_L03_basic','lesson_basic','K1-2-u4-C1',2,'match','auto','『국어』 116쪽 4번 — 인물과 생각이나 말을 이어 보세요.','{}'::text[],false,'{"seq":5,"concept":"K1-2-u4-C1","difficulty":2,"kind":"match","stem":"『국어』 116쪽 4번 — 인물과 생각이나 말을 이어 보세요.","pairs":[{"l":"서윤","r":"“너도 한번 먹어 봐.”"},{"l":"주원","r":"‘그럼 나도 한번 먹어 볼까?’"},{"l":"선생님","r":"“주원이는 반찬을 골고루 잘 먹는구나.”"}],"mis":"K1-2-u4-X02","explanation":["인물의 말이나 생각을 보면 누가 무엇을 했는지 알 수 있어요.","큰따옴표는 말, 작은따옴표는 생각이에요.","116쪽 4번이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L03_basic#6','kor',1,2,'u4','L03','g1_2_kor_u4_L03_basic','lesson_basic','K1-2-u4-C1',2,'match','auto','『국어』 116쪽 4번 — 인물과 행동을 이어 보세요.','{}'::text[],false,'{"seq":6,"concept":"K1-2-u4-C1","difficulty":2,"kind":"match","stem":"『국어』 116쪽 4번 — 인물과 행동을 이어 보세요.","pairs":[{"l":"서윤","r":"미역무침을 맛있게 먹었다."},{"l":"주원","r":"눈을 질끈 감고 미역무침을 먹어 보았다."},{"l":"선생님","r":"칭찬하며 박수를 치셨다."}],"mis":"K1-2-u4-X02","explanation":["행동을 정리할 때에는 그림도 참고해요.","누가 무엇을 했는지 이어요.","116쪽 4번이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L03_basic#7','kor',1,2,'u4','L03','g1_2_kor_u4_L03_basic','lesson_basic','K1-2-u4-C1',2,'mc','auto','처음에 주원이는 미역무침을 보고 어떻게 했나요?',ARRAY['K1-2-u4-X02']::text[],false,'{"seq":7,"concept":"K1-2-u4-C1","difficulty":2,"kind":"mc","stem":"처음에 주원이는 미역무침을 보고 어떻게 했나요?","options":[{"t":"먹을 용기가 나지 않아 고개를 절레절레 저었어요","correct":true},{"t":"바로 맛있게 먹었어요","mis":"K1-2-u4-X02"},{"t":"서윤이에게 미역무침을 주었어요","mis":"K1-2-u4-X02"}],"explanation":["처음에는 먹을 용기가 나지 않았어요.","그다음에 용기를 내어 먹어 보았어요.","다섯째 줄이에요."],"asset":{"type":"passage","lines":["오늘 점심시간에 급식 반찬으로 미역무침이 나왔다.","나는 미역을 가장 싫어한다. 하지만 내 친구 서윤이는 미역무침이 맛있다고 했다.","“너도 한번 먹어 봐. 새콤달콤한 맛이 얼마나 좋은데.”","서윤이는 미역무침을 맛있게 먹었다.","나는 그 모습을 보고도 먹을 용기가 나지 않아 고개를 절레절레 저었다.","하지만 주위를 둘러보니 친구들이 모두 맛있게 미역무침을 먹고 있었다.","‘그럼 나도 한번 먹어 볼까?’"],"title":"『국어』 114쪽 — 미역도 맛있어 (1)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L03_basic#8','kor',1,2,'u4','L03','g1_2_kor_u4_L03_basic','lesson_basic','K1-2-u4-C1',2,'mc','auto','미역무침을 먹고 주원이는 어떤 생각을 했나요?',ARRAY['K1-2-u4-X02']::text[],false,'{"seq":8,"concept":"K1-2-u4-C1","difficulty":2,"kind":"mc","stem":"미역무침을 먹고 주원이는 어떤 생각을 했나요?","options":[{"t":"다음에도 새로운 음식 먹기에 도전해 봐야지","correct":true},{"t":"다시는 미역을 먹지 말아야지","mis":"K1-2-u4-X02"},{"t":"서윤이와 놀지 말아야지","mis":"K1-2-u4-X02"}],"explanation":["작은따옴표 안에 주원이의 생각이 있어요.","새로운 것에 도전하는 마음이 생겼어요.","마지막 줄이에요."],"asset":{"type":"passage","lines":["나는 눈을 질끈 감고 미역무침을 한번 먹어 보았다.","입을 살짝 벌려 미역무침을 조금 먹어 보았더니 생각보다 맛이 좋았다.","계속 먹다 보니 입안에 새콤함이 가득해졌다. 어느새 미역무침을 모두 다 먹었다.","“주원이는 반찬을 골고루 잘 먹는구나.”","선생님께서도 나를 칭찬해 주시며 박수도 쳐 주셨다.","나는 어깨가 으쓱해지고 자꾸만 웃음이 나왔다.","‘다음에도 새로운 음식 먹기에 도전해 봐야지.’"],"title":"『국어』 114쪽 — 미역도 맛있어 (2)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L03_basic#9','kor',1,2,'u4','L03','g1_2_kor_u4_L03_basic','lesson_basic','K1-2-u4-C1',2,'ox','auto','인물이 무엇을 했는지 알려면 인물의 생각이나 말, 행동을 살펴봐야 해요.',ARRAY['K1-2-u4-X01']::text[],false,'{"seq":9,"concept":"K1-2-u4-C1","difficulty":2,"kind":"ox","stem":"인물이 무엇을 했는지 알려면 인물의 생각이나 말, 행동을 살펴봐야 해요.","answer":"O","reason_options":[{"t":"생각·말·행동에 인물이 한 일이 드러나니까","correct":true},{"t":"인물의 옷 색깔만 보면 알 수 있으니까","mis":"K1-2-u4-X01"}],"mis":"K1-2-u4-X01","explanation":["인물의 생각이나 말, 행동을 찾아요.","겉모습으로는 무엇을 했는지 몰라요.","지도서 182쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L03_basic#10','kor',1,2,'u4','L03','g1_2_kor_u4_L03_basic','lesson_basic','K1-2-u4-C1',3,'mc','auto','『국어』 117쪽 5번 — 일어난 일의 차례로 알맞은 것은?',ARRAY['K1-2-u4-X05']::text[],false,'{"seq":10,"concept":"K1-2-u4-C1","difficulty":3,"kind":"mc","stem":"『국어』 117쪽 5번 — 일어난 일의 차례로 알맞은 것은?","options":[{"t":"먹기 싫어했다 → 서윤이가 먹어 보라고 했다 → 용기 내어 먹었다 → 칭찬받았다","correct":true},{"t":"칭찬받았다 → 먹기 싫어했다 → 용기 내어 먹었다 → 서윤이가 먹어 보라고 했다","mis":"K1-2-u4-X05"},{"t":"용기 내어 먹었다 → 칭찬받았다 → 서윤이가 먹어 보라고 했다 → 먹기 싫어했다","mis":"K1-2-u4-X05"}],"explanation":["누가 무엇을 했는지 생각하며 차례대로 정리해요.","먼저 있었던 일부터 늘어놓아요.","117쪽 5번이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L03_challenge#1','kor',1,2,'u4','L03','g1_2_kor_u4_L03_challenge','lesson_challenge','K1-2-u4-C1',2,'mc','auto','「미역도 맛있어」에 나오지 않는 인물은?',ARRAY['K1-2-u4-X03']::text[],false,'{"seq":1,"concept":"K1-2-u4-C1","difficulty":2,"kind":"mc","stem":"「미역도 맛있어」에 나오지 않는 인물은?","options":[{"t":"엄마","correct":true},{"t":"서윤","mis":"K1-2-u4-X03"},{"t":"선생님","mis":"K1-2-u4-X03"}],"explanation":["주원이, 서윤이, 선생님이 나와요.","엄마는 나오지 않아요.","115쪽 2번이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
