INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L03_challenge#3','kor',1,2,'u4','L03','g1_2_kor_u4_L03_challenge','lesson_challenge','K1-2-u4-C1',3,'error','auto','친구가 「주원이는 미역무침을 처음부터 좋아했다.」라고 정리했어요. 무엇이 잘못되었나요?',ARRAY['K1-2-u4-X02']::text[],false,'{"seq":3,"concept":"K1-2-u4-C1","difficulty":3,"kind":"error","stem":"친구가 「주원이는 미역무침을 처음부터 좋아했다.」라고 정리했어요. 무엇이 잘못되었나요?","options":[{"t":"주원이는 미역을 가장 싫어했어요 — 용기 내어 먹어 보았어요","correct":true,"mis_target":"K1-2-u4-X02"},{"t":"잘 정리했어요","mis":"K1-2-u4-X02"},{"t":"서윤이가 미역을 싫어했어요","mis":"K1-2-u4-X02"}],"explanation":["글에서는 미역을 가장 싫어한다고 했어요.","글에 없는 일은 넣지 않아요.","둘째 줄이에요."],"asset":{"type":"passage","lines":["오늘 점심시간에 급식 반찬으로 미역무침이 나왔다.","나는 미역을 가장 싫어한다. 하지만 내 친구 서윤이는 미역무침이 맛있다고 했다.","“너도 한번 먹어 봐. 새콤달콤한 맛이 얼마나 좋은데.”","서윤이는 미역무침을 맛있게 먹었다.","나는 그 모습을 보고도 먹을 용기가 나지 않아 고개를 절레절레 저었다.","하지만 주위를 둘러보니 친구들이 모두 맛있게 미역무침을 먹고 있었다.","‘그럼 나도 한번 먹어 볼까?’"],"title":"『국어』 114쪽 — 미역도 맛있어 (1)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L03_challenge#4','kor',1,2,'u4','L03','g1_2_kor_u4_L03_challenge','lesson_challenge','K1-2-u4-C1',3,'error','auto','주원이가 무엇을 했는지 알려고 「주원이 옷이 파란색이다.」를 찾았어요. 무엇이 잘못되었나요?',ARRAY['K1-2-u4-X01']::text[],false,'{"seq":4,"concept":"K1-2-u4-C1","difficulty":3,"kind":"error","stem":"주원이가 무엇을 했는지 알려고 「주원이 옷이 파란색이다.」를 찾았어요. 무엇이 잘못되었나요?","options":[{"t":"옷이 아니라 주원이의 생각이나 말, 행동을 찾아야 해요","correct":true,"mis_target":"K1-2-u4-X01"},{"t":"잘 찾았어요","mis":"K1-2-u4-X01"},{"t":"선생님 옷을 찾아야 해요","mis":"K1-2-u4-X01"}],"explanation":["겉모습으로는 한 일을 알 수 없어요.","생각·말·행동을 찾아요.","지도서 182쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L03_challenge#5','kor',1,2,'u4','L03','g1_2_kor_u4_L03_challenge','lesson_challenge','K1-2-u4-C1',3,'mc','auto','주원이가 미역무침을 먹어 보기로 마음먹은 까닭은?',ARRAY['K1-2-u4-X02']::text[],false,'{"seq":5,"concept":"K1-2-u4-C1","difficulty":3,"kind":"mc","stem":"주원이가 미역무침을 먹어 보기로 마음먹은 까닭은?","options":[{"t":"주위를 둘러보니 친구들이 모두 맛있게 먹고 있어서","correct":true},{"t":"선생님이 혼내셔서","mis":"K1-2-u4-X02"},{"t":"배가 너무 고파서","mis":"K1-2-u4-X02"}],"explanation":["친구들이 맛있게 먹는 모습을 보고 마음이 바뀌었어요.","글에 없는 까닭은 고르지 않아요.","여섯째 줄이에요."],"asset":{"type":"passage","lines":["오늘 점심시간에 급식 반찬으로 미역무침이 나왔다.","나는 미역을 가장 싫어한다. 하지만 내 친구 서윤이는 미역무침이 맛있다고 했다.","“너도 한번 먹어 봐. 새콤달콤한 맛이 얼마나 좋은데.”","서윤이는 미역무침을 맛있게 먹었다.","나는 그 모습을 보고도 먹을 용기가 나지 않아 고개를 절레절레 저었다.","하지만 주위를 둘러보니 친구들이 모두 맛있게 미역무침을 먹고 있었다.","‘그럼 나도 한번 먹어 볼까?’"],"title":"『국어』 114쪽 — 미역도 맛있어 (1)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L03_challenge#6','kor',1,2,'u4','L03','g1_2_kor_u4_L03_challenge','lesson_challenge','K1-2-u4-C1',3,'mc','auto','칭찬을 받은 주원이의 모습으로 알맞은 것은?',ARRAY['K1-2-u4-X05','K1-2-u4-X02']::text[],false,'{"seq":6,"concept":"K1-2-u4-C1","difficulty":3,"kind":"mc","stem":"칭찬을 받은 주원이의 모습으로 알맞은 것은?","options":[{"t":"어깨가 으쓱해지고 자꾸만 웃음이 나왔어요","correct":true},{"t":"고개를 절레절레 저었어요","mis":"K1-2-u4-X05"},{"t":"눈물이 났어요","mis":"K1-2-u4-X02"}],"explanation":["칭찬을 받아 뿌듯했어요.","고개를 저은 것은 처음 일이에요.","여섯째 줄이에요."],"asset":{"type":"passage","lines":["나는 눈을 질끈 감고 미역무침을 한번 먹어 보았다.","입을 살짝 벌려 미역무침을 조금 먹어 보았더니 생각보다 맛이 좋았다.","계속 먹다 보니 입안에 새콤함이 가득해졌다. 어느새 미역무침을 모두 다 먹었다.","“주원이는 반찬을 골고루 잘 먹는구나.”","선생님께서도 나를 칭찬해 주시며 박수도 쳐 주셨다.","나는 어깨가 으쓱해지고 자꾸만 웃음이 나왔다.","‘다음에도 새로운 음식 먹기에 도전해 봐야지.’"],"title":"『국어』 114쪽 — 미역도 맛있어 (2)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L03_challenge#7','kor',1,2,'u4','L03','g1_2_kor_u4_L03_challenge','lesson_challenge','K1-2-u4-C1',3,'match','auto','지도서 183쪽 — 누가 무엇을 했는지 짝을 지어 보세요.','{}'::text[],false,'{"seq":7,"concept":"K1-2-u4-C1","difficulty":3,"kind":"match","stem":"지도서 183쪽 — 누가 무엇을 했는지 짝을 지어 보세요.","pairs":[{"l":"주원이가","r":"미역무침을 먹기 싫어했다."},{"l":"서윤이가","r":"주원이에게 미역무침을 먹어 보라고 했다."},{"l":"선생님께서","r":"주원이를 칭찬해 주셨다."}],"mis":"K1-2-u4-X02","explanation":["누가와 무엇을 했는지를 짝지어요.","짝을 찾아라 놀이예요.","지도서 183쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L03_challenge#8','kor',1,2,'u4','L03','g1_2_kor_u4_L03_challenge','lesson_challenge','K1-2-u4-C1',4,'sa','auto','「미역도 맛있어」에서 주원이에게 미역무침을 권한 친구의 이름을 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K1-2-u4-C1","difficulty":4,"kind":"sa","stem":"「미역도 맛있어」에서 주원이에게 미역무침을 권한 친구의 이름을 쓰세요.","answer":["서윤","서윤이"],"explanation":["서윤이가 먹어 보라고 했어요.","새콤달콤한 맛이 좋다고 했어요.","셋째 줄이에요."],"asset":{"type":"passage","lines":["오늘 점심시간에 급식 반찬으로 미역무침이 나왔다.","나는 미역을 가장 싫어한다. 하지만 내 친구 서윤이는 미역무침이 맛있다고 했다.","“너도 한번 먹어 봐. 새콤달콤한 맛이 얼마나 좋은데.”","서윤이는 미역무침을 맛있게 먹었다.","나는 그 모습을 보고도 먹을 용기가 나지 않아 고개를 절레절레 저었다.","하지만 주위를 둘러보니 친구들이 모두 맛있게 미역무침을 먹고 있었다.","‘그럼 나도 한번 먹어 볼까?’"],"title":"『국어』 114쪽 — 미역도 맛있어 (1)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L03_challenge#9','kor',1,2,'u4','L03','g1_2_kor_u4_L03_challenge','lesson_challenge','K1-2-u4-C1',4,'essay','teacher','『국어』 115쪽 2번 (3) — 주원이와 비슷한 경험을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K1-2-u4-C1","difficulty":4,"kind":"essay","stem":"『국어』 115쪽 2번 (3) — 주원이와 비슷한 경험을 쓰세요.","answer_guide":{"answer":"예: 브로콜리를 좋아하지 않지만 용기 내어 먹어 본 적이 있다. 생각보다 맛있어서 뿌듯했다. — 비슷한 일과 그때 마음이 있으면 맞아요.","scoring_points":["주원이와 비슷한 경험인가","무엇을 했는지 썼는가","그때의 마음을 썼는가"]},"explanation":["먹기 싫었던 음식을 떠올려요.","새로운 것에 도전한 일도 좋아요.","115쪽 2번이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L03_challenge#10','kor',1,2,'u4','L03','g1_2_kor_u4_L03_challenge','lesson_challenge','K1-2-u4-C1',4,'essay','teacher','「미역도 맛있어」에서 일어난 일을 「누가 무엇을 했다」 문장 세 개로 차례대로 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K1-2-u4-C1","difficulty":4,"kind":"essay","stem":"「미역도 맛있어」에서 일어난 일을 「누가 무엇을 했다」 문장 세 개로 차례대로 쓰세요.","answer_guide":{"answer":"예: 주원이는 미역무침을 먹기 싫어했다. / 서윤이가 먹어 보라고 했다. / 주원이는 용기 내어 미역무침을 먹었다. — 차례와 누가 무엇을이 맞으면 맞아요.","scoring_points":["누가 무엇을 했는지 썼는가","차례가 맞는가","글에 있는 일만 썼는가"]},"explanation":["117쪽 5번을 떠올려요.","먼저 있었던 일부터 써요.","지도서 183쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L06_basic#1','kor',1,2,'u4','L06','g1_2_kor_u4_L06_basic','lesson_basic','K1-2-u4-C2',1,'mc','auto','『국어』 121쪽 내용 알기 (1) — 사람들은 시장에 모여 무엇에 대한 이야기를 했나요?',ARRAY['K1-2-u4-X02']::text[],false,'{"seq":1,"concept":"K1-2-u4-C2","difficulty":1,"kind":"mc","stem":"『국어』 121쪽 내용 알기 (1) — 사람들은 시장에 모여 무엇에 대한 이야기를 했나요?","options":[{"t":"임금님이 가진 신기한 맷돌","correct":true},{"t":"바다를 건너는 배","mis":"K1-2-u4-X02"},{"t":"시장에서 파는 소금","mis":"K1-2-u4-X02"}],"explanation":["임금님이 가진 신기한 맷돌에 대해 이야기했어요.","배와 소금은 나중에 나와요.","둘째 줄이에요."],"asset":{"type":"passage","lines":["옛날 옛적에 어느 임금님이 신기한 맷돌을 가지고 있었습니다.","어느 날 아침, 사람들은 시장에 모여 신기한 맷돌에 대해 이야기를 했습니다.","“우리 임금님에게는 신기한 맷돌이 있다네.”","사람들 뒤에서 도둑이 그 말을 조용히 듣고 있었습니다.","‘그 맷돌이 있으면 부자가 될 수 있겠어.’","저녁이 되자 도둑은 궁궐로 숨어들었습니다.","그리고 깊은 밤, 모두 잠든 사이 몰래 맷돌을 훔쳐 도망갔습니다."],"title":"『국어』 118~119쪽 — 소금을 만드는 맷돌 (1)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L06_basic#2','kor',1,2,'u4','L06','g1_2_kor_u4_L06_basic','lesson_basic','K1-2-u4-C2',1,'mc','auto','『국어』 121쪽 내용 알기 (2) — 도둑은 어디로 도망가려고 했나요?',ARRAY['K1-2-u4-X02']::text[],false,'{"seq":2,"concept":"K1-2-u4-C2","difficulty":1,"kind":"mc","stem":"『국어』 121쪽 내용 알기 (2) — 도둑은 어디로 도망가려고 했나요?","options":[{"t":"바다 건너 멀리","correct":true},{"t":"임금님의 궁궐 안","mis":"K1-2-u4-X02"},{"t":"시장 한가운데","mis":"K1-2-u4-X02"}],"explanation":["배를 타고 바다를 건너 멀리 도망가려고 했어요.","궁궐은 맷돌을 훔친 곳이에요.","지도서 186쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L06_basic#3','kor',1,2,'u4','L06','g1_2_kor_u4_L06_basic','lesson_basic','K1-2-u4-C2',1,'mc','auto','『국어』 122쪽 — 시간을 나타내는 말은?',ARRAY['K1-2-u4-X04']::text[],false,'{"seq":3,"concept":"K1-2-u4-C2","difficulty":1,"kind":"mc","stem":"『국어』 122쪽 — 시간을 나타내는 말은?","options":[{"t":"어느 날 아침","correct":true},{"t":"시장","mis":"K1-2-u4-X04"},{"t":"맷돌","mis":"K1-2-u4-X04"}],"explanation":["「어느 날 아침」은 일이 일어난 때를 알려 줘요.","시장은 곳, 맷돌은 물건이에요.","122쪽 1번이에요."],"asset":{"type":"passage","lines":["옛날 옛적에 어느 임금님이 신기한 맷돌을 가지고 있었습니다.","어느 날 아침, 사람들은 시장에 모여 신기한 맷돌에 대해 이야기를 했습니다.","“우리 임금님에게는 신기한 맷돌이 있다네.”","사람들 뒤에서 도둑이 그 말을 조용히 듣고 있었습니다.","‘그 맷돌이 있으면 부자가 될 수 있겠어.’","저녁이 되자 도둑은 궁궐로 숨어들었습니다.","그리고 깊은 밤, 모두 잠든 사이 몰래 맷돌을 훔쳐 도망갔습니다."],"title":"『국어』 118~119쪽 — 소금을 만드는 맷돌 (1)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L06_basic#4','kor',1,2,'u4','L06','g1_2_kor_u4_L06_basic','lesson_basic','K1-2-u4-C3',1,'mc','auto','『국어』 123쪽 — 인물이 소리 내어 한 말에 쓰는 따옴표는?',ARRAY['K1-2-u4-X06','K1-2-u4-X07']::text[],false,'{"seq":4,"concept":"K1-2-u4-C3","difficulty":1,"kind":"mc","stem":"『국어』 123쪽 — 인물이 소리 내어 한 말에 쓰는 따옴표는?","options":[{"t":"“ ” 큰따옴표","correct":true},{"t":"‘ ’ 작은따옴표","mis":"K1-2-u4-X06"},{"t":"? 물음표","mis":"K1-2-u4-X07"}],"explanation":["소리 내어 한 말은 큰따옴표로 나타내요.","마음속으로 한 말은 작은따옴표예요.","123쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L06_basic#5','kor',1,2,'u4','L06','g1_2_kor_u4_L06_basic','lesson_basic','K1-2-u4-C2',2,'match','auto','『국어』 121쪽 낱말 알기 — 낱말과 뜻을 이어 보세요.','{}'::text[],false,'{"seq":5,"concept":"K1-2-u4-C2","difficulty":2,"kind":"match","stem":"『국어』 121쪽 낱말 알기 — 낱말과 뜻을 이어 보세요.","pairs":[{"l":"신기하다","r":"믿을 수 없을 정도로 놀랍다."},{"l":"서두르다","r":"일을 빨리 해치우려고 급하게 바삐 움직이다."}],"mis":"K1-2-u4-X02","explanation":["저절로 움직이는 장난감이 신기하다.","약속에 늦지 않게 출발을 서두르다.","121쪽 낱말 알기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L06_basic#6','kor',1,2,'u4','L06','g1_2_kor_u4_L06_basic','lesson_basic','K1-2-u4-C2',2,'mc','auto','『국어』 122쪽 1번 — 「저녁이 되자 도둑은 궁궐로 숨어들었습니다.」에서 시간을 나타내는 말은?',ARRAY['K1-2-u4-X04']::text[],false,'{"seq":6,"concept":"K1-2-u4-C2","difficulty":2,"kind":"mc","stem":"『국어』 122쪽 1번 — 「저녁이 되자 도둑은 궁궐로 숨어들었습니다.」에서 시간을 나타내는 말은?","options":[{"t":"저녁","correct":true},{"t":"궁궐","mis":"K1-2-u4-X04"},{"t":"도둑","mis":"K1-2-u4-X04"}],"explanation":["「저녁」이 일이 일어난 때예요.","궁궐은 곳, 도둑은 인물이에요.","122쪽 1번이에요."],"asset":{"type":"passage","lines":["옛날 옛적에 어느 임금님이 신기한 맷돌을 가지고 있었습니다.","어느 날 아침, 사람들은 시장에 모여 신기한 맷돌에 대해 이야기를 했습니다.","“우리 임금님에게는 신기한 맷돌이 있다네.”","사람들 뒤에서 도둑이 그 말을 조용히 듣고 있었습니다.","‘그 맷돌이 있으면 부자가 될 수 있겠어.’","저녁이 되자 도둑은 궁궐로 숨어들었습니다.","그리고 깊은 밤, 모두 잠든 사이 몰래 맷돌을 훔쳐 도망갔습니다."],"title":"『국어』 118~119쪽 — 소금을 만드는 맷돌 (1)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L06_basic#7','kor',1,2,'u4','L06','g1_2_kor_u4_L06_basic','lesson_basic','K1-2-u4-C2',2,'mc','auto','도둑이 맷돌을 훔쳐 도망간 때는?',ARRAY['K1-2-u4-X05','K1-2-u4-X02']::text[],false,'{"seq":7,"concept":"K1-2-u4-C2","difficulty":2,"kind":"mc","stem":"도둑이 맷돌을 훔쳐 도망간 때는?","options":[{"t":"깊은 밤, 모두 잠든 사이","correct":true},{"t":"어느 날 아침","mis":"K1-2-u4-X05"},{"t":"점심시간","mis":"K1-2-u4-X02"}],"explanation":["「깊은 밤, 모두 잠든 사이」라고 했어요.","어느 날 아침은 사람들이 시장에 모인 때예요.","일곱째 줄이에요."],"asset":{"type":"passage","lines":["옛날 옛적에 어느 임금님이 신기한 맷돌을 가지고 있었습니다.","어느 날 아침, 사람들은 시장에 모여 신기한 맷돌에 대해 이야기를 했습니다.","“우리 임금님에게는 신기한 맷돌이 있다네.”","사람들 뒤에서 도둑이 그 말을 조용히 듣고 있었습니다.","‘그 맷돌이 있으면 부자가 될 수 있겠어.’","저녁이 되자 도둑은 궁궐로 숨어들었습니다.","그리고 깊은 밤, 모두 잠든 사이 몰래 맷돌을 훔쳐 도망갔습니다."],"title":"『국어』 118~119쪽 — 소금을 만드는 맷돌 (1)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L06_basic#8','kor',1,2,'u4','L06','g1_2_kor_u4_L06_basic','lesson_basic','K1-2-u4-C3',2,'mc','auto','‘그 맷돌이 있으면 부자가 될 수 있겠어.’는 어떤 말인가요?',ARRAY['K1-2-u4-X06','K1-2-u4-X02']::text[],false,'{"seq":8,"concept":"K1-2-u4-C3","difficulty":2,"kind":"mc","stem":"‘그 맷돌이 있으면 부자가 될 수 있겠어.’는 어떤 말인가요?","options":[{"t":"도둑이 마음속으로 한 말","correct":true},{"t":"도둑이 소리 내어 한 말","mis":"K1-2-u4-X06"},{"t":"임금님이 한 말","mis":"K1-2-u4-X02"}],"explanation":["작은따옴표는 마음속으로 한 말이에요.","도둑은 고약한 마음을 먹었어요.","123쪽이에요."],"asset":{"type":"passage","lines":["옛날 옛적에 어느 임금님이 신기한 맷돌을 가지고 있었습니다.","어느 날 아침, 사람들은 시장에 모여 신기한 맷돌에 대해 이야기를 했습니다.","“우리 임금님에게는 신기한 맷돌이 있다네.”","사람들 뒤에서 도둑이 그 말을 조용히 듣고 있었습니다.","‘그 맷돌이 있으면 부자가 될 수 있겠어.’","저녁이 되자 도둑은 궁궐로 숨어들었습니다.","그리고 깊은 밤, 모두 잠든 사이 몰래 맷돌을 훔쳐 도망갔습니다."],"title":"『국어』 118~119쪽 — 소금을 만드는 맷돌 (1)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L06_basic#9','kor',1,2,'u4','L06','g1_2_kor_u4_L06_basic','lesson_basic','K1-2-u4-C2',2,'ox','auto','시간을 나타내는 말을 생각하면 일이 일어난 차례를 정리할 수 있어요.',ARRAY['K1-2-u4-X04']::text[],false,'{"seq":9,"concept":"K1-2-u4-C2","difficulty":2,"kind":"ox","stem":"시간을 나타내는 말을 생각하면 일이 일어난 차례를 정리할 수 있어요.","answer":"O","reason_options":[{"t":"아침·저녁·밤처럼 일이 일어난 때를 알려 주니까","correct":true},{"t":"시간을 나타내는 말은 장소를 알려 주니까","mis":"K1-2-u4-X04"}],"mis":"K1-2-u4-X04","explanation":["일이 일어난 때를 알면 차례가 보여요.","시장·궁궐은 곳을 나타내요.","122쪽 도움말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L06_basic#10','kor',1,2,'u4','L06','g1_2_kor_u4_L06_basic','lesson_basic','K1-2-u4-C2',3,'mc','auto','『국어』 122쪽 (2) — 일이 일어난 차례로 알맞은 것은?',ARRAY['K1-2-u4-X05']::text[],false,'{"seq":10,"concept":"K1-2-u4-C2","difficulty":3,"kind":"mc","stem":"『국어』 122쪽 (2) — 일이 일어난 차례로 알맞은 것은?","options":[{"t":"사람들이 시장에서 맷돌 이야기를 함 → 도둑이 맷돌을 훔침 → 맷돌이 바닷속에 가라앉음","correct":true},{"t":"도둑이 맷돌을 훔침 → 맷돌이 바닷속에 가라앉음 → 사람들이 시장에서 맷돌 이야기를 함","mis":"K1-2-u4-X05"},{"t":"맷돌이 바닷속에 가라앉음 → 사람들이 시장에서 맷돌 이야기를 함 → 도둑이 맷돌을 훔침","mis":"K1-2-u4-X05"}],"explanation":["시간을 나타내는 말과 누가 무엇을 했는지를 생각해요.","무슨 일 때문에 다음 일이 일어났는지도 떠올려요.","122쪽 (2)예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L06_challenge#1','kor',1,2,'u4','L06','g1_2_kor_u4_L06_challenge','lesson_challenge','K1-2-u4-C2',2,'mc','auto','도둑이 맷돌을 훔치기로 마음먹은 까닭은?',ARRAY['K1-2-u4-X02']::text[],false,'{"seq":1,"concept":"K1-2-u4-C2","difficulty":2,"kind":"mc","stem":"도둑이 맷돌을 훔치기로 마음먹은 까닭은?","options":[{"t":"맷돌이 있으면 부자가 될 수 있다고 생각해서","correct":true},{"t":"임금님이 맷돌을 주셔서","mis":"K1-2-u4-X02"},{"t":"맷돌이 무거워서","mis":"K1-2-u4-X02"}],"explanation":["‘그 맷돌이 있으면 부자가 될 수 있겠어.’라고 생각했어요.","고약한 마음을 먹었어요.","다섯째 줄이에요."],"asset":{"type":"passage","lines":["옛날 옛적에 어느 임금님이 신기한 맷돌을 가지고 있었습니다.","어느 날 아침, 사람들은 시장에 모여 신기한 맷돌에 대해 이야기를 했습니다.","“우리 임금님에게는 신기한 맷돌이 있다네.”","사람들 뒤에서 도둑이 그 말을 조용히 듣고 있었습니다.","‘그 맷돌이 있으면 부자가 될 수 있겠어.’","저녁이 되자 도둑은 궁궐로 숨어들었습니다.","그리고 깊은 밤, 모두 잠든 사이 몰래 맷돌을 훔쳐 도망갔습니다."],"title":"『국어』 118~119쪽 — 소금을 만드는 맷돌 (1)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L06_challenge#2','kor',1,2,'u4','L06','g1_2_kor_u4_L06_challenge','lesson_challenge','K1-2-u4-C3',2,'blank','auto','빈칸에 알맞은 따옴표는?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L06_challenge#3','kor',1,2,'u4','L06','g1_2_kor_u4_L06_challenge','lesson_challenge','K1-2-u4-C2',3,'error','auto','친구가 「시장」을 시간을 나타내는 말로 골랐어요. 무엇이 잘못되었나요?',ARRAY['K1-2-u4-X04']::text[],false,'{"seq":3,"concept":"K1-2-u4-C2","difficulty":3,"kind":"error","stem":"친구가 「시장」을 시간을 나타내는 말로 골랐어요. 무엇이 잘못되었나요?","options":[{"t":"「시장」은 곳을 나타내요 — 「어느 날 아침」이 시간을 나타내는 말이에요","correct":true,"mis_target":"K1-2-u4-X04"},{"t":"잘 골랐어요","mis":"K1-2-u4-X04"},{"t":"「맷돌」이 시간을 나타내는 말이에요","mis":"K1-2-u4-X04"}],"explanation":["「언제?」에 답이 되는 말이 시간을 나타내는 말이에요.","「시장에」는 「어디에서」의 답이에요.","122쪽이에요."],"asset":{"type":"passage","lines":["옛날 옛적에 어느 임금님이 신기한 맷돌을 가지고 있었습니다.","어느 날 아침, 사람들은 시장에 모여 신기한 맷돌에 대해 이야기를 했습니다.","“우리 임금님에게는 신기한 맷돌이 있다네.”","사람들 뒤에서 도둑이 그 말을 조용히 듣고 있었습니다.","‘그 맷돌이 있으면 부자가 될 수 있겠어.’","저녁이 되자 도둑은 궁궐로 숨어들었습니다.","그리고 깊은 밤, 모두 잠든 사이 몰래 맷돌을 훔쳐 도망갔습니다."],"title":"『국어』 118~119쪽 — 소금을 만드는 맷돌 (1)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L06_challenge#4','kor',1,2,'u4','L06','g1_2_kor_u4_L06_challenge','lesson_challenge','K1-2-u4-C3',3,'error','auto','‘그 맷돌이 있으면 부자가 될 수 있겠어.’를 큰따옴표로 고쳐 썼어요. 무엇이 잘못되었나요?',ARRAY['K1-2-u4-X06','K1-2-u4-X07']::text[],false,'{"seq":4,"concept":"K1-2-u4-C3","difficulty":3,"kind":"error","stem":"‘그 맷돌이 있으면 부자가 될 수 있겠어.’를 큰따옴표로 고쳐 썼어요. 무엇이 잘못되었나요?","options":[{"t":"마음속으로 한 말이라 작은따옴표를 써야 해요","correct":true,"mis_target":"K1-2-u4-X06"},{"t":"잘 고쳤어요","mis":"K1-2-u4-X06"},{"t":"따옴표를 아예 빼야 해요","mis":"K1-2-u4-X07"}],"explanation":["남들이 듣지 못하게 마음속으로 한 말이에요.","작은따옴표 ‘ ’를 써요.","123쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L06_challenge#5','kor',1,2,'u4','L06','g1_2_kor_u4_L06_challenge','lesson_challenge','K1-2-u4-C2',3,'mc','auto','바닷물이 짜게 된 까닭은?',ARRAY['K1-2-u4-X02']::text[],false,'{"seq":5,"concept":"K1-2-u4-C2","difficulty":3,"kind":"mc","stem":"바닷물이 짜게 된 까닭은?","options":[{"t":"바닷속에서도 맷돌이 쉬지 않고 소금을 만들어서","correct":true},{"t":"도둑이 소금을 뿌려서","mis":"K1-2-u4-X02"},{"t":"임금님이 소금을 버려서","mis":"K1-2-u4-X02"}],"explanation":["맷돌은 바닷속에서도 쉬지 않고 돌았어요.","그래서 바닷물이 짜게 되었어요.","마지막 줄이에요."],"asset":{"type":"passage","lines":["도둑은 배를 타고 바다를 건너다가 맷돌을 돌려 보고 싶어졌습니다.","“나와라, 소금!”","그러자 맷돌에서 하얀 소금이 쏟아져 나왔고, 점점 배 안에 쌓여 갔습니다.","배가 기우뚱거리기 시작했습니다.","도둑은 너무 놀라 무슨 말을 해야 하는지 잊어버렸습니다.","결국, 맷돌은 도둑과 함께 바닷속에 가라앉고 말았습니다.","바닷속에서도 맷돌은 쉬지 않고 돌았습니다. 그래서 바닷물이 짜게 되었습니다."],"title":"『국어』 120쪽 — 소금을 만드는 맷돌 (2)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L06_challenge#6','kor',1,2,'u4','L06','g1_2_kor_u4_L06_challenge','lesson_challenge','K1-2-u4-C2',3,'mc','auto','맷돌에서 소금이 계속 나오는데 도둑이 멈추지 못한 까닭은?',ARRAY['K1-2-u4-X02']::text[],false,'{"seq":6,"concept":"K1-2-u4-C2","difficulty":3,"kind":"mc","stem":"맷돌에서 소금이 계속 나오는데 도둑이 멈추지 못한 까닭은?","options":[{"t":"너무 놀라 멈추게 하는 말을 잊어버려서","correct":true},{"t":"소금을 더 갖고 싶어서","mis":"K1-2-u4-X02"},{"t":"맷돌이 고장 나서","mis":"K1-2-u4-X02"}],"explanation":["도둑은 무슨 말을 해야 하는지 잊어버렸어요.","그래서 배가 가라앉았어요.","다섯째 줄이에요."],"asset":{"type":"passage","lines":["도둑은 배를 타고 바다를 건너다가 맷돌을 돌려 보고 싶어졌습니다.","“나와라, 소금!”","그러자 맷돌에서 하얀 소금이 쏟아져 나왔고, 점점 배 안에 쌓여 갔습니다.","배가 기우뚱거리기 시작했습니다.","도둑은 너무 놀라 무슨 말을 해야 하는지 잊어버렸습니다.","결국, 맷돌은 도둑과 함께 바닷속에 가라앉고 말았습니다.","바닷속에서도 맷돌은 쉬지 않고 돌았습니다. 그래서 바닷물이 짜게 되었습니다."],"title":"『국어』 120쪽 — 소금을 만드는 맷돌 (2)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L06_challenge#7','kor',1,2,'u4','L06','g1_2_kor_u4_L06_challenge','lesson_challenge','K1-2-u4-C2',3,'match','auto','시간을 나타내는 말과 그때 일어난 일을 이어 보세요.','{}'::text[],false,'{"seq":7,"concept":"K1-2-u4-C2","difficulty":3,"kind":"match","stem":"시간을 나타내는 말과 그때 일어난 일을 이어 보세요.","pairs":[{"l":"어느 날 아침","r":"사람들이 시장에서 맷돌 이야기를 했다."},{"l":"저녁","r":"도둑이 궁궐로 숨어들었다."},{"l":"깊은 밤","r":"도둑이 몰래 맷돌을 훔쳐 도망갔다."}],"mis":"K1-2-u4-X05","explanation":["아침 → 저녁 → 깊은 밤 차례예요.","시간을 나타내는 말로 차례를 정리해요.","122쪽 1번이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L06_challenge#8','kor',1,2,'u4','L06','g1_2_kor_u4_L06_challenge','lesson_challenge','K1-2-u4-C2',4,'sa','auto','「도둑은 너무 놀라 무슨 말을 해야 하는지 잊어버렸습니다.」 — 도둑이 탄 것은 무엇인가요?','{}'::text[],false,'{"seq":8,"concept":"K1-2-u4-C2","difficulty":4,"kind":"sa","stem":"「도둑은 너무 놀라 무슨 말을 해야 하는지 잊어버렸습니다.」 — 도둑이 탄 것은 무엇인가요?","answer":["배"],"explanation":["도둑은 배를 타고 바다를 건넜어요.","소금이 쌓여 배가 기우뚱거렸어요.","120쪽이에요."],"asset":{"type":"passage","lines":["도둑은 배를 타고 바다를 건너다가 맷돌을 돌려 보고 싶어졌습니다.","“나와라, 소금!”","그러자 맷돌에서 하얀 소금이 쏟아져 나왔고, 점점 배 안에 쌓여 갔습니다.","배가 기우뚱거리기 시작했습니다.","도둑은 너무 놀라 무슨 말을 해야 하는지 잊어버렸습니다.","결국, 맷돌은 도둑과 함께 바닷속에 가라앉고 말았습니다.","바닷속에서도 맷돌은 쉬지 않고 돌았습니다. 그래서 바닷물이 짜게 되었습니다."],"title":"『국어』 120쪽 — 소금을 만드는 맷돌 (2)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L06_challenge#9','kor',1,2,'u4','L06','g1_2_kor_u4_L06_challenge','lesson_challenge','K1-2-u4-C2',4,'essay','teacher','「소금을 만드는 맷돌」에서 일어난 일을 시간을 나타내는 말을 넣어 두 문장으로 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K1-2-u4-C2","difficulty":4,"kind":"essay","stem":"「소금을 만드는 맷돌」에서 일어난 일을 시간을 나타내는 말을 넣어 두 문장으로 쓰세요.","answer_guide":{"answer":"예: 어느 날 아침, 사람들은 시장에서 맷돌 이야기를 했다. / 깊은 밤, 도둑은 맷돌을 훔쳐 도망갔다. — 시간을 나타내는 말과 일이 맞으면 맞아요.","scoring_points":["시간을 나타내는 말을 넣었는가","누가 무엇을 했는지 썼는가","차례가 맞는가"]},"explanation":["아침·저녁·깊은 밤을 찾아요.","그때 일어난 일을 함께 써요.","122쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L06_challenge#10','kor',1,2,'u4','L06','g1_2_kor_u4_L06_challenge','lesson_challenge','K1-2-u4-C3',4,'essay','teacher','「미역도 맛있어」나 「소금을 만드는 맷돌」에서 큰따옴표와 작은따옴표가 쓰인 문장을 하나씩 찾아 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K1-2-u4-C3","difficulty":4,"kind":"essay","stem":"「미역도 맛있어」나 「소금을 만드는 맷돌」에서 큰따옴표와 작은따옴표가 쓰인 문장을 하나씩 찾아 쓰세요.","answer_guide":{"answer":"예: 큰따옴표 — “나와라, 소금!” / 작은따옴표 — ‘그 맷돌이 있으면 부자가 될 수 있겠어.’ — 알맞게 하나씩 쓰면 맞아요.","scoring_points":["큰따옴표 문장을 바르게 찾았는가","작은따옴표 문장을 바르게 찾았는가","따옴표를 바르게 썼는가"]},"explanation":["소리 내어 한 말은 큰따옴표예요.","마음속 말은 작은따옴표예요.","123쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L08_basic#1','kor',1,2,'u4','L08','g1_2_kor_u4_L08_basic','lesson_basic','K1-2-u4-C4',1,'mc','auto','『국어』 124쪽 1번 — 「빨간 모자가 된 아이쿠」에 나오는 인물은?',ARRAY['K1-2-u4-X03']::text[],false,'{"seq":1,"concept":"K1-2-u4-C4","difficulty":1,"kind":"mc","stem":"『국어』 124쪽 1번 — 「빨간 모자가 된 아이쿠」에 나오는 인물은?","options":[{"t":"아이쿠","correct":true},{"t":"주원","mis":"K1-2-u4-X03"},{"t":"도둑","mis":"K1-2-u4-X03"}],"explanation":["아이쿠, 비비, 카르망 콩드 백작이 나와요.","주원과 도둑은 다른 이야기의 인물이에요.","124쪽 1번이에요."],"asset":{"type":"passage","lines":["아이쿠가 할머니 댁에 가기로 했어요.","아이쿠와 비비는 할머니께 꽃밭에서 꽃을 따 드리기로 했어요.","할머니 댁에서는 할머니로 변장한 카르망 콩드 백작이 기다리고 있었어요.","아이쿠는 변장한 백작을 할머니라고 부르며 꽃을 선물했어요.","꽃을 받은 백작은 몸이 가렵고 콧물을 흘리며 기침과 재채기를 했어요."],"title":"「빨간 모자가 된 아이쿠」 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L08_basic#2','kor',1,2,'u4','L08','g1_2_kor_u4_L08_basic','lesson_basic','K1-2-u4-C4',1,'mc','auto','『국어』 126쪽 3번 (1) — 아이쿠는 할머니께 무슨 선물을 드리려고 했나요?',ARRAY['K1-2-u4-X02']::text[],false,'{"seq":2,"concept":"K1-2-u4-C4","difficulty":1,"kind":"mc","stem":"『국어』 126쪽 3번 (1) — 아이쿠는 할머니께 무슨 선물을 드리려고 했나요?","options":[{"t":"꽃밭에서 딴 꽃","correct":true},{"t":"과자","mis":"K1-2-u4-X02"},{"t":"빨간 모자","mis":"K1-2-u4-X02"}],"explanation":["꽃밭에서 딴 꽃을 드리려고 했어요.","글에 없는 선물은 고르지 않아요.","둘째 줄이에요."],"asset":{"type":"passage","lines":["아이쿠가 할머니 댁에 가기로 했어요.","아이쿠와 비비는 할머니께 꽃밭에서 꽃을 따 드리기로 했어요.","할머니 댁에서는 할머니로 변장한 카르망 콩드 백작이 기다리고 있었어요.","아이쿠는 변장한 백작을 할머니라고 부르며 꽃을 선물했어요.","꽃을 받은 백작은 몸이 가렵고 콧물을 흘리며 기침과 재채기를 했어요."],"title":"「빨간 모자가 된 아이쿠」 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L08_basic#3','kor',1,2,'u4','L08','g1_2_kor_u4_L08_basic','lesson_basic','K1-2-u4-C4',1,'mc','auto','할머니 댁에서 아이쿠를 기다리고 있던 것은?',ARRAY['K1-2-u4-X02']::text[],false,'{"seq":3,"concept":"K1-2-u4-C4","difficulty":1,"kind":"mc","stem":"할머니 댁에서 아이쿠를 기다리고 있던 것은?","options":[{"t":"할머니로 변장한 카르망 콩드 백작","correct":true},{"t":"비비","mis":"K1-2-u4-X02"},{"t":"진짜 할머니","mis":"K1-2-u4-X02"}],"explanation":["백작이 할머니로 변장하고 기다리고 있었어요.","비비는 아이쿠와 함께 왔어요.","셋째 줄이에요."],"asset":{"type":"passage","lines":["아이쿠가 할머니 댁에 가기로 했어요.","아이쿠와 비비는 할머니께 꽃밭에서 꽃을 따 드리기로 했어요.","할머니 댁에서는 할머니로 변장한 카르망 콩드 백작이 기다리고 있었어요.","아이쿠는 변장한 백작을 할머니라고 부르며 꽃을 선물했어요.","꽃을 받은 백작은 몸이 가렵고 콧물을 흘리며 기침과 재채기를 했어요."],"title":"「빨간 모자가 된 아이쿠」 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L08_basic#4','kor',1,2,'u4','L08','g1_2_kor_u4_L08_basic','lesson_basic','K1-2-u4-C4',1,'mc','auto','만화 영화를 볼 때 자세히 살펴볼 것은?',ARRAY['K1-2-u4-X08']::text[],false,'{"seq":4,"concept":"K1-2-u4-C4","difficulty":1,"kind":"mc","stem":"만화 영화를 볼 때 자세히 살펴볼 것은?","options":[{"t":"인물의 표정과 몸짓","correct":true},{"t":"화면의 색깔 수","mis":"K1-2-u4-X08"},{"t":"영상의 길이","mis":"K1-2-u4-X08"}],"explanation":["인물의 말과 행동, 표정과 몸짓을 살펴봐요.","색깔 수나 길이는 이야기가 아니에요.","125쪽 도움말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L08_basic#5','kor',1,2,'u4','L08','g1_2_kor_u4_L08_basic','lesson_basic','K1-2-u4-C4',2,'mc','auto','『국어』 126쪽 3번 (2) — 꽃을 선물받은 카르망 콩드 백작에게 어떤 일이 일어났나요?',ARRAY['K1-2-u4-X02']::text[],false,'{"seq":5,"concept":"K1-2-u4-C4","difficulty":2,"kind":"mc","stem":"『국어』 126쪽 3번 (2) — 꽃을 선물받은 카르망 콩드 백작에게 어떤 일이 일어났나요?","options":[{"t":"몸이 가렵고 콧물·기침·재채기가 났어요","correct":true},{"t":"아주 기뻐하며 춤을 추었어요","mis":"K1-2-u4-X02"},{"t":"꽃 냄새를 맡고 잠이 들었어요","mis":"K1-2-u4-X02"}],"explanation":["꽃을 받자 이상한 반응이 생겼어요.","글에 없는 일은 고르지 않아요.","마지막 줄이에요."],"asset":{"type":"passage","lines":["아이쿠가 할머니 댁에 가기로 했어요.","아이쿠와 비비는 할머니께 꽃밭에서 꽃을 따 드리기로 했어요.","할머니 댁에서는 할머니로 변장한 카르망 콩드 백작이 기다리고 있었어요.","아이쿠는 변장한 백작을 할머니라고 부르며 꽃을 선물했어요.","꽃을 받은 백작은 몸이 가렵고 콧물을 흘리며 기침과 재채기를 했어요."],"title":"「빨간 모자가 된 아이쿠」 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L08_basic#6','kor',1,2,'u4','L08','g1_2_kor_u4_L08_basic','lesson_basic','K1-2-u4-C4',2,'mc','auto','아이쿠가 카르망 콩드 백작을 할머니라고 부른 까닭은?',ARRAY['K1-2-u4-X02']::text[],false,'{"seq":6,"concept":"K1-2-u4-C4","difficulty":2,"kind":"mc","stem":"아이쿠가 카르망 콩드 백작을 할머니라고 부른 까닭은?","options":[{"t":"백작이 할머니로 변장하고 있어서","correct":true},{"t":"백작이 진짜 할머니라서","mis":"K1-2-u4-X02"},{"t":"비비가 그렇게 부르라고 해서","mis":"K1-2-u4-X02"}],"explanation":["백작이 할머니로 변장해 아이쿠가 속았어요.","글에 없는 까닭은 고르지 않아요.","셋째·넷째 줄이에요."],"asset":{"type":"passage","lines":["아이쿠가 할머니 댁에 가기로 했어요.","아이쿠와 비비는 할머니께 꽃밭에서 꽃을 따 드리기로 했어요.","할머니 댁에서는 할머니로 변장한 카르망 콩드 백작이 기다리고 있었어요.","아이쿠는 변장한 백작을 할머니라고 부르며 꽃을 선물했어요.","꽃을 받은 백작은 몸이 가렵고 콧물을 흘리며 기침과 재채기를 했어요."],"title":"「빨간 모자가 된 아이쿠」 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L08_basic#7','kor',1,2,'u4','L08','g1_2_kor_u4_L08_basic','lesson_basic','K1-2-u4-C4',2,'match','auto','『국어』 127쪽 5번 — 있었던 일을 차례대로 이어 보세요.','{}'::text[],false,'{"seq":7,"concept":"K1-2-u4-C4","difficulty":2,"kind":"match","stem":"『국어』 127쪽 5번 — 있었던 일을 차례대로 이어 보세요.","pairs":[{"l":"①","r":"아이쿠가 할머니 댁에 가기로 했다."},{"l":"②","r":"아이쿠와 비비가 할머니께 꽃을 따 드리기로 했다."},{"l":"③","r":"아이쿠가 할머니로 변장한 백작을 만났다."},{"l":"④","r":"꽃을 선물받은 백작에게 이상한 반응이 생겼다."}],"mis":"K1-2-u4-X05","explanation":["있었던 일을 차례대로 정리해요.","그림을 보며 앞부분을 떠올려요.","127쪽 5번이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L08_basic#8','kor',1,2,'u4','L08','g1_2_kor_u4_L08_basic','lesson_basic','K1-2-u4-C4',2,'mc','auto','만화 영화가 책과 다른 점은?',ARRAY['K1-2-u4-X08']::text[],false,'{"seq":8,"concept":"K1-2-u4-C4","difficulty":2,"kind":"mc","stem":"만화 영화가 책과 다른 점은?","options":[{"t":"움직이는 영상과 소리로 이야기를 전해요","correct":true},{"t":"글자로만 이야기를 전해요","mis":"K1-2-u4-X08"},{"t":"이야기가 없어요","mis":"K1-2-u4-X08"}],"explanation":["만화 영화는 영상과 소리, 인물의 말투와 표정으로 이야기를 전해요.","그래서 보면서 내용을 알 수 있어요.","지도서 191쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L08_basic#9','kor',1,2,'u4','L08','g1_2_kor_u4_L08_basic','lesson_basic','K1-2-u4-C5',2,'ox','auto','『국어』 126쪽 4번 — 재미있었던 장면은 친구마다 다를 수 있어요.',ARRAY['K1-2-u4-X12']::text[],false,'{"seq":9,"concept":"K1-2-u4-C5","difficulty":2,"kind":"ox","stem":"『국어』 126쪽 4번 — 재미있었던 장면은 친구마다 다를 수 있어요.","answer":"O","reason_options":[{"t":"사람마다 재미를 느끼는 장면이 다르니까","correct":true},{"t":"재미있는 장면은 하나로 정해져 있으니까","mis":"K1-2-u4-X12"}],"mis":"K1-2-u4-X12","explanation":["간식 먹는 장면, 할머니라고 부르는 장면처럼 저마다 달라요.","서로 존중하며 들어요.","126쪽 4번이에요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"아이쿠가 간식을 먹는 장면이 재미있었어."},{"who":"친구 2","text":"아이쿠가 백작을 할머니라고 부르는 장면이 기억에 남았어."},{"who":"친구 3","text":"백작이 뛰어나가는 장면이 재미있었어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L08_basic#10','kor',1,2,'u4','L08','g1_2_kor_u4_L08_basic','lesson_basic','K1-2-u4-C4',3,'mc','auto','만화 영화에서 있었던 일을 정리할 때 먼저 할 일은?',ARRAY['K1-2-u4-X08']::text[],false,'{"seq":10,"concept":"K1-2-u4-C4","difficulty":3,"kind":"mc","stem":"만화 영화에서 있었던 일을 정리할 때 먼저 할 일은?","options":[{"t":"누가 나오는지 알아보기","correct":true},{"t":"영상 길이 재기","mis":"K1-2-u4-X08"},{"t":"제일 좋아하는 색 찾기","mis":"K1-2-u4-X08"}],"explanation":["누가 나오는지 알아야 누가 무엇을 했는지 알 수 있어요.","이것이 있었던 일을 아는 기본이에요.","지도서 189쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L08_challenge#1','kor',1,2,'u4','L08','g1_2_kor_u4_L08_challenge','lesson_challenge','K1-2-u4-C4',2,'mc','auto','「빨간 모자가 된 아이쿠」에 나오지 않는 인물은?',ARRAY['K1-2-u4-X03']::text[],false,'{"seq":1,"concept":"K1-2-u4-C4","difficulty":2,"kind":"mc","stem":"「빨간 모자가 된 아이쿠」에 나오지 않는 인물은?","options":[{"t":"엄마 까투리","correct":true},{"t":"비비","mis":"K1-2-u4-X03"},{"t":"카르망 콩드 백작","mis":"K1-2-u4-X03"}],"explanation":["엄마 까투리는 다른 만화 영화에 나와요.","아이쿠·비비·백작이 나와요.","124쪽 1번이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L08_challenge#2','kor',1,2,'u4','L08','g1_2_kor_u4_L08_challenge','lesson_challenge','K1-2-u4-C4',2,'blank','auto','빈칸에 알맞은 말은?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L08_challenge#3','kor',1,2,'u4','L08','g1_2_kor_u4_L08_challenge','lesson_challenge','K1-2-u4-C4',3,'error','auto','친구가 「아이쿠가 진짜 할머니께 꽃을 드렸다.」라고 정리했어요. 무엇이 잘못되었나요?',ARRAY['K1-2-u4-X02']::text[],false,'{"seq":3,"concept":"K1-2-u4-C4","difficulty":3,"kind":"error","stem":"친구가 「아이쿠가 진짜 할머니께 꽃을 드렸다.」라고 정리했어요. 무엇이 잘못되었나요?","options":[{"t":"꽃을 받은 것은 할머니로 변장한 카르망 콩드 백작이에요","correct":true,"mis_target":"K1-2-u4-X02"},{"t":"잘 정리했어요","mis":"K1-2-u4-X02"},{"t":"비비가 꽃을 받았어요","mis":"K1-2-u4-X02"}],"explanation":["백작이 할머니로 변장하고 있었어요.","인물이 한 일을 바꾸지 않아요.","넷째 줄이에요."],"asset":{"type":"passage","lines":["아이쿠가 할머니 댁에 가기로 했어요.","아이쿠와 비비는 할머니께 꽃밭에서 꽃을 따 드리기로 했어요.","할머니 댁에서는 할머니로 변장한 카르망 콩드 백작이 기다리고 있었어요.","아이쿠는 변장한 백작을 할머니라고 부르며 꽃을 선물했어요.","꽃을 받은 백작은 몸이 가렵고 콧물을 흘리며 기침과 재채기를 했어요."],"title":"「빨간 모자가 된 아이쿠」 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L08_challenge#4','kor',1,2,'u4','L08','g1_2_kor_u4_L08_challenge','lesson_challenge','K1-2-u4-C4',3,'error','auto','있었던 일을 「꽃을 따 드리기로 했다.」라고만 썼어요. 무엇이 빠졌나요?',ARRAY['K1-2-u4-X09','K1-2-u4-X08']::text[],false,'{"seq":4,"concept":"K1-2-u4-C4","difficulty":3,"kind":"error","stem":"있었던 일을 「꽃을 따 드리기로 했다.」라고만 썼어요. 무엇이 빠졌나요?","options":[{"t":"누가 했는지가 빠졌어요 — 「아이쿠와 비비가」를 넣어요","correct":true,"mis_target":"K1-2-u4-X09"},{"t":"잘 썼어요","mis":"K1-2-u4-X09"},{"t":"색깔을 넣어야 해요","mis":"K1-2-u4-X08"}],"explanation":["누가 무엇을 했는지 함께 써요.","누가가 빠지면 누구 일인지 몰라요.","127쪽 5번이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L08_challenge#5','kor',1,2,'u4','L08','g1_2_kor_u4_L08_challenge','lesson_challenge','K1-2-u4-C4',3,'error','auto','만화 영화를 본 뒤 「화면이 몇 가지 색이었는지」를 정리했어요. 무엇이 잘못되었나요?',ARRAY['K1-2-u4-X08']::text[],false,'{"seq":5,"concept":"K1-2-u4-C4","difficulty":3,"kind":"error","stem":"만화 영화를 본 뒤 「화면이 몇 가지 색이었는지」를 정리했어요. 무엇이 잘못되었나요?","options":[{"t":"이야기와 상관없어요 — 누가 무엇을 했는지 정리해요","correct":true,"mis_target":"K1-2-u4-X08"},{"t":"잘 정리했어요","mis":"K1-2-u4-X08"},{"t":"영상 길이도 써야 해요","mis":"K1-2-u4-X08"}],"explanation":["색깔 수로는 있었던 일을 알 수 없어요.","인물과 인물이 한 일을 정리해요.","지도서 189쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L08_challenge#6','kor',1,2,'u4','L08','g1_2_kor_u4_L08_challenge','lesson_challenge','K1-2-u4-C4',3,'mc','auto','인물의 말과 행동을 따라 해 볼 때 함께 살리면 좋은 것은?',ARRAY['K1-2-u4-X01','K1-2-u4-X08']::text[],false,'{"seq":6,"concept":"K1-2-u4-C4","difficulty":3,"kind":"mc","stem":"인물의 말과 행동을 따라 해 볼 때 함께 살리면 좋은 것은?","options":[{"t":"목소리의 높낮이, 표정과 몸짓","correct":true},{"t":"옷 색깔","mis":"K1-2-u4-X01"},{"t":"영상 길이","mis":"K1-2-u4-X08"}],"explanation":["말투와 표정, 몸짓은 만화 영화의 특징이에요.","따라 하면 더 실감 나요.","지도서 190쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L08_challenge#7','kor',1,2,'u4','L08','g1_2_kor_u4_L08_challenge','lesson_challenge','K1-2-u4-C4',3,'match','auto','인물과 한 일을 이어 보세요.','{}'::text[],false,'{"seq":7,"concept":"K1-2-u4-C4","difficulty":3,"kind":"match","stem":"인물과 한 일을 이어 보세요.","pairs":[{"l":"아이쿠","r":"변장한 백작을 할머니라고 부르며 꽃을 선물했다."},{"l":"카르망 콩드 백작","r":"할머니로 변장하고 기다렸다."}],"mis":"K1-2-u4-X02","explanation":["누가 무엇을 했는지 이어요.","인물이 한 일을 바꾸지 않아요.","126쪽 3번이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L08_challenge#8','kor',1,2,'u4','L08','g1_2_kor_u4_L08_challenge','lesson_challenge','K1-2-u4-C4',4,'sa','auto','아이쿠와 함께 꽃을 따러 간 로봇의 이름을 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K1-2-u4-C4","difficulty":4,"kind":"sa","stem":"아이쿠와 함께 꽃을 따러 간 로봇의 이름을 쓰세요.","answer":["비비"],"explanation":["비비는 아이쿠 왕자의 로봇이에요.","아이쿠와 함께 꽃을 땄어요.","124쪽 1번이에요."],"asset":{"type":"passage","lines":["아이쿠가 할머니 댁에 가기로 했어요.","아이쿠와 비비는 할머니께 꽃밭에서 꽃을 따 드리기로 했어요.","할머니 댁에서는 할머니로 변장한 카르망 콩드 백작이 기다리고 있었어요.","아이쿠는 변장한 백작을 할머니라고 부르며 꽃을 선물했어요.","꽃을 받은 백작은 몸이 가렵고 콧물을 흘리며 기침과 재채기를 했어요."],"title":"「빨간 모자가 된 아이쿠」 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L08_challenge#9','kor',1,2,'u4','L08','g1_2_kor_u4_L08_challenge','lesson_challenge','K1-2-u4-C4',4,'essay','teacher','「빨간 모자가 된 아이쿠」에서 있었던 일을 「누가 무엇을 했다」 문장 세 개로 차례대로 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K1-2-u4-C4","difficulty":4,"kind":"essay","stem":"「빨간 모자가 된 아이쿠」에서 있었던 일을 「누가 무엇을 했다」 문장 세 개로 차례대로 쓰세요.","answer_guide":{"answer":"예: 아이쿠가 할머니 댁에 가기로 했다. / 아이쿠와 비비가 꽃을 땄다. / 아이쿠가 변장한 백작을 만났다. — 차례와 누가 무엇을이 맞으면 맞아요.","scoring_points":["누가 무엇을 했는지 썼는가","차례가 맞는가","있었던 일만 썼는가"]},"explanation":["127쪽 5번을 떠올려요.","먼저 있었던 일부터 써요.","지도서 191쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L08_challenge#10','kor',1,2,'u4','L08','g1_2_kor_u4_L08_challenge','lesson_challenge','K1-2-u4-C5',4,'essay','teacher','『국어』 126쪽 4번 — 「빨간 모자가 된 아이쿠」에서 재미있었던 장면과 그 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K1-2-u4-C5","difficulty":4,"kind":"essay","stem":"『국어』 126쪽 4번 — 「빨간 모자가 된 아이쿠」에서 재미있었던 장면과 그 까닭을 쓰세요.","answer_guide":{"answer":"예: 아이쿠가 백작을 할머니라고 부르는 장면이 재미있었다. 진짜 할머니가 아닌 줄 모르고 꽃을 주는 모습이 웃겼다. — 장면과 까닭이 있으면 맞아요.","scoring_points":["어떤 장면인지 썼는가","까닭을 썼는가","내 말로 썼는가"]},"explanation":["어떤 장면이 왜 재미있었는지 써요.","친구와 달라도 괜찮아요.","126쪽 4번이에요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"아이쿠가 간식을 먹는 장면이 재미있었어."},{"who":"친구 2","text":"아이쿠가 백작을 할머니라고 부르는 장면이 기억에 남았어."},{"who":"친구 3","text":"백작이 뛰어나가는 장면이 재미있었어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L10_basic#1','kor',1,2,'u4','L10','g1_2_kor_u4_L10_basic','lesson_basic','K1-2-u4-C5',1,'mc','auto','『국어』 129쪽 (1) — 「아기 거북이가 숲으로 왔어요!」의 등장인물은?',ARRAY['K1-2-u4-X03']::text[],false,'{"seq":1,"concept":"K1-2-u4-C5","difficulty":1,"kind":"mc","stem":"『국어』 129쪽 (1) — 「아기 거북이가 숲으로 왔어요!」의 등장인물은?","options":[{"t":"엄마 까투리","correct":true},{"t":"아이쿠","mis":"K1-2-u4-X03"},{"t":"양치기 소년","mis":"K1-2-u4-X03"}],"explanation":["엄마 까투리, 마지, 두리, 세찌, 꽁지, 아기 거북이 나와요.","아이쿠와 양치기 소년은 다른 이야기예요.","129쪽 내용 알기예요."],"asset":{"type":"passage","lines":["꽁지가 모래 구덩이에서 거북알을 발견했어요.","한 아기 거북은 혼자 늦게 알에서 깨어났어요.","아기 거북은 까투리 가족을 따라 숲속 집으로 갔어요.","아기 거북과 마지, 두리, 세찌, 꽁지는 미끄럼틀도 타고 공놀이도 했어요.","마침내 아기 거북은 다시 가족을 만났어요."],"title":"「아기 거북이가 숲으로 왔어요!」 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L10_basic#2','kor',1,2,'u4','L10','g1_2_kor_u4_L10_basic','lesson_basic','K1-2-u4-C5',1,'mc','auto','꽁지는 모래 구덩이에서 무엇을 발견했나요?',ARRAY['K1-2-u4-X02']::text[],false,'{"seq":2,"concept":"K1-2-u4-C5","difficulty":1,"kind":"mc","stem":"꽁지는 모래 구덩이에서 무엇을 발견했나요?","options":[{"t":"거북알","correct":true},{"t":"맷돌","mis":"K1-2-u4-X02"},{"t":"꽃","mis":"K1-2-u4-X02"}],"explanation":["꽁지가 거북알을 발견했어요.","글에 없는 것은 고르지 않아요.","첫째 줄이에요."],"asset":{"type":"passage","lines":["꽁지가 모래 구덩이에서 거북알을 발견했어요.","한 아기 거북은 혼자 늦게 알에서 깨어났어요.","아기 거북은 까투리 가족을 따라 숲속 집으로 갔어요.","아기 거북과 마지, 두리, 세찌, 꽁지는 미끄럼틀도 타고 공놀이도 했어요.","마침내 아기 거북은 다시 가족을 만났어요."],"title":"「아기 거북이가 숲으로 왔어요!」 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L10_basic#3','kor',1,2,'u4','L10','g1_2_kor_u4_L10_basic','lesson_basic','K1-2-u4-C5',1,'mc','auto','『국어』 129쪽 (3) — 아기 거북과 꺼병이들은 무엇을 하고 놀았나요?',ARRAY['K1-2-u4-X02']::text[],false,'{"seq":3,"concept":"K1-2-u4-C5","difficulty":1,"kind":"mc","stem":"『국어』 129쪽 (3) — 아기 거북과 꺼병이들은 무엇을 하고 놀았나요?","options":[{"t":"미끄럼틀 타기, 공놀이","correct":true},{"t":"수영 대회","mis":"K1-2-u4-X02"},{"t":"책 읽기","mis":"K1-2-u4-X02"}],"explanation":["미끄럼틀도 타고 공놀이도 했어요.","글에 없는 놀이는 고르지 않아요.","넷째 줄이에요."],"asset":{"type":"passage","lines":["꽁지가 모래 구덩이에서 거북알을 발견했어요.","한 아기 거북은 혼자 늦게 알에서 깨어났어요.","아기 거북은 까투리 가족을 따라 숲속 집으로 갔어요.","아기 거북과 마지, 두리, 세찌, 꽁지는 미끄럼틀도 타고 공놀이도 했어요.","마침내 아기 거북은 다시 가족을 만났어요."],"title":"「아기 거북이가 숲으로 왔어요!」 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L10_basic#4','kor',1,2,'u4','L10','g1_2_kor_u4_L10_basic','lesson_basic','K1-2-u4-C5',1,'mc','auto','『국어』 129쪽 낱말 알기 — 「꺼병이」의 뜻은?',ARRAY['K1-2-u4-X02']::text[],false,'{"seq":4,"concept":"K1-2-u4-C5","difficulty":1,"kind":"mc","stem":"『국어』 129쪽 낱말 알기 — 「꺼병이」의 뜻은?","options":[{"t":"꿩의 어린 새끼","correct":true},{"t":"땅이 움푹하게 파인 곳","mis":"K1-2-u4-X02"},{"t":"맨 나중에 난 사람","mis":"K1-2-u4-X02"}],"explanation":["꺼병이는 꿩의 어린 새끼예요.","구덩이와 막내의 뜻과 헷갈리지 않아요.","129쪽 낱말 알기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L10_basic#5','kor',1,2,'u4','L10','g1_2_kor_u4_L10_basic','lesson_basic','K1-2-u4-C5',2,'match','auto','『국어』 129쪽 낱말 알기 — 낱말과 뜻을 이어 보세요.','{}'::text[],false,'{"seq":5,"concept":"K1-2-u4-C5","difficulty":2,"kind":"match","stem":"『국어』 129쪽 낱말 알기 — 낱말과 뜻을 이어 보세요.","pairs":[{"l":"구덩이","r":"땅이 움푹하게 파인 곳."},{"l":"꺼병이","r":"꿩의 어린 새끼."},{"l":"막내","r":"여러 형제, 자매 가운데에서 맨 나중에 난 사람."}],"mis":"K1-2-u4-X02","explanation":["구덩이·꺼병이·막내예요.","꽁지는 꺼병이 사 남매의 막내예요.","129쪽 낱말 알기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L10_basic#6','kor',1,2,'u4','L10','g1_2_kor_u4_L10_basic','lesson_basic','K1-2-u4-C5',2,'mc','auto','『국어』 129쪽 (2) — 아기 거북은 왜 혼자 까투리 가족의 집으로 오게 되었나요?',ARRAY['K1-2-u4-X02']::text[],false,'{"seq":6,"concept":"K1-2-u4-C5","difficulty":2,"kind":"mc","stem":"『국어』 129쪽 (2) — 아기 거북은 왜 혼자 까투리 가족의 집으로 오게 되었나요?","options":[{"t":"혼자 뒤늦게 알에서 깨어났기 때문이에요","correct":true},{"t":"까투리 집이 더 좋아서예요","mis":"K1-2-u4-X02"},{"t":"바다가 너무 추워서예요","mis":"K1-2-u4-X02"}],"explanation":["혼자 늦게 깨어나 가족과 떨어졌어요.","그래서 까투리 가족을 따라갔어요.","둘째·셋째 줄이에요."],"asset":{"type":"passage","lines":["꽁지가 모래 구덩이에서 거북알을 발견했어요.","한 아기 거북은 혼자 늦게 알에서 깨어났어요.","아기 거북은 까투리 가족을 따라 숲속 집으로 갔어요.","아기 거북과 마지, 두리, 세찌, 꽁지는 미끄럼틀도 타고 공놀이도 했어요.","마침내 아기 거북은 다시 가족을 만났어요."],"title":"「아기 거북이가 숲으로 왔어요!」 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
