INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L10_basic#8','kor',1,2,'u4','L10','g1_2_kor_u4_L10_basic','lesson_basic','K1-2-u4-C5',2,'mc','auto','『국어』 131쪽 — 감동적인 장면을 말한 것은?',ARRAY['K1-2-u4-X13','K1-2-u4-X10']::text[],false,'{"seq":8,"concept":"K1-2-u4-C5","difficulty":2,"kind":"mc","stem":"『국어』 131쪽 — 감동적인 장면을 말한 것은?","options":[{"t":"아기 거북이 다시 가족을 만나는 장면이 감동적이야","correct":true},{"t":"만화 영화가 몇 분이었는지가 감동적이야","mis":"K1-2-u4-X13"},{"t":"감동적이었어.","mis":"K1-2-u4-X10"}],"explanation":["어떤 장면인지 말했어요.","한마디나 길이로는 감동을 전하기 어려워요.","131쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L10_basic#9','kor',1,2,'u4','L10','g1_2_kor_u4_L10_basic','lesson_basic','K1-2-u4-C5',2,'ox','auto','감동적인 장면을 찾을 때 친구와 생각이 다르면 내 생각을 바꿔야 해요.',ARRAY['K1-2-u4-X12']::text[],false,'{"seq":9,"concept":"K1-2-u4-C5","difficulty":2,"kind":"ox","stem":"감동적인 장면을 찾을 때 친구와 생각이 다르면 내 생각을 바꿔야 해요.","answer":"X","reason_options":[{"t":"사람마다 감동을 느끼는 장면이 다를 수 있으니까","correct":true},{"t":"모두 같은 장면에서 감동해야 하니까","mis":"K1-2-u4-X12"}],"mis":"K1-2-u4-X12","explanation":["서로 다른 생각을 존중해요.","감동을 느낀 부분이 달라서 더 재미있어요.","지도서 195쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L10_basic#10','kor',1,2,'u4','L10','g1_2_kor_u4_L10_basic','lesson_basic','K1-2-u4-C5',3,'mc','auto','『국어』 130쪽 — 일어난 일의 차례로 알맞은 것은?',ARRAY['K1-2-u4-X05']::text[],false,'{"seq":10,"concept":"K1-2-u4-C5","difficulty":3,"kind":"mc","stem":"『국어』 130쪽 — 일어난 일의 차례로 알맞은 것은?","options":[{"t":"거북알 발견 → 까투리 가족을 따라감 → 함께 놀았음 → 다시 가족을 만남","correct":true},{"t":"다시 가족을 만남 → 거북알 발견 → 함께 놀았음 → 까투리 가족을 따라감","mis":"K1-2-u4-X05"},{"t":"함께 놀았음 → 거북알 발견 → 다시 가족을 만남 → 까투리 가족을 따라감","mis":"K1-2-u4-X05"}],"explanation":["일어난 일을 차례대로 정리해요.","먼저 있었던 일부터 늘어놓아요.","130쪽이에요."],"asset":{"type":"passage","lines":["꽁지가 모래 구덩이에서 거북알을 발견했어요.","한 아기 거북은 혼자 늦게 알에서 깨어났어요.","아기 거북은 까투리 가족을 따라 숲속 집으로 갔어요.","아기 거북과 마지, 두리, 세찌, 꽁지는 미끄럼틀도 타고 공놀이도 했어요.","마침내 아기 거북은 다시 가족을 만났어요."],"title":"「아기 거북이가 숲으로 왔어요!」 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L10_challenge#1','kor',1,2,'u4','L10','g1_2_kor_u4_L10_challenge','lesson_challenge','K1-2-u4-C5',2,'mc','auto','까투리 가족이 아기 거북에게 한 일로 알맞은 것은?',ARRAY['K1-2-u4-X02']::text[],false,'{"seq":1,"concept":"K1-2-u4-C5","difficulty":2,"kind":"mc","stem":"까투리 가족이 아기 거북에게 한 일로 알맞은 것은?","options":[{"t":"친절하게 대해 주고 재미있게 놀아 주었어요","correct":true},{"t":"아기 거북을 쫓아냈어요","mis":"K1-2-u4-X02"},{"t":"아기 거북을 모른 척했어요","mis":"K1-2-u4-X02"}],"explanation":["꺼병이들은 아기 거북을 동생처럼 대해 주었어요.","그래서 감동적이라는 친구가 많아요.","지도서 195쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L10_challenge#2','kor',1,2,'u4','L10','g1_2_kor_u4_L10_challenge','lesson_challenge','K1-2-u4-C5',2,'mc','auto','「꺼병이들이 아기 거북을 동생처럼 대해 주던 장면이 재미있었어.」를 말한 친구가 잘한 점은?',ARRAY['K1-2-u4-X11','K1-2-u4-X13']::text[],false,'{"seq":2,"concept":"K1-2-u4-C5","difficulty":2,"kind":"mc","stem":"「꺼병이들이 아기 거북을 동생처럼 대해 주던 장면이 재미있었어.」를 말한 친구가 잘한 점은?","options":[{"t":"어떤 장면인지 인물이 한 일로 말했어요","correct":true},{"t":"친구 말을 따라 했어요","mis":"K1-2-u4-X11"},{"t":"영상 길이를 말했어요","mis":"K1-2-u4-X13"}],"explanation":["인물이 한 일이 들어 있어요.","그래서 친구도 장면을 떠올려요.","131쪽 예시예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L10_challenge#3','kor',1,2,'u4','L10','g1_2_kor_u4_L10_challenge','lesson_challenge','K1-2-u4-C5',3,'error','auto','친구가 「감동적이었어.」라고만 말했어요. 무엇이 부족한가요?',ARRAY['K1-2-u4-X10','K1-2-u4-X01']::text[],false,'{"seq":3,"concept":"K1-2-u4-C5","difficulty":3,"kind":"error","stem":"친구가 「감동적이었어.」라고만 말했어요. 무엇이 부족한가요?","options":[{"t":"어떤 장면이 왜 감동적이었는지가 빠졌어요","correct":true,"mis_target":"K1-2-u4-X10"},{"t":"잘 말했어요","mis":"K1-2-u4-X10"},{"t":"더 크게 말해야 해요","mis":"K1-2-u4-X01"}],"explanation":["어떤 장면인지와 까닭을 말해요.","한마디로 끝내지 않아요.","지도서 195쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L10_challenge#4','kor',1,2,'u4','L10','g1_2_kor_u4_L10_challenge','lesson_challenge','K1-2-u4-C5',3,'error','auto','친구가 고른 장면이 나와 달라서 「그건 감동적이지 않아.」라고 했어요. 무엇이 잘못되었나요?',ARRAY['K1-2-u4-X12']::text[],false,'{"seq":4,"concept":"K1-2-u4-C5","difficulty":3,"kind":"error","stem":"친구가 고른 장면이 나와 달라서 「그건 감동적이지 않아.」라고 했어요. 무엇이 잘못되었나요?","options":[{"t":"사람마다 감동을 느끼는 장면이 달라요 — 친구 생각을 존중해요","correct":true,"mis_target":"K1-2-u4-X12"},{"t":"잘 말했어요","mis":"K1-2-u4-X12"},{"t":"친구 장면을 고쳐 줘야 해요","mis":"K1-2-u4-X12"}],"explanation":["다른 생각도 틀린 것이 아니에요.","왜 그 장면인지 물어봐요.","지도서 177쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L10_challenge#5','kor',1,2,'u4','L10','g1_2_kor_u4_L10_challenge','lesson_challenge','K1-2-u4-C5',3,'error','auto','감동적인 까닭을 「화면 색깔이 예뻐서」라고 했어요. 무엇이 아쉬운가요?',ARRAY['K1-2-u4-X13']::text[],false,'{"seq":5,"concept":"K1-2-u4-C5","difficulty":3,"kind":"error","stem":"감동적인 까닭을 「화면 색깔이 예뻐서」라고 했어요. 무엇이 아쉬운가요?","options":[{"t":"까닭을 인물이 한 말이나 행동에서 찾아요","correct":true,"mis_target":"K1-2-u4-X13"},{"t":"잘 말했어요","mis":"K1-2-u4-X13"},{"t":"영상이 길어서라고 해야 해요","mis":"K1-2-u4-X13"}],"explanation":["인물이 무엇을 했길래 마음이 움직였는지 말해요.","색깔은 이야기가 아니에요.","지도서 195쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L10_challenge#6','kor',1,2,'u4','L10','g1_2_kor_u4_L10_challenge','lesson_challenge','K1-2-u4-C5',3,'mc','auto','『국어』 131쪽 자신과 관련짓기 — 아기 거북처럼 가족과 떨어져 혼자 있을 때 알맞은 생각은?',ARRAY['K1-2-u4-X02']::text[],false,'{"seq":6,"concept":"K1-2-u4-C5","difficulty":3,"kind":"mc","stem":"『국어』 131쪽 자신과 관련짓기 — 아기 거북처럼 가족과 떨어져 혼자 있을 때 알맞은 생각은?","options":[{"t":"주변 어른께 도움을 청하고 가족을 기다려요","correct":true},{"t":"아무도 모르게 멀리 가요","mis":"K1-2-u4-X02"},{"t":"모르는 사람을 따라가요","mis":"K1-2-u4-X02"}],"explanation":["혼자일 때에는 믿을 수 있는 어른께 도움을 청해요.","나라면 어떻게 했을지 생각해 봐요.","131쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L10_challenge#7','kor',1,2,'u4','L10','g1_2_kor_u4_L10_challenge','lesson_challenge','K1-2-u4-C5',3,'match','auto','「아기 거북이가 숲으로 왔어요!」 — 인물과 한 일을 이어 보세요.','{}'::text[],false,'{"seq":7,"concept":"K1-2-u4-C5","difficulty":3,"kind":"match","stem":"「아기 거북이가 숲으로 왔어요!」 — 인물과 한 일을 이어 보세요.","pairs":[{"l":"꽁지","r":"모래 구덩이에서 거북알을 발견했다."},{"l":"아기 거북","r":"까투리 가족을 따라 숲속 집으로 갔다."}],"mis":"K1-2-u4-X02","explanation":["누가 무엇을 했는지 이어요.","인물이 한 일을 바꾸지 않아요.","130쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L10_challenge#8','kor',1,2,'u4','L10','g1_2_kor_u4_L10_challenge','lesson_challenge','K1-2-u4-C5',4,'sa','auto','『국어』 130쪽 — 「아기 거북과 마지, 두리, 세찌, 꽁지는 재미있게 ◯◯◯.」 빈칸에 알맞은 말을 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K1-2-u4-C5","difficulty":4,"kind":"sa","stem":"『국어』 130쪽 — 「아기 거북과 마지, 두리, 세찌, 꽁지는 재미있게 ◯◯◯.」 빈칸에 알맞은 말을 쓰세요.","answer":["놀았다","놀았어요","놀았습니다"],"explanation":["재미있게 놀았어요.","미끄럼틀도 타고 공놀이도 했어요.","130쪽이에요."],"asset":{"type":"passage","lines":["꽁지가 모래 구덩이에서 거북알을 발견했어요.","한 아기 거북은 혼자 늦게 알에서 깨어났어요.","아기 거북은 까투리 가족을 따라 숲속 집으로 갔어요.","아기 거북과 마지, 두리, 세찌, 꽁지는 미끄럼틀도 타고 공놀이도 했어요.","마침내 아기 거북은 다시 가족을 만났어요."],"title":"「아기 거북이가 숲으로 왔어요!」 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L10_challenge#9','kor',1,2,'u4','L10','g1_2_kor_u4_L10_challenge','lesson_challenge','K1-2-u4-C5',4,'essay','teacher','「아기 거북이가 숲으로 왔어요!」에서 재미있거나 감동적인 장면과 그 까닭을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K1-2-u4-C5","difficulty":4,"kind":"essay","stem":"「아기 거북이가 숲으로 왔어요!」에서 재미있거나 감동적인 장면과 그 까닭을 쓰세요.","answer_guide":{"answer":"예: 아기 거북이 다시 가족을 만나는 장면이 감동적이었다. 혼자 있어서 무서웠을 텐데 가족을 만나 기뻤을 것 같다. — 장면과 까닭이 있으면 맞아요.","scoring_points":["어떤 장면인지 썼는가","까닭을 썼는가","내 말로 썼는가"]},"explanation":["어떤 장면에서 마음이 움직였는지 떠올려요.","까닭은 인물이 한 일에서 찾아요.","131쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L10_challenge#10','kor',1,2,'u4','L10','g1_2_kor_u4_L10_challenge','lesson_challenge','K1-2-u4-C5',4,'essay','teacher','반가운 사람을 다시 만났을 때 나라면 어떻게 할지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K1-2-u4-C5","difficulty":4,"kind":"essay","stem":"반가운 사람을 다시 만났을 때 나라면 어떻게 할지 쓰세요.","answer_guide":{"answer":"예: 오랜만에 만난 할머니께 달려가 꼭 안아 드리고 「보고 싶었어요.」라고 말하겠다. — 나라면 할 행동이 있으면 맞아요.","scoring_points":["내가 할 행동을 썼는가","만화 영화와 이어지는가","문장이 자연스러운가"]},"explanation":["아기 거북이 가족을 만난 장면을 떠올려요.","내 경험과 이어 봐요.","지도서 195쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L12_basic#1','kor',1,2,'u4','L12','g1_2_kor_u4_L12_basic','lesson_basic','K1-2-u4-C6',1,'mc','auto','『국어』 132쪽 — 「만화 영화를 보고 감동적인 장면 그리기」에서 가장 먼저 할 일은?',ARRAY['K1-2-u4-X05','K1-2-u4-X16']::text[],false,'{"seq":1,"concept":"K1-2-u4-C6","difficulty":1,"kind":"mc","stem":"『국어』 132쪽 — 「만화 영화를 보고 감동적인 장면 그리기」에서 가장 먼저 할 일은?","options":[{"t":"감동적인 장면을 친구들과 이야기하기","correct":true},{"t":"그림을 전시하기","mis":"K1-2-u4-X05"},{"t":"친구 그림에 점수 매기기","mis":"K1-2-u4-X16"}],"explanation":["이야기하기 → 그리기 → 전시하고 감상하기 차례예요.","점수를 매기는 활동이 아니에요.","132쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L12_basic#2','kor',1,2,'u4','L12','g1_2_kor_u4_L12_basic','lesson_basic','K1-2-u4-C6',1,'mc','auto','감동적인 장면을 그림으로 표현할 때 중요한 것은?',ARRAY['K1-2-u4-X14','K1-2-u4-X15']::text[],false,'{"seq":2,"concept":"K1-2-u4-C6","difficulty":1,"kind":"mc","stem":"감동적인 장면을 그림으로 표현할 때 중요한 것은?","options":[{"t":"감동받은 부분이 잘 드러나게 그리기","correct":true},{"t":"아주 예쁘게 꾸미기","mis":"K1-2-u4-X14"},{"t":"배경만 가득 그리기","mis":"K1-2-u4-X15"}],"explanation":["예쁘게 그리기보다 감동받은 부분이 드러나야 해요.","인물과 인물이 한 일을 그려요.","지도서 197쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L12_basic#3','kor',1,2,'u4','L12','g1_2_kor_u4_L12_basic','lesson_basic','K1-2-u4-C6',1,'mc','auto','붙임 16의 여백에는 무엇을 쓰나요?',ARRAY['K1-2-u4-X16','K1-2-u4-X08']::text[],false,'{"seq":3,"concept":"K1-2-u4-C6","difficulty":1,"kind":"mc","stem":"붙임 16의 여백에는 무엇을 쓰나요?","options":[{"t":"어떤 장면을 그렸는지 설명하는 글","correct":true},{"t":"친구 이름","mis":"K1-2-u4-X16"},{"t":"그림 그린 시간","mis":"K1-2-u4-X08"}],"explanation":["어떤 장면을 그렸는지 글로 설명해요.","그래야 보는 사람이 장면을 알 수 있어요.","지도서 197쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L12_basic#4','kor',1,2,'u4','L12','g1_2_kor_u4_L12_basic','lesson_basic','K1-2-u4-C6',1,'mc','auto','그림을 전시한 뒤 할 일은?',ARRAY['K1-2-u4-X16']::text[],false,'{"seq":4,"concept":"K1-2-u4-C6","difficulty":1,"kind":"mc","stem":"그림을 전시한 뒤 할 일은?","options":[{"t":"서로의 그림을 감상하며 감동을 비교해요","correct":true},{"t":"누가 제일 잘 그렸는지 뽑아요","mis":"K1-2-u4-X16"},{"t":"그림을 바로 버려요","mis":"K1-2-u4-X16"}],"explanation":["다른 친구는 어떤 장면을 감동적이라고 했는지 비교해요.","순위를 매기지 않아요.","132쪽 ③이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
