INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L12_basic#6','kor',1,2,'u4','L12','g1_2_kor_u4_L12_basic','lesson_basic','K1-2-u4-C6',2,'mc','auto','그림으로 그릴 장면을 정할 때 먼저 생각할 것은?',ARRAY['K1-2-u4-X14','K1-2-u4-X16']::text[],false,'{"seq":6,"concept":"K1-2-u4-C6","difficulty":2,"kind":"mc","stem":"그림으로 그릴 장면을 정할 때 먼저 생각할 것은?","options":[{"t":"그 장면에 누가 나오고 무엇을 했는지","correct":true},{"t":"어떤 색 크레파스가 예쁜지","mis":"K1-2-u4-X14"},{"t":"친구보다 크게 그릴 수 있는지","mis":"K1-2-u4-X16"}],"explanation":["그릴 인물과 그 인물의 말·행동을 먼저 떠올려요.","그러면 장면이 잘 드러나요.","지도서 197쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
