INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L12_challenge#5','kor',1,2,'u4','L12','g1_2_kor_u4_L12_challenge','lesson_challenge','K1-2-u4-C6',3,'error','auto','그림만 그리고 어떤 장면인지 설명하는 글은 쓰지 않았어요. 무엇이 아쉬운가요?',ARRAY['K1-2-u4-X15','K1-2-u4-X08']::text[],false,'{"seq":5,"concept":"K1-2-u4-C6","difficulty":3,"kind":"error","stem":"그림만 그리고 어떤 장면인지 설명하는 글은 쓰지 않았어요. 무엇이 아쉬운가요?","options":[{"t":"여백에 어떤 장면을 그렸는지 글로 써요","correct":true,"mis_target":"K1-2-u4-X15"},{"t":"잘했어요","mis":"K1-2-u4-X15"},{"t":"제목만 크게 써요","mis":"K1-2-u4-X08"}],"explanation":["글로 설명하면 장면이 더 잘 전해져요.","붙임 16의 여백을 활용해요.","지도서 197쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L12_challenge#6','kor',1,2,'u4','L12','g1_2_kor_u4_L12_challenge','lesson_challenge','K1-2-u4-C6',3,'mc','auto','친구와 같은 만화 영화를 그렸는데 장면이 달라요. 알맞은 생각은?',ARRAY['K1-2-u4-X12']::text[],false,'{"seq":6,"concept":"K1-2-u4-C6","difficulty":3,"kind":"mc","stem":"친구와 같은 만화 영화를 그렸는데 장면이 달라요. 알맞은 생각은?","options":[{"t":"감동을 주는 장면은 사람마다 다를 수 있어요","correct":true},{"t":"둘 중 하나는 틀렸어요","mis":"K1-2-u4-X12"},{"t":"같은 장면으로 다시 그려야 해요","mis":"K1-2-u4-X12"}],"explanation":["같은 만화 영화라도 감동 장면은 달라요.","서로 비교하며 존중해요.","지도서 196쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L12_challenge#7','kor',1,2,'u4','L12','g1_2_kor_u4_L12_challenge','lesson_challenge','K1-2-u4-C6',3,'match','auto','지도서 198~199쪽 — 우리 반에서 정한 활동과 하는 일을 이어 보세요.','{}'::text[],false,'{"seq":7,"concept":"K1-2-u4-C6","difficulty":3,"kind":"match","stem":"지도서 198~199쪽 — 우리 반에서 정한 활동과 하는 일을 이어 보세요.","pairs":[{"l":"입술책 만들기","r":"입술 모양 책에 생각이나 느낌을 써서 발표한다."},{"l":"역할놀이","r":"맡은 역할의 목소리와 몸짓으로 이야기를 꾸민다."}],"mis":"K1-2-u4-X16","explanation":["입술책은 생각을 쓰고 발표하는 활동이에요.","역할놀이는 인물이 되어 보는 활동이에요.","지도서 198~199쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L12_challenge#8','kor',1,2,'u4','L12','g1_2_kor_u4_L12_challenge','lesson_challenge','K1-2-u4-C6',4,'sa','auto','『국어』 132쪽 — 감동적인 장면을 그리기 전에 쓰는 칸 두 가지 가운데 하나는 「표현하고 싶은 장면」이에요. 나머지 하나를 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K1-2-u4-C6","difficulty":4,"kind":"sa","stem":"『국어』 132쪽 — 감동적인 장면을 그리기 전에 쓰는 칸 두 가지 가운데 하나는 「표현하고 싶은 장면」이에요. 나머지 하나를 쓰세요.","answer":["제목"],"explanation":["제목과 표현하고 싶은 장면을 써요.","그다음 그림을 그려요.","132쪽 ②예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L12_challenge#9','kor',1,2,'u4','L12','g1_2_kor_u4_L12_challenge','lesson_challenge','K1-2-u4-C6',4,'essay','teacher','내가 본 만화 영화에서 그림으로 그리고 싶은 감동적인 장면을 「누가 무엇을 하는 장면」으로 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K1-2-u4-C6","difficulty":4,"kind":"essay","stem":"내가 본 만화 영화에서 그림으로 그리고 싶은 감동적인 장면을 「누가 무엇을 하는 장면」으로 쓰세요.","answer_guide":{"answer":"예: 아기 거북이 다시 가족을 만나 함께 기뻐하는 장면 — 인물과 한 일이 있으면 맞아요.","scoring_points":["인물이 드러나는가","인물이 한 일이 드러나는가","감동적인 장면인가"]},"explanation":["그릴 인물을 먼저 정해요.","인물이 한 말과 행동을 떠올려요.","지도서 197쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L12_challenge#10','kor',1,2,'u4','L12','g1_2_kor_u4_L12_challenge','lesson_challenge','K1-2-u4-C6',4,'essay','teacher','친구의 그림을 감상하고 칭찬하는 말을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K1-2-u4-C6","difficulty":4,"kind":"essay","stem":"친구의 그림을 감상하고 칭찬하는 말을 쓰세요.","answer_guide":{"answer":"예: 아기 거북이 웃는 모습이 잘 보여서 다시 만나 기쁜 마음이 느껴져. — 장면이나 인물에 대한 칭찬이면 맞아요.","scoring_points":["좋은 점을 짚었는가","장면이나 인물과 관련된 칭찬인가","흉보거나 견주지 않았는가"]},"explanation":["인물의 모습과 행동이 잘 나타난 점을 칭찬해요.","그림 솜씨 견주기는 하지 않아요.","지도서 197쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_a#1','kor',1,2,'u4','','g1_2_kor_u4_review_a','unit_review','K1-2-u4-C1',1,'mc','auto','『국어』 134쪽 1번 — 누가 무엇을 했는지 알아보는 방법은?',ARRAY['K1-2-u4-X01']::text[],false,'{"seq":1,"concept":"K1-2-u4-C1","difficulty":1,"kind":"mc","stem":"『국어』 134쪽 1번 — 누가 무엇을 했는지 알아보는 방법은?","options":[{"t":"인물의 생각을 살펴본다","correct":true},{"t":"목소리가 큰지 살펴본다","mis":"K1-2-u4-X01"},{"t":"옷 색깔을 살펴본다","mis":"K1-2-u4-X01"}],"explanation":["인물의 생각이나 말, 행동을 살펴봐요.","목소리 크기로는 한 일을 알 수 없어요.","134쪽 1번이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_a#2','kor',1,2,'u4','','g1_2_kor_u4_review_a','unit_review','K1-2-u4-C1',1,'mc','auto','「미역도 맛있어」는 언제 일어난 일인가요?',ARRAY['K1-2-u4-X02']::text[],false,'{"seq":2,"concept":"K1-2-u4-C1","difficulty":1,"kind":"mc","stem":"「미역도 맛있어」는 언제 일어난 일인가요?","options":[{"t":"오늘 점심시간","correct":true},{"t":"어제 저녁","mis":"K1-2-u4-X02"},{"t":"아침 등굣길","mis":"K1-2-u4-X02"}],"explanation":["오늘 점심시간에 있었던 일이에요.","급식에 미역무침이 나왔어요.","115쪽이에요."],"asset":{"type":"passage","lines":["오늘 점심시간에 급식 반찬으로 미역무침이 나왔다.","나는 미역을 가장 싫어한다. 하지만 내 친구 서윤이는 미역무침이 맛있다고 했다.","“너도 한번 먹어 봐. 새콤달콤한 맛이 얼마나 좋은데.”","서윤이는 미역무침을 맛있게 먹었다.","나는 그 모습을 보고도 먹을 용기가 나지 않아 고개를 절레절레 저었다.","하지만 주위를 둘러보니 친구들이 모두 맛있게 미역무침을 먹고 있었다.","‘그럼 나도 한번 먹어 볼까?’"],"title":"『국어』 114쪽 — 미역도 맛있어 (1)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_a#3','kor',1,2,'u4','','g1_2_kor_u4_review_a','unit_review','K1-2-u4-C2',1,'mc','auto','시간을 나타내는 말은?',ARRAY['K1-2-u4-X04']::text[],false,'{"seq":3,"concept":"K1-2-u4-C2","difficulty":1,"kind":"mc","stem":"시간을 나타내는 말은?","options":[{"t":"어느 날 아침","correct":true},{"t":"시장","mis":"K1-2-u4-X04"},{"t":"맷돌","mis":"K1-2-u4-X04"}],"explanation":["일이 일어난 때를 알려 주는 말이에요.","시장은 곳, 맷돌은 물건이에요.","122쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_a#4','kor',1,2,'u4','','g1_2_kor_u4_review_a','unit_review','K1-2-u4-C3',1,'mc','auto','인물이 소리 내어 한 말에 쓰는 따옴표는?',ARRAY['K1-2-u4-X06','K1-2-u4-X07']::text[],false,'{"seq":4,"concept":"K1-2-u4-C3","difficulty":1,"kind":"mc","stem":"인물이 소리 내어 한 말에 쓰는 따옴표는?","options":[{"t":"“ ” 큰따옴표","correct":true},{"t":"‘ ’ 작은따옴표","mis":"K1-2-u4-X06"},{"t":"? 물음표","mis":"K1-2-u4-X07"}],"explanation":["소리 내어 한 말은 큰따옴표예요.","마음속 말은 작은따옴표예요.","123쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_a#5','kor',1,2,'u4','','g1_2_kor_u4_review_a','unit_review','K1-2-u4-C7',1,'mc','auto','『국어』 136쪽 — 「현수가 책을 ___.」에 알맞은 말은?',ARRAY['K1-2-u4-X17']::text[],false,'{"seq":5,"concept":"K1-2-u4-C7","difficulty":1,"kind":"mc","stem":"『국어』 136쪽 — 「현수가 책을 ___.」에 알맞은 말은?","options":[{"t":"읽습니다","correct":true},{"t":"먹습니다","mis":"K1-2-u4-X17"},{"t":"찹니다","mis":"K1-2-u4-X17"}],"explanation":["현수가 책을 읽습니다.","책은 읽어요.","136쪽 기초 다지기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_a#6','kor',1,2,'u4','','g1_2_kor_u4_review_a','unit_review','K1-2-u4-C4',1,'mc','auto','「빨간 모자가 된 아이쿠」에 나오는 인물은?',ARRAY['K1-2-u4-X03']::text[],false,'{"seq":6,"concept":"K1-2-u4-C4","difficulty":1,"kind":"mc","stem":"「빨간 모자가 된 아이쿠」에 나오는 인물은?","options":[{"t":"비비","correct":true},{"t":"서윤","mis":"K1-2-u4-X03"},{"t":"꽁지","mis":"K1-2-u4-X03"}],"explanation":["아이쿠·비비·카르망 콩드 백작이 나와요.","서윤과 꽁지는 다른 이야기예요.","124쪽이에요."],"asset":{"type":"passage","lines":["아이쿠가 할머니 댁에 가기로 했어요.","아이쿠와 비비는 할머니께 꽃밭에서 꽃을 따 드리기로 했어요.","할머니 댁에서는 할머니로 변장한 카르망 콩드 백작이 기다리고 있었어요.","아이쿠는 변장한 백작을 할머니라고 부르며 꽃을 선물했어요.","꽃을 받은 백작은 몸이 가렵고 콧물을 흘리며 기침과 재채기를 했어요."],"title":"「빨간 모자가 된 아이쿠」 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_a#7','kor',1,2,'u4','','g1_2_kor_u4_review_a','unit_review','K1-2-u4-C5',1,'mc','auto','꽁지는 모래 구덩이에서 무엇을 발견했나요?',ARRAY['K1-2-u4-X02']::text[],false,'{"seq":7,"concept":"K1-2-u4-C5","difficulty":1,"kind":"mc","stem":"꽁지는 모래 구덩이에서 무엇을 발견했나요?","options":[{"t":"거북알","correct":true},{"t":"맷돌","mis":"K1-2-u4-X02"},{"t":"꽃","mis":"K1-2-u4-X02"}],"explanation":["꽁지가 거북알을 발견했어요.","글에 없는 것은 고르지 않아요.","130쪽이에요."],"asset":{"type":"passage","lines":["꽁지가 모래 구덩이에서 거북알을 발견했어요.","한 아기 거북은 혼자 늦게 알에서 깨어났어요.","아기 거북은 까투리 가족을 따라 숲속 집으로 갔어요.","아기 거북과 마지, 두리, 세찌, 꽁지는 미끄럼틀도 타고 공놀이도 했어요.","마침내 아기 거북은 다시 가족을 만났어요."],"title":"「아기 거북이가 숲으로 왔어요!」 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_a#8','kor',1,2,'u4','','g1_2_kor_u4_review_a','unit_review','K1-2-u4-C6',1,'mc','auto','감동적인 장면을 그릴 때 중요한 것은?',ARRAY['K1-2-u4-X14','K1-2-u4-X15']::text[],false,'{"seq":8,"concept":"K1-2-u4-C6","difficulty":1,"kind":"mc","stem":"감동적인 장면을 그릴 때 중요한 것은?","options":[{"t":"감동받은 부분이 잘 드러나게 그리기","correct":true},{"t":"아주 예쁘게 꾸미기","mis":"K1-2-u4-X14"},{"t":"배경만 가득 그리기","mis":"K1-2-u4-X15"}],"explanation":["감동받은 부분이 드러나야 해요.","인물과 한 일을 그려요.","지도서 197쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_a#9','kor',1,2,'u4','','g1_2_kor_u4_review_a','unit_review','K1-2-u4-C1',2,'match','auto','「미역도 맛있어」 — 인물과 생각이나 말을 이어 보세요.','{}'::text[],false,'{"seq":9,"concept":"K1-2-u4-C1","difficulty":2,"kind":"match","stem":"「미역도 맛있어」 — 인물과 생각이나 말을 이어 보세요.","pairs":[{"l":"서윤","r":"“너도 한번 먹어 봐.”"},{"l":"주원","r":"‘그럼 나도 한번 먹어 볼까?’"},{"l":"선생님","r":"“주원이는 반찬을 골고루 잘 먹는구나.”"}],"mis":"K1-2-u4-X02","explanation":["인물의 생각이나 말을 이어요.","큰따옴표는 말, 작은따옴표는 생각이에요.","116쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_a#10','kor',1,2,'u4','','g1_2_kor_u4_review_a','unit_review','K1-2-u4-C2',2,'match','auto','시간을 나타내는 말과 그때 일어난 일을 이어 보세요.','{}'::text[],false,'{"seq":10,"concept":"K1-2-u4-C2","difficulty":2,"kind":"match","stem":"시간을 나타내는 말과 그때 일어난 일을 이어 보세요.","pairs":[{"l":"어느 날 아침","r":"사람들이 시장에서 맷돌 이야기를 했다."},{"l":"저녁","r":"도둑이 궁궐로 숨어들었다."},{"l":"깊은 밤","r":"도둑이 몰래 맷돌을 훔쳐 도망갔다."}],"mis":"K1-2-u4-X05","explanation":["아침 → 저녁 → 깊은 밤이에요.","시간을 나타내는 말로 차례를 정리해요.","122쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_a#11','kor',1,2,'u4','','g1_2_kor_u4_review_a','unit_review','K1-2-u4-C3',2,'blank','auto','빈칸에 알맞은 따옴표는?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_a#12','kor',1,2,'u4','','g1_2_kor_u4_review_a','unit_review','K1-2-u4-C4',2,'mc','auto','꽃을 선물받은 카르망 콩드 백작에게 어떤 일이 일어났나요?',ARRAY['K1-2-u4-X02']::text[],false,'{"seq":12,"concept":"K1-2-u4-C4","difficulty":2,"kind":"mc","stem":"꽃을 선물받은 카르망 콩드 백작에게 어떤 일이 일어났나요?","options":[{"t":"몸이 가렵고 콧물·기침·재채기가 났어요","correct":true},{"t":"아주 기뻐하며 춤을 추었어요","mis":"K1-2-u4-X02"},{"t":"꽃 냄새를 맡고 잠이 들었어요","mis":"K1-2-u4-X02"}],"explanation":["꽃을 받자 이상한 반응이 생겼어요.","글에 없는 일은 고르지 않아요.","126쪽이에요."],"asset":{"type":"passage","lines":["아이쿠가 할머니 댁에 가기로 했어요.","아이쿠와 비비는 할머니께 꽃밭에서 꽃을 따 드리기로 했어요.","할머니 댁에서는 할머니로 변장한 카르망 콩드 백작이 기다리고 있었어요.","아이쿠는 변장한 백작을 할머니라고 부르며 꽃을 선물했어요.","꽃을 받은 백작은 몸이 가렵고 콧물을 흘리며 기침과 재채기를 했어요."],"title":"「빨간 모자가 된 아이쿠」 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_a#13','kor',1,2,'u4','','g1_2_kor_u4_review_a','unit_review','K1-2-u4-C5',2,'mc','auto','아기 거북은 왜 혼자 까투리 가족의 집으로 오게 되었나요?',ARRAY['K1-2-u4-X02']::text[],false,'{"seq":13,"concept":"K1-2-u4-C5","difficulty":2,"kind":"mc","stem":"아기 거북은 왜 혼자 까투리 가족의 집으로 오게 되었나요?","options":[{"t":"혼자 뒤늦게 알에서 깨어났기 때문이에요","correct":true},{"t":"까투리 집이 더 좋아서예요","mis":"K1-2-u4-X02"},{"t":"바다가 너무 추워서예요","mis":"K1-2-u4-X02"}],"explanation":["혼자 늦게 깨어나 가족과 떨어졌어요.","그래서 까투리 가족을 따라갔어요.","129쪽이에요."],"asset":{"type":"passage","lines":["꽁지가 모래 구덩이에서 거북알을 발견했어요.","한 아기 거북은 혼자 늦게 알에서 깨어났어요.","아기 거북은 까투리 가족을 따라 숲속 집으로 갔어요.","아기 거북과 마지, 두리, 세찌, 꽁지는 미끄럼틀도 타고 공놀이도 했어요.","마침내 아기 거북은 다시 가족을 만났어요."],"title":"「아기 거북이가 숲으로 왔어요!」 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_a#14','kor',1,2,'u4','','g1_2_kor_u4_review_a','unit_review','K1-2-u4-C7',2,'match','auto','『국어』 136쪽 — 문장과 동작을 나타내는 말을 이어 보세요.','{}'::text[],false,'{"seq":14,"concept":"K1-2-u4-C7","difficulty":2,"kind":"match","stem":"『국어』 136쪽 — 문장과 동작을 나타내는 말을 이어 보세요.","pairs":[{"l":"명희가 얼굴을","r":"씻습니다"},{"l":"한나가 밥을","r":"먹습니다"},{"l":"재현이가 이를","r":"닦습니다"}],"mis":"K1-2-u4-X17","explanation":["얼굴을 씻고, 밥을 먹고, 이를 닦아요.","그림에 맞는 동작 말을 넣어요.","136쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_a#15','kor',1,2,'u4','','g1_2_kor_u4_review_a','unit_review','K1-2-u4-C2',2,'mc','auto','『국어』 134쪽 2번 — 「흥부 놀부」에서 가장 먼저 일어난 일은?',ARRAY['K1-2-u4-X05']::text[],false,'{"seq":15,"concept":"K1-2-u4-C2","difficulty":2,"kind":"mc","stem":"『국어』 134쪽 2번 — 「흥부 놀부」에서 가장 먼저 일어난 일은?","options":[{"t":"흥부가 다친 제비 다리를 고쳐 주었다","correct":true},{"t":"박에서 금은보화가 나왔다","mis":"K1-2-u4-X05"},{"t":"박이 열렸다","mis":"K1-2-u4-X05"}],"explanation":["제비 다리를 고쳐 준 일이 처음이에요.","그 일 때문에 다음 일이 일어났어요.","134쪽 2번이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_a#16','kor',1,2,'u4','','g1_2_kor_u4_review_a','unit_review','K1-2-u4-C1',2,'ox','auto','인물이 무엇을 했는지 알려면 인물의 생각이나 말, 행동을 살펴봐야 해요.',ARRAY['K1-2-u4-X01']::text[],false,'{"seq":16,"concept":"K1-2-u4-C1","difficulty":2,"kind":"ox","stem":"인물이 무엇을 했는지 알려면 인물의 생각이나 말, 행동을 살펴봐야 해요.","answer":"O","reason_options":[{"t":"생각·말·행동에 인물이 한 일이 드러나니까","correct":true},{"t":"인물의 목소리 크기만 보면 알 수 있으니까","mis":"K1-2-u4-X01"}],"mis":"K1-2-u4-X01","explanation":["생각이나 말, 행동을 살펴요.","목소리 크기로는 알 수 없어요.","134쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_a#17','kor',1,2,'u4','','g1_2_kor_u4_review_a','unit_review','K1-2-u4-C1',3,'error','auto','친구가 「주원이는 미역무침을 처음부터 좋아했다.」라고 정리했어요. 무엇이 잘못되었나요?',ARRAY['K1-2-u4-X02']::text[],false,'{"seq":17,"concept":"K1-2-u4-C1","difficulty":3,"kind":"error","stem":"친구가 「주원이는 미역무침을 처음부터 좋아했다.」라고 정리했어요. 무엇이 잘못되었나요?","options":[{"t":"주원이는 미역을 가장 싫어했어요 — 용기 내어 먹어 보았어요","correct":true,"mis_target":"K1-2-u4-X02"},{"t":"잘 정리했어요","mis":"K1-2-u4-X02"},{"t":"서윤이가 미역을 싫어했어요","mis":"K1-2-u4-X02"}],"explanation":["글에 없는 일은 넣지 않아요.","처음에는 먹기 싫어했어요.","115쪽이에요."],"asset":{"type":"passage","lines":["오늘 점심시간에 급식 반찬으로 미역무침이 나왔다.","나는 미역을 가장 싫어한다. 하지만 내 친구 서윤이는 미역무침이 맛있다고 했다.","“너도 한번 먹어 봐. 새콤달콤한 맛이 얼마나 좋은데.”","서윤이는 미역무침을 맛있게 먹었다.","나는 그 모습을 보고도 먹을 용기가 나지 않아 고개를 절레절레 저었다.","하지만 주위를 둘러보니 친구들이 모두 맛있게 미역무침을 먹고 있었다.","‘그럼 나도 한번 먹어 볼까?’"],"title":"『국어』 114쪽 — 미역도 맛있어 (1)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_a#18','kor',1,2,'u4','','g1_2_kor_u4_review_a','unit_review','K1-2-u4-C3',3,'error','auto','‘그 맷돌이 있으면 부자가 될 수 있겠어.’를 큰따옴표로 고쳐 썼어요. 무엇이 잘못되었나요?',ARRAY['K1-2-u4-X06','K1-2-u4-X07']::text[],false,'{"seq":18,"concept":"K1-2-u4-C3","difficulty":3,"kind":"error","stem":"‘그 맷돌이 있으면 부자가 될 수 있겠어.’를 큰따옴표로 고쳐 썼어요. 무엇이 잘못되었나요?","options":[{"t":"마음속으로 한 말이라 작은따옴표를 써야 해요","correct":true,"mis_target":"K1-2-u4-X06"},{"t":"잘 고쳤어요","mis":"K1-2-u4-X06"},{"t":"따옴표를 아예 빼야 해요","mis":"K1-2-u4-X07"}],"explanation":["마음속으로 한 말은 작은따옴표예요.","도둑의 생각이에요.","123쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_a#19','kor',1,2,'u4','','g1_2_kor_u4_review_a','unit_review','K1-2-u4-C5',3,'error','auto','친구가 「감동적이었어.」라고만 말했어요. 무엇이 부족한가요?',ARRAY['K1-2-u4-X10','K1-2-u4-X01']::text[],false,'{"seq":19,"concept":"K1-2-u4-C5","difficulty":3,"kind":"error","stem":"친구가 「감동적이었어.」라고만 말했어요. 무엇이 부족한가요?","options":[{"t":"어떤 장면이 왜 감동적이었는지가 빠졌어요","correct":true,"mis_target":"K1-2-u4-X10"},{"t":"잘 말했어요","mis":"K1-2-u4-X10"},{"t":"더 크게 말해야 해요","mis":"K1-2-u4-X01"}],"explanation":["어떤 장면인지와 까닭을 말해요.","한마디로 끝내지 않아요.","지도서 195쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_a#20','kor',1,2,'u4','','g1_2_kor_u4_review_a','unit_review','K1-2-u4-C6',3,'error','auto','그림에 숲 배경만 가득 그리고 인물은 그리지 않았어요. 무엇이 아쉬운가요?',ARRAY['K1-2-u4-X15','K1-2-u4-X14']::text[],false,'{"seq":20,"concept":"K1-2-u4-C6","difficulty":3,"kind":"error","stem":"그림에 숲 배경만 가득 그리고 인물은 그리지 않았어요. 무엇이 아쉬운가요?","options":[{"t":"누가 무엇을 하는 장면인지 인물과 한 일을 그려요","correct":true,"mis_target":"K1-2-u4-X15"},{"t":"잘 그렸어요","mis":"K1-2-u4-X15"},{"t":"색을 더 칠해야 해요","mis":"K1-2-u4-X14"}],"explanation":["배경만으로는 어떤 장면인지 몰라요.","인물과 한 일이 보이게 그려요.","지도서 197쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_a#21','kor',1,2,'u4','','g1_2_kor_u4_review_a','unit_review','K1-2-u4-C2',3,'mc','auto','「개미와 비둘기」에서 일이 일어난 차례로 알맞은 것은?',ARRAY['K1-2-u4-X05']::text[],false,'{"seq":21,"concept":"K1-2-u4-C2","difficulty":3,"kind":"mc","stem":"「개미와 비둘기」에서 일이 일어난 차례로 알맞은 것은?","options":[{"t":"사냥꾼이 총을 겨누었다 → 개미가 발꿈치를 물었다 → 비둘기가 날아갔다","correct":true},{"t":"비둘기가 날아갔다 → 사냥꾼이 총을 겨누었다 → 개미가 발꿈치를 물었다","mis":"K1-2-u4-X05"},{"t":"개미가 발꿈치를 물었다 → 비둘기가 날아갔다 → 사냥꾼이 총을 겨누었다","mis":"K1-2-u4-X05"}],"explanation":["무슨 일 때문에 다음 일이 일어났는지 생각해요.","시간을 나타내는 말이 없어도 흐름을 찾아요.","지도서 203쪽이에요."],"asset":{"type":"passage","lines":["비둘기가 나뭇가지 위에 앉아 있었습니다.","이것을 본 사냥꾼이 비둘기에게 몰래 총을 겨누었습니다.","‘저런, 비둘기가 위험하다.’","그 모습을 본 개미가 사냥꾼의 발꿈치를 따끔하게 물었습니다.","“앗, 따가워!” 사냥꾼이 소리를 지르자 비둘기가 깜짝 놀라 날아갔습니다.","“개미야, 고마워. 네가 아니었으면 큰일 날 뻔했구나.”"],"title":"지도서 203쪽 — 개미와 비둘기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_a#22','kor',1,2,'u4','','g1_2_kor_u4_review_a','unit_review','K1-2-u4-C4',3,'match','auto','「빨간 모자가 된 아이쿠」 — 있었던 일을 차례대로 이어 보세요.','{}'::text[],false,'{"seq":22,"concept":"K1-2-u4-C4","difficulty":3,"kind":"match","stem":"「빨간 모자가 된 아이쿠」 — 있었던 일을 차례대로 이어 보세요.","pairs":[{"l":"①","r":"아이쿠가 할머니 댁에 가기로 했다."},{"l":"②","r":"아이쿠와 비비가 할머니께 꽃을 따 드리기로 했다."},{"l":"③","r":"아이쿠가 할머니로 변장한 백작을 만났다."},{"l":"④","r":"꽃을 선물받은 백작에게 이상한 반응이 생겼다."}],"mis":"K1-2-u4-X05","explanation":["있었던 일을 차례대로 정리해요.","그림을 보며 떠올려요.","127쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_a#23','kor',1,2,'u4','','g1_2_kor_u4_review_a','unit_review','K1-2-u4-C1',4,'sa','auto','「미역도 맛있어」에서 주원이에게 미역무침을 권한 친구의 이름을 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K1-2-u4-C1","difficulty":4,"kind":"sa","stem":"「미역도 맛있어」에서 주원이에게 미역무침을 권한 친구의 이름을 쓰세요.","answer":["서윤","서윤이"],"explanation":["서윤이가 먹어 보라고 했어요.","새콤달콤한 맛이 좋다고 했어요.","115쪽이에요."],"asset":{"type":"passage","lines":["오늘 점심시간에 급식 반찬으로 미역무침이 나왔다.","나는 미역을 가장 싫어한다. 하지만 내 친구 서윤이는 미역무침이 맛있다고 했다.","“너도 한번 먹어 봐. 새콤달콤한 맛이 얼마나 좋은데.”","서윤이는 미역무침을 맛있게 먹었다.","나는 그 모습을 보고도 먹을 용기가 나지 않아 고개를 절레절레 저었다.","하지만 주위를 둘러보니 친구들이 모두 맛있게 미역무침을 먹고 있었다.","‘그럼 나도 한번 먹어 볼까?’"],"title":"『국어』 114쪽 — 미역도 맛있어 (1)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_a#24','kor',1,2,'u4','','g1_2_kor_u4_review_a','unit_review','K1-2-u4-C2',4,'essay','teacher','지도서 평가 — 「개미와 비둘기」를 읽고 일이 일어난 차례대로 세 문장으로 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K1-2-u4-C2","difficulty":4,"kind":"essay","stem":"지도서 평가 — 「개미와 비둘기」를 읽고 일이 일어난 차례대로 세 문장으로 쓰세요.","answer_guide":{"answer":"예: 사냥꾼이 비둘기에게 총을 겨누었다. / 개미가 사냥꾼의 발꿈치를 물었다. / 비둘기가 놀라 날아갔다. — 누가 무엇을 했는지와 차례가 맞으면 맞아요.","scoring_points":["누가 무엇을 했는지 썼는가","차례가 맞는가","글에 있는 일만 썼는가"]},"explanation":["인물이 한 일을 먼저 찾아요.","무슨 일 때문에 다음 일이 일어났는지 생각해요.","지도서 203쪽이에요."],"asset":{"type":"passage","lines":["비둘기가 나뭇가지 위에 앉아 있었습니다.","이것을 본 사냥꾼이 비둘기에게 몰래 총을 겨누었습니다.","‘저런, 비둘기가 위험하다.’","그 모습을 본 개미가 사냥꾼의 발꿈치를 따끔하게 물었습니다.","“앗, 따가워!” 사냥꾼이 소리를 지르자 비둘기가 깜짝 놀라 날아갔습니다.","“개미야, 고마워. 네가 아니었으면 큰일 날 뻔했구나.”"],"title":"지도서 203쪽 — 개미와 비둘기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_a#25','kor',1,2,'u4','','g1_2_kor_u4_review_a','unit_review','K1-2-u4-C5',4,'essay','teacher','『국어』 135쪽 4번 — 자신이 본 책이나 만화 영화의 제목과 생각이나 느낌을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K1-2-u4-C5","difficulty":4,"kind":"essay","stem":"『국어』 135쪽 4번 — 자신이 본 책이나 만화 영화의 제목과 생각이나 느낌을 쓰세요.","answer_guide":{"answer":"예: 「○○○」 — 주인공이 친구들과 술래잡기하는 모습을 보고 나도 술래잡기하고 싶다는 생각이 들었다. — 제목과 장면에 대한 생각이 있으면 맞아요.","scoring_points":["제목을 썼는가","어떤 장면인지 드러나는가","내 생각이나 느낌을 썼는가"]},"explanation":["책이나 만화 영화를 떠올려요.","어떤 장면 때문인지 써요.","135쪽 4번이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_b#1','kor',1,2,'u4','','g1_2_kor_u4_review_b','unit_review','K1-2-u4-C1',1,'mc','auto','『국어』 134쪽 1번 — 누가 무엇을 했는지 알아보는 방법은?',ARRAY['K1-2-u4-X01']::text[],false,'{"seq":1,"concept":"K1-2-u4-C1","difficulty":1,"kind":"mc","stem":"『국어』 134쪽 1번 — 누가 무엇을 했는지 알아보는 방법은?","options":[{"t":"인물의 행동을 살펴본다","correct":true},{"t":"목소리가 큰지 살펴본다","mis":"K1-2-u4-X01"},{"t":"키가 큰지 살펴본다","mis":"K1-2-u4-X01"}],"explanation":["인물의 행동을 보면 한 일을 알 수 있어요.","겉모습으로는 알 수 없어요.","134쪽 1번이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_b#2','kor',1,2,'u4','','g1_2_kor_u4_review_b','unit_review','K1-2-u4-C1',1,'mc','auto','주원이에게 미역무침을 먹어 보라고 한 사람은?',ARRAY['K1-2-u4-X02','K1-2-u4-X03']::text[],false,'{"seq":2,"concept":"K1-2-u4-C1","difficulty":1,"kind":"mc","stem":"주원이에게 미역무침을 먹어 보라고 한 사람은?","options":[{"t":"친구 서윤이","correct":true},{"t":"선생님","mis":"K1-2-u4-X02"},{"t":"엄마","mis":"K1-2-u4-X03"}],"explanation":["서윤이가 먹어 보라고 했어요.","선생님은 칭찬해 주셨어요.","115쪽이에요."],"asset":{"type":"passage","lines":["오늘 점심시간에 급식 반찬으로 미역무침이 나왔다.","나는 미역을 가장 싫어한다. 하지만 내 친구 서윤이는 미역무침이 맛있다고 했다.","“너도 한번 먹어 봐. 새콤달콤한 맛이 얼마나 좋은데.”","서윤이는 미역무침을 맛있게 먹었다.","나는 그 모습을 보고도 먹을 용기가 나지 않아 고개를 절레절레 저었다.","하지만 주위를 둘러보니 친구들이 모두 맛있게 미역무침을 먹고 있었다.","‘그럼 나도 한번 먹어 볼까?’"],"title":"『국어』 114쪽 — 미역도 맛있어 (1)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_b#3','kor',1,2,'u4','','g1_2_kor_u4_review_b','unit_review','K1-2-u4-C2',1,'mc','auto','시간을 나타내는 말은?',ARRAY['K1-2-u4-X04']::text[],false,'{"seq":3,"concept":"K1-2-u4-C2","difficulty":1,"kind":"mc","stem":"시간을 나타내는 말은?","options":[{"t":"저녁","correct":true},{"t":"궁궐","mis":"K1-2-u4-X04"},{"t":"도둑","mis":"K1-2-u4-X04"}],"explanation":["저녁은 때를 나타내요.","궁궐은 곳, 도둑은 인물이에요.","122쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_b#4','kor',1,2,'u4','','g1_2_kor_u4_review_b','unit_review','K1-2-u4-C3',1,'mc','auto','인물이 마음속으로 한 말에 쓰는 따옴표는?',ARRAY['K1-2-u4-X06','K1-2-u4-X07']::text[],false,'{"seq":4,"concept":"K1-2-u4-C3","difficulty":1,"kind":"mc","stem":"인물이 마음속으로 한 말에 쓰는 따옴표는?","options":[{"t":"‘ ’ 작은따옴표","correct":true},{"t":"“ ” 큰따옴표","mis":"K1-2-u4-X06"},{"t":"! 느낌표","mis":"K1-2-u4-X07"}],"explanation":["마음속으로 한 말은 작은따옴표예요.","소리 내어 한 말은 큰따옴표예요.","123쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_b#5','kor',1,2,'u4','','g1_2_kor_u4_review_b','unit_review','K1-2-u4-C7',1,'mc','auto','『국어』 136쪽 — 「명희가 얼굴을 ___.」에 알맞은 말은?',ARRAY['K1-2-u4-X17']::text[],false,'{"seq":5,"concept":"K1-2-u4-C7","difficulty":1,"kind":"mc","stem":"『국어』 136쪽 — 「명희가 얼굴을 ___.」에 알맞은 말은?","options":[{"t":"씻습니다","correct":true},{"t":"그립니다","mis":"K1-2-u4-X17"},{"t":"읽습니다","mis":"K1-2-u4-X17"}],"explanation":["명희가 얼굴을 씻습니다.","얼굴은 씻어요.","136쪽 기초 다지기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_b#6','kor',1,2,'u4','','g1_2_kor_u4_review_b','unit_review','K1-2-u4-C4',1,'mc','auto','아이쿠는 할머니께 무슨 선물을 드리려고 했나요?',ARRAY['K1-2-u4-X02']::text[],false,'{"seq":6,"concept":"K1-2-u4-C4","difficulty":1,"kind":"mc","stem":"아이쿠는 할머니께 무슨 선물을 드리려고 했나요?","options":[{"t":"꽃밭에서 딴 꽃","correct":true},{"t":"과자","mis":"K1-2-u4-X02"},{"t":"빨간 모자","mis":"K1-2-u4-X02"}],"explanation":["꽃을 드리려고 했어요.","글에 없는 선물은 고르지 않아요.","126쪽이에요."],"asset":{"type":"passage","lines":["아이쿠가 할머니 댁에 가기로 했어요.","아이쿠와 비비는 할머니께 꽃밭에서 꽃을 따 드리기로 했어요.","할머니 댁에서는 할머니로 변장한 카르망 콩드 백작이 기다리고 있었어요.","아이쿠는 변장한 백작을 할머니라고 부르며 꽃을 선물했어요.","꽃을 받은 백작은 몸이 가렵고 콧물을 흘리며 기침과 재채기를 했어요."],"title":"「빨간 모자가 된 아이쿠」 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_b#7','kor',1,2,'u4','','g1_2_kor_u4_review_b','unit_review','K1-2-u4-C5',1,'mc','auto','아기 거북과 꺼병이들은 무엇을 하고 놀았나요?',ARRAY['K1-2-u4-X02']::text[],false,'{"seq":7,"concept":"K1-2-u4-C5","difficulty":1,"kind":"mc","stem":"아기 거북과 꺼병이들은 무엇을 하고 놀았나요?","options":[{"t":"미끄럼틀 타기, 공놀이","correct":true},{"t":"수영 대회","mis":"K1-2-u4-X02"},{"t":"책 읽기","mis":"K1-2-u4-X02"}],"explanation":["미끄럼틀도 타고 공놀이도 했어요.","글에 없는 놀이예요.","129쪽이에요."],"asset":{"type":"passage","lines":["꽁지가 모래 구덩이에서 거북알을 발견했어요.","한 아기 거북은 혼자 늦게 알에서 깨어났어요.","아기 거북은 까투리 가족을 따라 숲속 집으로 갔어요.","아기 거북과 마지, 두리, 세찌, 꽁지는 미끄럼틀도 타고 공놀이도 했어요.","마침내 아기 거북은 다시 가족을 만났어요."],"title":"「아기 거북이가 숲으로 왔어요!」 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_b#8','kor',1,2,'u4','','g1_2_kor_u4_review_b','unit_review','K1-2-u4-C6',1,'mc','auto','그림을 전시하고 할 일은?',ARRAY['K1-2-u4-X16']::text[],false,'{"seq":8,"concept":"K1-2-u4-C6","difficulty":1,"kind":"mc","stem":"그림을 전시하고 할 일은?","options":[{"t":"서로의 그림을 감상하며 감동을 비교해요","correct":true},{"t":"누가 제일 잘 그렸는지 뽑아요","mis":"K1-2-u4-X16"},{"t":"그림을 바로 버려요","mis":"K1-2-u4-X16"}],"explanation":["서로 다른 감동을 비교해요.","순위를 매기지 않아요.","132쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_b#9','kor',1,2,'u4','','g1_2_kor_u4_review_b','unit_review','K1-2-u4-C1',2,'match','auto','「미역도 맛있어」 — 인물과 행동을 이어 보세요.','{}'::text[],false,'{"seq":9,"concept":"K1-2-u4-C1","difficulty":2,"kind":"match","stem":"「미역도 맛있어」 — 인물과 행동을 이어 보세요.","pairs":[{"l":"서윤","r":"미역무침을 맛있게 먹었다."},{"l":"주원","r":"눈을 질끈 감고 미역무침을 먹어 보았다."},{"l":"선생님","r":"칭찬하며 박수를 치셨다."}],"mis":"K1-2-u4-X02","explanation":["인물의 행동을 이어요.","그림을 참고해요.","116쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_b#10','kor',1,2,'u4','','g1_2_kor_u4_review_b','unit_review','K1-2-u4-C2',2,'mc','auto','「소금을 만드는 맷돌」에서 가장 나중에 일어난 일은?',ARRAY['K1-2-u4-X05']::text[],false,'{"seq":10,"concept":"K1-2-u4-C2","difficulty":2,"kind":"mc","stem":"「소금을 만드는 맷돌」에서 가장 나중에 일어난 일은?","options":[{"t":"바닷물이 짜게 되었다","correct":true},{"t":"도둑이 맷돌을 훔쳤다","mis":"K1-2-u4-X05"},{"t":"사람들이 시장에서 이야기했다","mis":"K1-2-u4-X05"}],"explanation":["맷돌이 바닷속에서 계속 돌아 바닷물이 짜졌어요.","이것이 마지막 일이에요.","120쪽이에요."],"asset":{"type":"passage","lines":["도둑은 배를 타고 바다를 건너다가 맷돌을 돌려 보고 싶어졌습니다.","“나와라, 소금!”","그러자 맷돌에서 하얀 소금이 쏟아져 나왔고, 점점 배 안에 쌓여 갔습니다.","배가 기우뚱거리기 시작했습니다.","도둑은 너무 놀라 무슨 말을 해야 하는지 잊어버렸습니다.","결국, 맷돌은 도둑과 함께 바닷속에 가라앉고 말았습니다.","바닷속에서도 맷돌은 쉬지 않고 돌았습니다. 그래서 바닷물이 짜게 되었습니다."],"title":"『국어』 120쪽 — 소금을 만드는 맷돌 (2)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_b#11','kor',1,2,'u4','','g1_2_kor_u4_review_b','unit_review','K1-2-u4-C3',2,'blank','auto','빈칸에 알맞은 따옴표는?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_b#12','kor',1,2,'u4','','g1_2_kor_u4_review_b','unit_review','K1-2-u4-C4',2,'mc','auto','아이쿠가 백작을 할머니라고 부른 까닭은?',ARRAY['K1-2-u4-X02']::text[],false,'{"seq":12,"concept":"K1-2-u4-C4","difficulty":2,"kind":"mc","stem":"아이쿠가 백작을 할머니라고 부른 까닭은?","options":[{"t":"백작이 할머니로 변장하고 있어서","correct":true},{"t":"백작이 진짜 할머니라서","mis":"K1-2-u4-X02"},{"t":"비비가 그렇게 부르라고 해서","mis":"K1-2-u4-X02"}],"explanation":["변장한 백작에게 속았어요.","글에 없는 까닭은 고르지 않아요.","126쪽이에요."],"asset":{"type":"passage","lines":["아이쿠가 할머니 댁에 가기로 했어요.","아이쿠와 비비는 할머니께 꽃밭에서 꽃을 따 드리기로 했어요.","할머니 댁에서는 할머니로 변장한 카르망 콩드 백작이 기다리고 있었어요.","아이쿠는 변장한 백작을 할머니라고 부르며 꽃을 선물했어요.","꽃을 받은 백작은 몸이 가렵고 콧물을 흘리며 기침과 재채기를 했어요."],"title":"「빨간 모자가 된 아이쿠」 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_b#13','kor',1,2,'u4','','g1_2_kor_u4_review_b','unit_review','K1-2-u4-C5',2,'match','auto','낱말과 뜻을 이어 보세요.','{}'::text[],false,'{"seq":13,"concept":"K1-2-u4-C5","difficulty":2,"kind":"match","stem":"낱말과 뜻을 이어 보세요.","pairs":[{"l":"구덩이","r":"땅이 움푹하게 파인 곳."},{"l":"꺼병이","r":"꿩의 어린 새끼."},{"l":"막내","r":"여러 형제, 자매 가운데에서 맨 나중에 난 사람."}],"mis":"K1-2-u4-X02","explanation":["구덩이·꺼병이·막내예요.","뜻을 바르게 이어요.","129쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_b#14','kor',1,2,'u4','','g1_2_kor_u4_review_b','unit_review','K1-2-u4-C7',2,'match','auto','『국어』 136쪽 — 문장과 동작을 나타내는 말을 이어 보세요.','{}'::text[],false,'{"seq":14,"concept":"K1-2-u4-C7","difficulty":2,"kind":"match","stem":"『국어』 136쪽 — 문장과 동작을 나타내는 말을 이어 보세요.","pairs":[{"l":"현수가 책을","r":"읽습니다"},{"l":"태윤이가 공을","r":"찹니다"},{"l":"진희가 그림을","r":"그립니다"}],"mis":"K1-2-u4-X17","explanation":["책을 읽고, 공을 차고, 그림을 그려요.","동작 말로 누가 무엇을 하는지 말해요.","136쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_b#15','kor',1,2,'u4','','g1_2_kor_u4_review_b','unit_review','K1-2-u4-C2',2,'mc','auto','「흥부 놀부」에서 가장 나중에 일어난 일은?',ARRAY['K1-2-u4-X05']::text[],false,'{"seq":15,"concept":"K1-2-u4-C2","difficulty":2,"kind":"mc","stem":"「흥부 놀부」에서 가장 나중에 일어난 일은?","options":[{"t":"박에서 금은보화가 나왔다","correct":true},{"t":"흥부가 제비 다리를 고쳐 주었다","mis":"K1-2-u4-X05"},{"t":"제비가 박씨를 물어 왔다","mis":"K1-2-u4-X05"}],"explanation":["박을 타자 금은보화가 나왔어요.","무슨 일 때문에 다음 일이 일어났는지 생각해요.","134쪽 2번이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_b#16','kor',1,2,'u4','','g1_2_kor_u4_review_b','unit_review','K1-2-u4-C2',2,'ox','auto','시간을 나타내는 말을 생각하면 일이 일어난 차례를 정리할 수 있어요.',ARRAY['K1-2-u4-X04']::text[],false,'{"seq":16,"concept":"K1-2-u4-C2","difficulty":2,"kind":"ox","stem":"시간을 나타내는 말을 생각하면 일이 일어난 차례를 정리할 수 있어요.","answer":"O","reason_options":[{"t":"아침·저녁·밤처럼 일이 일어난 때를 알려 주니까","correct":true},{"t":"시간을 나타내는 말은 장소를 알려 주니까","mis":"K1-2-u4-X04"}],"mis":"K1-2-u4-X04","explanation":["일이 일어난 때를 알면 차례가 보여요.","시장·궁궐은 곳이에요.","122쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_b#17','kor',1,2,'u4','','g1_2_kor_u4_review_b','unit_review','K1-2-u4-C1',3,'error','auto','인물이 한 일을 알려고 「목소리가 큰지」를 살펴보았어요. 무엇이 잘못되었나요?',ARRAY['K1-2-u4-X01']::text[],false,'{"seq":17,"concept":"K1-2-u4-C1","difficulty":3,"kind":"error","stem":"인물이 한 일을 알려고 「목소리가 큰지」를 살펴보았어요. 무엇이 잘못되었나요?","options":[{"t":"인물의 생각이나 말, 행동을 살펴봐야 해요","correct":true,"mis_target":"K1-2-u4-X01"},{"t":"잘 살펴보았어요","mis":"K1-2-u4-X01"},{"t":"옷 색깔도 살펴봐야 해요","mis":"K1-2-u4-X01"}],"explanation":["목소리 크기로는 한 일을 알 수 없어요.","생각·말·행동을 찾아요.","134쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_b#18','kor',1,2,'u4','','g1_2_kor_u4_review_b','unit_review','K1-2-u4-C3',3,'error','auto','“나와라, 소금!을 쓰고 뒤쪽 따옴표를 쓰지 않았어요. 무엇이 잘못되었나요?',ARRAY['K1-2-u4-X07','K1-2-u4-X06']::text[],false,'{"seq":18,"concept":"K1-2-u4-C3","difficulty":3,"kind":"error","stem":"“나와라, 소금!을 쓰고 뒤쪽 따옴표를 쓰지 않았어요. 무엇이 잘못되었나요?","options":[{"t":"따옴표는 말의 앞과 뒤에 두 짝을 함께 써요","correct":true,"mis_target":"K1-2-u4-X07"},{"t":"잘 썼어요","mis":"K1-2-u4-X07"},{"t":"작은따옴표로 바꿔야 해요","mis":"K1-2-u4-X06"}],"explanation":["열고 닫는 두 짝을 함께 써요.","“나와라, 소금!”처럼 써요.","123쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_b#19','kor',1,2,'u4','','g1_2_kor_u4_review_b','unit_review','K1-2-u4-C5',3,'error','auto','친구가 고른 장면이 나와 달라서 「그건 감동적이지 않아.」라고 했어요. 무엇이 잘못되었나요?',ARRAY['K1-2-u4-X12']::text[],false,'{"seq":19,"concept":"K1-2-u4-C5","difficulty":3,"kind":"error","stem":"친구가 고른 장면이 나와 달라서 「그건 감동적이지 않아.」라고 했어요. 무엇이 잘못되었나요?","options":[{"t":"사람마다 감동을 느끼는 장면이 달라요 — 친구 생각을 존중해요","correct":true,"mis_target":"K1-2-u4-X12"},{"t":"잘 말했어요","mis":"K1-2-u4-X12"},{"t":"친구 장면을 고쳐 줘야 해요","mis":"K1-2-u4-X12"}],"explanation":["다른 생각도 틀린 것이 아니에요.","왜 그 장면인지 물어봐요.","지도서 177쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_b#20','kor',1,2,'u4','','g1_2_kor_u4_review_b','unit_review','K1-2-u4-C6',3,'error','auto','전시한 그림을 보고 「내 그림이 제일 잘 그렸어.」라고 했어요. 무엇이 잘못되었나요?',ARRAY['K1-2-u4-X16','K1-2-u4-X12']::text[],false,'{"seq":20,"concept":"K1-2-u4-C6","difficulty":3,"kind":"error","stem":"전시한 그림을 보고 「내 그림이 제일 잘 그렸어.」라고 했어요. 무엇이 잘못되었나요?","options":[{"t":"순위를 매기지 말고 친구가 고른 장면과 까닭을 살펴봐요","correct":true,"mis_target":"K1-2-u4-X16"},{"t":"잘 말했어요","mis":"K1-2-u4-X16"},{"t":"친구 그림을 고쳐 줘야 해요","mis":"K1-2-u4-X12"}],"explanation":["감상은 서로 다른 감동을 비교하는 시간이에요.","칭찬할 점을 찾아요.","132쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_b#21','kor',1,2,'u4','','g1_2_kor_u4_review_b','unit_review','K1-2-u4-C1',3,'mc','auto','「개미와 비둘기」에서 비둘기가 깜짝 놀라 날아간 까닭은?',ARRAY['K1-2-u4-X02']::text[],false,'{"seq":21,"concept":"K1-2-u4-C1","difficulty":3,"kind":"mc","stem":"「개미와 비둘기」에서 비둘기가 깜짝 놀라 날아간 까닭은?","options":[{"t":"사냥꾼이 「앗, 따가워!」 하고 소리를 질러서","correct":true},{"t":"개미가 비둘기를 물어서","mis":"K1-2-u4-X02"},{"t":"비가 내려서","mis":"K1-2-u4-X02"}],"explanation":["사냥꾼의 소리를 듣고 날아갔어요.","개미는 사냥꾼을 물었어요.","지도서 203쪽이에요."],"asset":{"type":"passage","lines":["비둘기가 나뭇가지 위에 앉아 있었습니다.","이것을 본 사냥꾼이 비둘기에게 몰래 총을 겨누었습니다.","‘저런, 비둘기가 위험하다.’","그 모습을 본 개미가 사냥꾼의 발꿈치를 따끔하게 물었습니다.","“앗, 따가워!” 사냥꾼이 소리를 지르자 비둘기가 깜짝 놀라 날아갔습니다.","“개미야, 고마워. 네가 아니었으면 큰일 날 뻔했구나.”"],"title":"지도서 203쪽 — 개미와 비둘기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_b#22','kor',1,2,'u4','','g1_2_kor_u4_review_b','unit_review','K1-2-u4-C5',3,'match','auto','「아기 거북이가 숲으로 왔어요!」 — 일어난 일을 차례대로 이어 보세요.','{}'::text[],false,'{"seq":22,"concept":"K1-2-u4-C5","difficulty":3,"kind":"match","stem":"「아기 거북이가 숲으로 왔어요!」 — 일어난 일을 차례대로 이어 보세요.","pairs":[{"l":"①","r":"꽁지가 거북알을 발견했다."},{"l":"②","r":"아기 거북이 까투리 가족을 따라 집으로 갔다."},{"l":"③","r":"아기 거북과 꺼병이들이 재미있게 놀았다."},{"l":"④","r":"아기 거북이 다시 가족을 만났다."}],"mis":"K1-2-u4-X05","explanation":["일어난 일을 차례대로 정리해요.","먼저 있었던 일부터예요.","130쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_b#23','kor',1,2,'u4','','g1_2_kor_u4_review_b','unit_review','K1-2-u4-C2',4,'sa','auto','「소금을 만드는 맷돌」에서 도둑이 맷돌을 훔친 곳은 어디인가요?','{}'::text[],false,'{"seq":23,"concept":"K1-2-u4-C2","difficulty":4,"kind":"sa","stem":"「소금을 만드는 맷돌」에서 도둑이 맷돌을 훔친 곳은 어디인가요?","answer":["궁궐"],"explanation":["저녁에 궁궐로 숨어들었어요.","깊은 밤에 맷돌을 훔쳤어요.","119쪽이에요."],"asset":{"type":"passage","lines":["옛날 옛적에 어느 임금님이 신기한 맷돌을 가지고 있었습니다.","어느 날 아침, 사람들은 시장에 모여 신기한 맷돌에 대해 이야기를 했습니다.","“우리 임금님에게는 신기한 맷돌이 있다네.”","사람들 뒤에서 도둑이 그 말을 조용히 듣고 있었습니다.","‘그 맷돌이 있으면 부자가 될 수 있겠어.’","저녁이 되자 도둑은 궁궐로 숨어들었습니다.","그리고 깊은 밤, 모두 잠든 사이 몰래 맷돌을 훔쳐 도망갔습니다."],"title":"『국어』 118~119쪽 — 소금을 만드는 맷돌 (1)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_b#24','kor',1,2,'u4','','g1_2_kor_u4_review_b','unit_review','K1-2-u4-C2',4,'essay','teacher','「소금을 만드는 맷돌」에서 일어난 일을 시간을 나타내는 말을 넣어 두 문장으로 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K1-2-u4-C2","difficulty":4,"kind":"essay","stem":"「소금을 만드는 맷돌」에서 일어난 일을 시간을 나타내는 말을 넣어 두 문장으로 쓰세요.","answer_guide":{"answer":"예: 어느 날 아침, 사람들은 시장에서 맷돌 이야기를 했다. / 깊은 밤, 도둑은 맷돌을 훔쳐 도망갔다. — 시간을 나타내는 말과 일이 맞으면 맞아요.","scoring_points":["시간을 나타내는 말을 넣었는가","누가 무엇을 했는지 썼는가","차례가 맞는가"]},"explanation":["아침·저녁·깊은 밤을 찾아요.","그때 일어난 일을 써요.","122쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_b#25','kor',1,2,'u4','','g1_2_kor_u4_review_b','unit_review','K1-2-u4-C5',4,'essay','teacher','「아기 거북이가 숲으로 왔어요!」에서 감동적인 장면과 그 까닭을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K1-2-u4-C5","difficulty":4,"kind":"essay","stem":"「아기 거북이가 숲으로 왔어요!」에서 감동적인 장면과 그 까닭을 쓰세요.","answer_guide":{"answer":"예: 아기 거북이 다시 가족을 만나는 장면이 감동적이었다. 혼자 있어서 무서웠을 텐데 가족을 만나 기뻤을 것 같다. — 장면과 까닭이 있으면 맞아요.","scoring_points":["어떤 장면인지 썼는가","까닭을 썼는가","내 말로 썼는가"]},"explanation":["마음이 움직인 장면을 떠올려요.","까닭은 인물이 한 일에서 찾아요.","131쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_c#1','kor',1,2,'u4','','g1_2_kor_u4_review_c','unit_review','K1-2-u4-C1',1,'mc','auto','누가 무엇을 했는지 알아보는 방법은?',ARRAY['K1-2-u4-X01']::text[],false,'{"seq":1,"concept":"K1-2-u4-C1","difficulty":1,"kind":"mc","stem":"누가 무엇을 했는지 알아보는 방법은?","options":[{"t":"인물의 말을 살펴본다","correct":true},{"t":"머리 모양을 살펴본다","mis":"K1-2-u4-X01"},{"t":"목소리가 큰지 살펴본다","mis":"K1-2-u4-X01"}],"explanation":["인물이 한 말에도 한 일이 드러나요.","머리 모양은 상관없어요.","134쪽 1번이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_c#2','kor',1,2,'u4','','g1_2_kor_u4_review_c','unit_review','K1-2-u4-C1',1,'mc','auto','주원이를 칭찬해 주신 사람은?',ARRAY['K1-2-u4-X02','K1-2-u4-X03']::text[],false,'{"seq":2,"concept":"K1-2-u4-C1","difficulty":1,"kind":"mc","stem":"주원이를 칭찬해 주신 사람은?","options":[{"t":"선생님","correct":true},{"t":"서윤이","mis":"K1-2-u4-X02"},{"t":"엄마","mis":"K1-2-u4-X03"}],"explanation":["선생님께서 칭찬하며 박수를 치셨어요.","서윤이는 먹어 보라고 했어요.","116쪽이에요."],"asset":{"type":"passage","lines":["나는 눈을 질끈 감고 미역무침을 한번 먹어 보았다.","입을 살짝 벌려 미역무침을 조금 먹어 보았더니 생각보다 맛이 좋았다.","계속 먹다 보니 입안에 새콤함이 가득해졌다. 어느새 미역무침을 모두 다 먹었다.","“주원이는 반찬을 골고루 잘 먹는구나.”","선생님께서도 나를 칭찬해 주시며 박수도 쳐 주셨다.","나는 어깨가 으쓱해지고 자꾸만 웃음이 나왔다.","‘다음에도 새로운 음식 먹기에 도전해 봐야지.’"],"title":"『국어』 114쪽 — 미역도 맛있어 (2)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_c#3','kor',1,2,'u4','','g1_2_kor_u4_review_c','unit_review','K1-2-u4-C2',1,'mc','auto','시간을 나타내는 말은?',ARRAY['K1-2-u4-X04']::text[],false,'{"seq":3,"concept":"K1-2-u4-C2","difficulty":1,"kind":"mc","stem":"시간을 나타내는 말은?","options":[{"t":"깊은 밤","correct":true},{"t":"바다","mis":"K1-2-u4-X04"},{"t":"배","mis":"K1-2-u4-X04"}],"explanation":["깊은 밤은 때를 나타내요.","바다와 배는 시간을 나타내지 않아요.","122쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_c#4','kor',1,2,'u4','','g1_2_kor_u4_review_c','unit_review','K1-2-u4-C3',1,'mc','auto','“우리 임금님에게는 신기한 맷돌이 있다네.”는 어떤 말인가요?',ARRAY['K1-2-u4-X06','K1-2-u4-X04']::text[],false,'{"seq":4,"concept":"K1-2-u4-C3","difficulty":1,"kind":"mc","stem":"“우리 임금님에게는 신기한 맷돌이 있다네.”는 어떤 말인가요?","options":[{"t":"소리 내어 한 말","correct":true},{"t":"마음속으로 한 말","mis":"K1-2-u4-X06"},{"t":"시간을 나타내는 말","mis":"K1-2-u4-X04"}],"explanation":["큰따옴표가 있으니 소리 내어 한 말이에요.","사람들이 시장에서 한 말이에요.","123쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_c#5','kor',1,2,'u4','','g1_2_kor_u4_review_c','unit_review','K1-2-u4-C7',1,'mc','auto','『국어』 136쪽 — 「한나가 밥을 ___.」에 알맞은 말은?',ARRAY['K1-2-u4-X17']::text[],false,'{"seq":5,"concept":"K1-2-u4-C7","difficulty":1,"kind":"mc","stem":"『국어』 136쪽 — 「한나가 밥을 ___.」에 알맞은 말은?","options":[{"t":"먹습니다","correct":true},{"t":"닦습니다","mis":"K1-2-u4-X17"},{"t":"찹니다","mis":"K1-2-u4-X17"}],"explanation":["한나가 밥을 먹습니다.","밥은 먹어요.","136쪽 기초 다지기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_c#6','kor',1,2,'u4','','g1_2_kor_u4_review_c','unit_review','K1-2-u4-C4',1,'mc','auto','할머니로 변장한 인물은?',ARRAY['K1-2-u4-X02']::text[],false,'{"seq":6,"concept":"K1-2-u4-C4","difficulty":1,"kind":"mc","stem":"할머니로 변장한 인물은?","options":[{"t":"카르망 콩드 백작","correct":true},{"t":"비비","mis":"K1-2-u4-X02"},{"t":"아이쿠","mis":"K1-2-u4-X02"}],"explanation":["카르망 콩드 백작이 할머니로 변장했어요.","비비는 아이쿠의 로봇이에요.","126쪽이에요."],"asset":{"type":"passage","lines":["아이쿠가 할머니 댁에 가기로 했어요.","아이쿠와 비비는 할머니께 꽃밭에서 꽃을 따 드리기로 했어요.","할머니 댁에서는 할머니로 변장한 카르망 콩드 백작이 기다리고 있었어요.","아이쿠는 변장한 백작을 할머니라고 부르며 꽃을 선물했어요.","꽃을 받은 백작은 몸이 가렵고 콧물을 흘리며 기침과 재채기를 했어요."],"title":"「빨간 모자가 된 아이쿠」 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_c#7','kor',1,2,'u4','','g1_2_kor_u4_review_c','unit_review','K1-2-u4-C5',1,'mc','auto','「꺼병이」의 뜻은?',ARRAY['K1-2-u4-X02']::text[],false,'{"seq":7,"concept":"K1-2-u4-C5","difficulty":1,"kind":"mc","stem":"「꺼병이」의 뜻은?","options":[{"t":"꿩의 어린 새끼","correct":true},{"t":"땅이 움푹하게 파인 곳","mis":"K1-2-u4-X02"},{"t":"맨 나중에 난 사람","mis":"K1-2-u4-X02"}],"explanation":["꺼병이는 꿩의 어린 새끼예요.","구덩이·막내와 헷갈리지 않아요.","129쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_c#8','kor',1,2,'u4','','g1_2_kor_u4_review_c','unit_review','K1-2-u4-C6',1,'mc','auto','그림 옆 여백에 쓸 것은?',ARRAY['K1-2-u4-X16','K1-2-u4-X08']::text[],false,'{"seq":8,"concept":"K1-2-u4-C6","difficulty":1,"kind":"mc","stem":"그림 옆 여백에 쓸 것은?","options":[{"t":"어떤 장면을 그렸는지 설명하는 글","correct":true},{"t":"친구 이름","mis":"K1-2-u4-X16"},{"t":"그린 시간","mis":"K1-2-u4-X08"}],"explanation":["어떤 장면인지 글로 설명해요.","보는 사람이 장면을 알 수 있어요.","지도서 197쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_c#9','kor',1,2,'u4','','g1_2_kor_u4_review_c','unit_review','K1-2-u4-C1',2,'match','auto','『국어활동』 53쪽 — 인물이 한 일을 이어 보세요.','{}'::text[],false,'{"seq":9,"concept":"K1-2-u4-C1","difficulty":2,"kind":"match","stem":"『국어활동』 53쪽 — 인물이 한 일을 이어 보세요.","pairs":[{"l":"양치기 소년","r":"늑대가 나타났다고 소리쳤다."},{"l":"마을 사람들","r":"거짓말이라는 것을 알고 화를 냈다."}],"mis":"K1-2-u4-X02","explanation":["양치기 소년은 늑대가 나타났다고 소리쳤어요.","마을 사람들은 화를 냈어요.","국어활동 53쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_c#10','kor',1,2,'u4','','g1_2_kor_u4_review_c','unit_review','K1-2-u4-C2',2,'mc','auto','도둑이 맷돌과 함께 바닷속에 빠진 까닭은?',ARRAY['K1-2-u4-X02']::text[],false,'{"seq":10,"concept":"K1-2-u4-C2","difficulty":2,"kind":"mc","stem":"도둑이 맷돌과 함께 바닷속에 빠진 까닭은?","options":[{"t":"맷돌을 멈추게 하는 말을 잊어버려서","correct":true},{"t":"임금님이 쫓아와서","mis":"K1-2-u4-X02"},{"t":"배에 구멍이 나서","mis":"K1-2-u4-X02"}],"explanation":["소금이 계속 쌓여 배가 가라앉았어요.","글에 없는 까닭은 고르지 않아요.","121쪽이에요."],"asset":{"type":"passage","lines":["도둑은 배를 타고 바다를 건너다가 맷돌을 돌려 보고 싶어졌습니다.","“나와라, 소금!”","그러자 맷돌에서 하얀 소금이 쏟아져 나왔고, 점점 배 안에 쌓여 갔습니다.","배가 기우뚱거리기 시작했습니다.","도둑은 너무 놀라 무슨 말을 해야 하는지 잊어버렸습니다.","결국, 맷돌은 도둑과 함께 바닷속에 가라앉고 말았습니다.","바닷속에서도 맷돌은 쉬지 않고 돌았습니다. 그래서 바닷물이 짜게 되었습니다."],"title":"『국어』 120쪽 — 소금을 만드는 맷돌 (2)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_c#11','kor',1,2,'u4','','g1_2_kor_u4_review_c','unit_review','K1-2-u4-C3',2,'blank','auto','『국어활동』 54쪽 — 빈칸에 알맞은 따옴표는?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_c#12','kor',1,2,'u4','','g1_2_kor_u4_review_c','unit_review','K1-2-u4-C4',2,'mc','auto','「빨간 모자가 된 아이쿠」에서 가장 먼저 있었던 일은?',ARRAY['K1-2-u4-X05']::text[],false,'{"seq":12,"concept":"K1-2-u4-C4","difficulty":2,"kind":"mc","stem":"「빨간 모자가 된 아이쿠」에서 가장 먼저 있었던 일은?","options":[{"t":"아이쿠가 할머니 댁에 가기로 했다","correct":true},{"t":"백작에게 이상한 반응이 생겼다","mis":"K1-2-u4-X05"},{"t":"아이쿠가 변장한 백작을 만났다","mis":"K1-2-u4-X05"}],"explanation":["할머니 댁에 가기로 한 것이 처음 일이에요.","차례대로 떠올려요.","127쪽이에요."],"asset":{"type":"passage","lines":["아이쿠가 할머니 댁에 가기로 했어요.","아이쿠와 비비는 할머니께 꽃밭에서 꽃을 따 드리기로 했어요.","할머니 댁에서는 할머니로 변장한 카르망 콩드 백작이 기다리고 있었어요.","아이쿠는 변장한 백작을 할머니라고 부르며 꽃을 선물했어요.","꽃을 받은 백작은 몸이 가렵고 콧물을 흘리며 기침과 재채기를 했어요."],"title":"「빨간 모자가 된 아이쿠」 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_c#13','kor',1,2,'u4','','g1_2_kor_u4_review_c','unit_review','K1-2-u4-C5',2,'mc','auto','「아기 거북이가 숲으로 왔어요!」에서 가장 나중에 일어난 일은?',ARRAY['K1-2-u4-X05']::text[],false,'{"seq":13,"concept":"K1-2-u4-C5","difficulty":2,"kind":"mc","stem":"「아기 거북이가 숲으로 왔어요!」에서 가장 나중에 일어난 일은?","options":[{"t":"아기 거북이 다시 가족을 만났다","correct":true},{"t":"꽁지가 거북알을 발견했다","mis":"K1-2-u4-X05"},{"t":"까투리 가족을 따라 집으로 갔다","mis":"K1-2-u4-X05"}],"explanation":["마침내 다시 가족을 만났어요.","이것이 마지막 일이에요.","130쪽이에요."],"asset":{"type":"passage","lines":["꽁지가 모래 구덩이에서 거북알을 발견했어요.","한 아기 거북은 혼자 늦게 알에서 깨어났어요.","아기 거북은 까투리 가족을 따라 숲속 집으로 갔어요.","아기 거북과 마지, 두리, 세찌, 꽁지는 미끄럼틀도 타고 공놀이도 했어요.","마침내 아기 거북은 다시 가족을 만났어요."],"title":"「아기 거북이가 숲으로 왔어요!」 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_c#14','kor',1,2,'u4','','g1_2_kor_u4_review_c','unit_review','K1-2-u4-C7',2,'mc','auto','동작을 나타내는 말이 아닌 것은?',ARRAY['K1-2-u4-X17']::text[],false,'{"seq":14,"concept":"K1-2-u4-C7","difficulty":2,"kind":"mc","stem":"동작을 나타내는 말이 아닌 것은?","options":[{"t":"책상","correct":true},{"t":"닦습니다","mis":"K1-2-u4-X17"},{"t":"그립니다","mis":"K1-2-u4-X17"}],"explanation":["책상은 물건의 이름이에요.","몸으로 해 볼 수 있는 말이 동작을 나타내는 말이에요.","지도서 201쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_c#15','kor',1,2,'u4','','g1_2_kor_u4_review_c','unit_review','K1-2-u4-C2',2,'mc','auto','『국어활동』 55쪽 — 「아침 일찍」에 일어난 일은?',ARRAY['K1-2-u4-X05']::text[],false,'{"seq":15,"concept":"K1-2-u4-C2","difficulty":2,"kind":"mc","stem":"『국어활동』 55쪽 — 「아침 일찍」에 일어난 일은?","options":[{"t":"양치기 소년이 심심해서 늑대가 나타났다고 거짓말을 했다","correct":true},{"t":"진짜 늑대가 나타났다","mis":"K1-2-u4-X05"},{"t":"마을 사람들이 화가 났다","mis":"K1-2-u4-X05"}],"explanation":["아침 일찍 첫 거짓말을 했어요.","진짜 늑대는 며칠 뒤에 나타났어요.","국어활동 55쪽이에요."],"asset":{"type":"passage","lines":["아침 일찍 양 떼를 몰고 풀밭으로 간 양치기 소년은 심심했어요.","‘뭐, 재미있는 일 없을까?’","소년은 늑대가 나타났다고 거짓말을 했어요.","이튿날 소년은 또 거짓말을 해 마을 사람들이 화가 났어요.","며칠 뒤, 이번에는 진짜로 늑대가 나타났어요.","“늑대가 나타났어요! 도와주세요!”","마을 사람들은 아무도 오지 않았고, 소년은 그제야 거짓말한 것을 후회했어요."],"title":"『국어활동』 52~55쪽 — 양치기 소년"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_c#16','kor',1,2,'u4','','g1_2_kor_u4_review_c','unit_review','K1-2-u4-C5',2,'ox','auto','만화 영화를 보고 생각이나 느낌을 말할 때 친구의 말을 그대로 따라 해도 돼요.',ARRAY['K1-2-u4-X11']::text[],false,'{"seq":16,"concept":"K1-2-u4-C5","difficulty":2,"kind":"ox","stem":"만화 영화를 보고 생각이나 느낌을 말할 때 친구의 말을 그대로 따라 해도 돼요.","answer":"X","reason_options":[{"t":"내 생각이나 느낌을 내 말로 말해야 하니까","correct":true},{"t":"친구와 같은 말을 해야 맞으니까","mis":"K1-2-u4-X11"}],"mis":"K1-2-u4-X11","explanation":["친구 생각은 존중하되 따라 하지는 않아요.","내 마음이 움직인 장면을 말해요.","135쪽 3번이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_c#17','kor',1,2,'u4','','g1_2_kor_u4_review_c','unit_review','K1-2-u4-C2',3,'error','auto','친구가 「시장」을 시간을 나타내는 말로 골랐어요. 무엇이 잘못되었나요?',ARRAY['K1-2-u4-X04']::text[],false,'{"seq":17,"concept":"K1-2-u4-C2","difficulty":3,"kind":"error","stem":"친구가 「시장」을 시간을 나타내는 말로 골랐어요. 무엇이 잘못되었나요?","options":[{"t":"「시장」은 곳을 나타내요 — 「어느 날 아침」이 시간을 나타내는 말이에요","correct":true,"mis_target":"K1-2-u4-X04"},{"t":"잘 골랐어요","mis":"K1-2-u4-X04"},{"t":"「맷돌」이 시간을 나타내는 말이에요","mis":"K1-2-u4-X04"}],"explanation":["「언제?」에 답이 되는 말이 시간을 나타내는 말이에요.","시장은 「어디에서」의 답이에요.","122쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_c#18','kor',1,2,'u4','','g1_2_kor_u4_review_c','unit_review','K1-2-u4-C4',3,'error','auto','친구가 「아이쿠가 진짜 할머니께 꽃을 드렸다.」라고 정리했어요. 무엇이 잘못되었나요?',ARRAY['K1-2-u4-X02']::text[],false,'{"seq":18,"concept":"K1-2-u4-C4","difficulty":3,"kind":"error","stem":"친구가 「아이쿠가 진짜 할머니께 꽃을 드렸다.」라고 정리했어요. 무엇이 잘못되었나요?","options":[{"t":"꽃을 받은 것은 할머니로 변장한 카르망 콩드 백작이에요","correct":true,"mis_target":"K1-2-u4-X02"},{"t":"잘 정리했어요","mis":"K1-2-u4-X02"},{"t":"비비가 꽃을 받았어요","mis":"K1-2-u4-X02"}],"explanation":["백작이 할머니로 변장하고 있었어요.","인물이 한 일을 바꾸지 않아요.","126쪽이에요."],"asset":{"type":"passage","lines":["아이쿠가 할머니 댁에 가기로 했어요.","아이쿠와 비비는 할머니께 꽃밭에서 꽃을 따 드리기로 했어요.","할머니 댁에서는 할머니로 변장한 카르망 콩드 백작이 기다리고 있었어요.","아이쿠는 변장한 백작을 할머니라고 부르며 꽃을 선물했어요.","꽃을 받은 백작은 몸이 가렵고 콧물을 흘리며 기침과 재채기를 했어요."],"title":"「빨간 모자가 된 아이쿠」 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_c#19','kor',1,2,'u4','','g1_2_kor_u4_review_c','unit_review','K1-2-u4-C5',3,'error','auto','감동적인 까닭을 「화면 색깔이 예뻐서」라고 했어요. 무엇이 아쉬운가요?',ARRAY['K1-2-u4-X13']::text[],false,'{"seq":19,"concept":"K1-2-u4-C5","difficulty":3,"kind":"error","stem":"감동적인 까닭을 「화면 색깔이 예뻐서」라고 했어요. 무엇이 아쉬운가요?","options":[{"t":"까닭을 인물이 한 말이나 행동에서 찾아요","correct":true,"mis_target":"K1-2-u4-X13"},{"t":"잘 말했어요","mis":"K1-2-u4-X13"},{"t":"영상이 길어서라고 해야 해요","mis":"K1-2-u4-X13"}],"explanation":["인물이 무엇을 했길래 마음이 움직였는지 말해요.","색깔은 이야기가 아니에요.","지도서 195쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_c#20','kor',1,2,'u4','','g1_2_kor_u4_review_c','unit_review','K1-2-u4-C6',3,'error','auto','예쁘게 꾸미느라 시간을 다 써서 어떤 장면인지 알 수 없게 되었어요. 무엇이 아쉬운가요?',ARRAY['K1-2-u4-X14']::text[],false,'{"seq":20,"concept":"K1-2-u4-C6","difficulty":3,"kind":"error","stem":"예쁘게 꾸미느라 시간을 다 써서 어떤 장면인지 알 수 없게 되었어요. 무엇이 아쉬운가요?","options":[{"t":"예쁘게보다 감동받은 장면이 드러나게 그려요","correct":true,"mis_target":"K1-2-u4-X14"},{"t":"잘했어요","mis":"K1-2-u4-X14"},{"t":"더 많이 꾸며야 해요","mis":"K1-2-u4-X14"}],"explanation":["감동받은 부분이 드러나야 해요.","꾸미기에만 힘쓰지 않아요.","지도서 197쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_c#21','kor',1,2,'u4','','g1_2_kor_u4_review_c','unit_review','K1-2-u4-C7',3,'error','auto','「재현이가 이를 먹습니다.」라고 썼어요. 무엇이 잘못되었나요?',ARRAY['K1-2-u4-X17']::text[],false,'{"seq":21,"concept":"K1-2-u4-C7","difficulty":3,"kind":"error","stem":"「재현이가 이를 먹습니다.」라고 썼어요. 무엇이 잘못되었나요?","options":[{"t":"이는 「닦습니다」가 알맞아요","correct":true,"mis_target":"K1-2-u4-X17"},{"t":"잘 썼어요","mis":"K1-2-u4-X17"},{"t":"「재현이가」를 빼야 해요","mis":"K1-2-u4-X17"}],"explanation":["그림에 맞는 동작 말을 넣어요.","이를 닦습니다.","136쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_c#22','kor',1,2,'u4','','g1_2_kor_u4_review_c','unit_review','K1-2-u4-C2',3,'match','auto','『국어활동』 55쪽 — 시간을 나타내는 말과 일을 이어 보세요.','{}'::text[],false,'{"seq":22,"concept":"K1-2-u4-C2","difficulty":3,"kind":"match","stem":"『국어활동』 55쪽 — 시간을 나타내는 말과 일을 이어 보세요.","pairs":[{"l":"아침 일찍","r":"양치기 소년이 처음 거짓말을 했다."},{"l":"이튿날","r":"소년이 또 거짓말을 해 마을 사람들이 화가 났다."},{"l":"며칠 뒤","r":"진짜 늑대가 나타났지만 아무도 오지 않았다."}],"mis":"K1-2-u4-X05","explanation":["아침 일찍 → 이튿날 → 며칠 뒤예요.","시간을 나타내는 말로 차례를 정리해요.","국어활동 55쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_c#23','kor',1,2,'u4','','g1_2_kor_u4_review_c','unit_review','K1-2-u4-C4',4,'sa','auto','아이쿠와 함께 꽃을 따러 간 로봇의 이름을 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K1-2-u4-C4","difficulty":4,"kind":"sa","stem":"아이쿠와 함께 꽃을 따러 간 로봇의 이름을 쓰세요.","answer":["비비"],"explanation":["비비는 아이쿠 왕자의 로봇이에요.","함께 꽃을 땄어요.","124쪽이에요."],"asset":{"type":"passage","lines":["아이쿠가 할머니 댁에 가기로 했어요.","아이쿠와 비비는 할머니께 꽃밭에서 꽃을 따 드리기로 했어요.","할머니 댁에서는 할머니로 변장한 카르망 콩드 백작이 기다리고 있었어요.","아이쿠는 변장한 백작을 할머니라고 부르며 꽃을 선물했어요.","꽃을 받은 백작은 몸이 가렵고 콧물을 흘리며 기침과 재채기를 했어요."],"title":"「빨간 모자가 된 아이쿠」 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_c#24','kor',1,2,'u4','','g1_2_kor_u4_review_c','unit_review','K1-2-u4-C1',4,'essay','teacher','「미역도 맛있어」에서 일어난 일을 「누가 무엇을 했다」 문장 세 개로 차례대로 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K1-2-u4-C1","difficulty":4,"kind":"essay","stem":"「미역도 맛있어」에서 일어난 일을 「누가 무엇을 했다」 문장 세 개로 차례대로 쓰세요.","answer_guide":{"answer":"예: 주원이는 미역무침을 먹기 싫어했다. / 서윤이가 먹어 보라고 했다. / 주원이는 용기 내어 먹었다. — 차례와 누가 무엇을이 맞으면 맞아요.","scoring_points":["누가 무엇을 했는지 썼는가","차례가 맞는가","글에 있는 일만 썼는가"]},"explanation":["117쪽 5번을 떠올려요.","먼저 있었던 일부터 써요.","117쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_c#25','kor',1,2,'u4','','g1_2_kor_u4_review_c','unit_review','K1-2-u4-C5',4,'essay','teacher','「빨간 모자가 된 아이쿠」에서 재미있었던 장면과 그 까닭을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K1-2-u4-C5","difficulty":4,"kind":"essay","stem":"「빨간 모자가 된 아이쿠」에서 재미있었던 장면과 그 까닭을 쓰세요.","answer_guide":{"answer":"예: 아이쿠가 백작을 할머니라고 부르는 장면이 재미있었다. 진짜 할머니가 아닌 줄 모르고 꽃을 주는 모습이 웃겼다. — 장면과 까닭이 있으면 맞아요.","scoring_points":["어떤 장면인지 썼는가","까닭을 썼는가","내 말로 썼는가"]},"explanation":["재미있었던 장면을 떠올려요.","친구와 달라도 괜찮아요.","126쪽이에요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"아이쿠가 간식을 먹는 장면이 재미있었어."},{"who":"친구 2","text":"아이쿠가 백작을 할머니라고 부르는 장면이 기억에 남았어."},{"who":"친구 3","text":"백작이 뛰어나가는 장면이 재미있었어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_d#1','kor',1,2,'u4','','g1_2_kor_u4_review_d','unit_review','K1-2-u4-C1',1,'mc','auto','누가 무엇을 했는지 알아보는 방법이 아닌 것은?',ARRAY['K1-2-u4-X01']::text[],false,'{"seq":1,"concept":"K1-2-u4-C1","difficulty":1,"kind":"mc","stem":"누가 무엇을 했는지 알아보는 방법이 아닌 것은?","options":[{"t":"목소리가 큰지 살펴본다","correct":true},{"t":"인물의 생각을 살펴본다","mis":"K1-2-u4-X01"},{"t":"인물의 행동을 살펴본다","mis":"K1-2-u4-X01"}],"explanation":["목소리 크기로는 무엇을 했는지 몰라요.","생각이나 말, 행동을 살펴봐요.","134쪽 1번이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_d#2','kor',1,2,'u4','','g1_2_kor_u4_review_d','unit_review','K1-2-u4-C1',1,'mc','auto','「미역도 맛있어」의 등장인물이 아닌 것은?',ARRAY['K1-2-u4-X03']::text[],false,'{"seq":2,"concept":"K1-2-u4-C1","difficulty":1,"kind":"mc","stem":"「미역도 맛있어」의 등장인물이 아닌 것은?","options":[{"t":"엄마","correct":true},{"t":"서윤","mis":"K1-2-u4-X03"},{"t":"주원","mis":"K1-2-u4-X03"}],"explanation":["주원이, 서윤이, 선생님이 나와요.","엄마는 나오지 않아요.","115쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_d#3','kor',1,2,'u4','','g1_2_kor_u4_review_d','unit_review','K1-2-u4-C2',1,'mc','auto','『국어활동』 55쪽 — 시간을 나타내는 말은?',ARRAY['K1-2-u4-X04']::text[],false,'{"seq":3,"concept":"K1-2-u4-C2","difficulty":1,"kind":"mc","stem":"『국어활동』 55쪽 — 시간을 나타내는 말은?","options":[{"t":"이튿날","correct":true},{"t":"풀밭","mis":"K1-2-u4-X04"},{"t":"양 떼","mis":"K1-2-u4-X04"}],"explanation":["이튿날은 다음 날을 뜻하는 시간을 나타내는 말이에요.","풀밭과 양 떼는 아니에요.","국어활동 55쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_d#4','kor',1,2,'u4','','g1_2_kor_u4_review_d','unit_review','K1-2-u4-C3',1,'mc','auto','‘그럼 나도 한번 먹어 볼까?’는 어떤 말인가요?',ARRAY['K1-2-u4-X06','K1-2-u4-X02']::text[],false,'{"seq":4,"concept":"K1-2-u4-C3","difficulty":1,"kind":"mc","stem":"‘그럼 나도 한번 먹어 볼까?’는 어떤 말인가요?","options":[{"t":"마음속으로 한 말","correct":true},{"t":"소리 내어 한 말","mis":"K1-2-u4-X06"},{"t":"선생님이 한 말","mis":"K1-2-u4-X02"}],"explanation":["작은따옴표가 있으니 마음속으로 한 말이에요.","주원이의 생각이에요.","116쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_d#5','kor',1,2,'u4','','g1_2_kor_u4_review_d','unit_review','K1-2-u4-C7',1,'mc','auto','『국어』 136쪽 — 「태윤이가 공을 ___.」에 알맞은 말은?',ARRAY['K1-2-u4-X17']::text[],false,'{"seq":5,"concept":"K1-2-u4-C7","difficulty":1,"kind":"mc","stem":"『국어』 136쪽 — 「태윤이가 공을 ___.」에 알맞은 말은?","options":[{"t":"찹니다","correct":true},{"t":"씻습니다","mis":"K1-2-u4-X17"},{"t":"읽습니다","mis":"K1-2-u4-X17"}],"explanation":["태윤이가 공을 찹니다.","공은 차요.","136쪽 기초 다지기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_d#6','kor',1,2,'u4','','g1_2_kor_u4_review_d','unit_review','K1-2-u4-C4',1,'mc','auto','만화 영화를 볼 때 자세히 살펴볼 것은?',ARRAY['K1-2-u4-X08']::text[],false,'{"seq":6,"concept":"K1-2-u4-C4","difficulty":1,"kind":"mc","stem":"만화 영화를 볼 때 자세히 살펴볼 것은?","options":[{"t":"인물의 표정과 몸짓","correct":true},{"t":"화면의 색깔 수","mis":"K1-2-u4-X08"},{"t":"영상의 길이","mis":"K1-2-u4-X08"}],"explanation":["인물의 말, 표정, 몸짓을 살펴봐요.","길이나 색깔 수는 이야기가 아니에요.","125쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_d#7','kor',1,2,'u4','','g1_2_kor_u4_review_d','unit_review','K1-2-u4-C5',1,'mc','auto','「아기 거북이가 숲으로 왔어요!」의 등장인물은?',ARRAY['K1-2-u4-X03']::text[],false,'{"seq":7,"concept":"K1-2-u4-C5","difficulty":1,"kind":"mc","stem":"「아기 거북이가 숲으로 왔어요!」의 등장인물은?","options":[{"t":"아기 거북","correct":true},{"t":"아이쿠","mis":"K1-2-u4-X03"},{"t":"도둑","mis":"K1-2-u4-X03"}],"explanation":["엄마 까투리, 꺼병이 사 남매, 아기 거북이 나와요.","다른 이야기의 인물은 고르지 않아요.","129쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_d#8','kor',1,2,'u4','','g1_2_kor_u4_review_d','unit_review','K1-2-u4-C6',1,'mc','auto','칭찬 붙임딱지를 붙여 줄 작품은?',ARRAY['K1-2-u4-X14','K1-2-u4-X16']::text[],false,'{"seq":8,"concept":"K1-2-u4-C6","difficulty":1,"kind":"mc","stem":"칭찬 붙임딱지를 붙여 줄 작품은?","options":[{"t":"인물의 모습과 행동이 잘 나타난 작품","correct":true},{"t":"색이 가장 많은 작품","mis":"K1-2-u4-X14"},{"t":"가장 빨리 그린 작품","mis":"K1-2-u4-X16"}],"explanation":["인물과 장면이 잘 드러난 작품을 칭찬해요.","색이나 빠르기는 기준이 아니에요.","지도서 197쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_d#9','kor',1,2,'u4','','g1_2_kor_u4_review_d','unit_review','K1-2-u4-C1',2,'match','auto','지도서 평가 — 「개미와 비둘기」에서 인물과 한 일을 이어 보세요.','{}'::text[],false,'{"seq":9,"concept":"K1-2-u4-C1","difficulty":2,"kind":"match","stem":"지도서 평가 — 「개미와 비둘기」에서 인물과 한 일을 이어 보세요.","pairs":[{"l":"사냥꾼","r":"“앗, 따가워!” 하고 소리를 질렀다."},{"l":"비둘기","r":"개미에게 감사의 인사를 했다."}],"mis":"K1-2-u4-X02","explanation":["사냥꾼은 개미에게 물려 소리를 질렀어요.","비둘기는 개미에게 고마워했어요.","지도서 203쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_d#10','kor',1,2,'u4','','g1_2_kor_u4_review_d','unit_review','K1-2-u4-C2',2,'mc','auto','『국어활동』 55쪽 — 「양치기 소년」에서 진짜 늑대가 나타난 때는?',ARRAY['K1-2-u4-X05']::text[],false,'{"seq":10,"concept":"K1-2-u4-C2","difficulty":2,"kind":"mc","stem":"『국어활동』 55쪽 — 「양치기 소년」에서 진짜 늑대가 나타난 때는?","options":[{"t":"며칠 뒤","correct":true},{"t":"아침 일찍","mis":"K1-2-u4-X05"},{"t":"이튿날","mis":"K1-2-u4-X05"}],"explanation":["며칠 뒤에 진짜 늑대가 나타났어요.","아침 일찍, 이튿날에는 거짓말을 했어요.","국어활동 55쪽이에요."],"asset":{"type":"passage","lines":["아침 일찍 양 떼를 몰고 풀밭으로 간 양치기 소년은 심심했어요.","‘뭐, 재미있는 일 없을까?’","소년은 늑대가 나타났다고 거짓말을 했어요.","이튿날 소년은 또 거짓말을 해 마을 사람들이 화가 났어요.","며칠 뒤, 이번에는 진짜로 늑대가 나타났어요.","“늑대가 나타났어요! 도와주세요!”","마을 사람들은 아무도 오지 않았고, 소년은 그제야 거짓말한 것을 후회했어요."],"title":"『국어활동』 52~55쪽 — 양치기 소년"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_d#11','kor',1,2,'u4','','g1_2_kor_u4_review_d','unit_review','K1-2-u4-C3',2,'blank','auto','『국어활동』 54쪽 — 빈칸에 알맞은 따옴표는?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_d#12','kor',1,2,'u4','','g1_2_kor_u4_review_d','unit_review','K1-2-u4-C4',2,'mc','auto','만화 영화에서 있었던 일을 정리할 때 먼저 할 일은?',ARRAY['K1-2-u4-X08']::text[],false,'{"seq":12,"concept":"K1-2-u4-C4","difficulty":2,"kind":"mc","stem":"만화 영화에서 있었던 일을 정리할 때 먼저 할 일은?","options":[{"t":"누가 나오는지 알아보기","correct":true},{"t":"영상 길이 재기","mis":"K1-2-u4-X08"},{"t":"좋아하는 색 찾기","mis":"K1-2-u4-X08"}],"explanation":["누가 나오는지 알아야 누가 무엇을 했는지 알 수 있어요.","이야기와 상관없는 것은 살피지 않아요.","124쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_d#13','kor',1,2,'u4','','g1_2_kor_u4_review_d','unit_review','K1-2-u4-C5',2,'mc','auto','감동적인 장면을 말한 것은?',ARRAY['K1-2-u4-X13','K1-2-u4-X10']::text[],false,'{"seq":13,"concept":"K1-2-u4-C5","difficulty":2,"kind":"mc","stem":"감동적인 장면을 말한 것은?","options":[{"t":"아기 거북이 다시 가족을 만나는 장면이 감동적이야","correct":true},{"t":"만화 영화가 몇 분이었는지가 감동적이야","mis":"K1-2-u4-X13"},{"t":"감동적이었어.","mis":"K1-2-u4-X10"}],"explanation":["어떤 장면인지 말했어요.","한마디로 끝내지 않아요.","131쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_d#14','kor',1,2,'u4','','g1_2_kor_u4_review_d','unit_review','K1-2-u4-C7',2,'mc','auto','동작을 나타내는 말이 아닌 것은?',ARRAY['K1-2-u4-X17']::text[],false,'{"seq":14,"concept":"K1-2-u4-C7","difficulty":2,"kind":"mc","stem":"동작을 나타내는 말이 아닌 것은?","options":[{"t":"얼굴","correct":true},{"t":"씻습니다","mis":"K1-2-u4-X17"},{"t":"찹니다","mis":"K1-2-u4-X17"}],"explanation":["얼굴은 몸의 이름이에요.","씻습니다·찹니다는 동작을 나타내요.","지도서 201쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_d#15','kor',1,2,'u4','','g1_2_kor_u4_review_d','unit_review','K1-2-u4-C2',2,'mc','auto','지도서 평가 — 「개미와 비둘기」에서 가장 먼저 일어난 일은?',ARRAY['K1-2-u4-X05']::text[],false,'{"seq":15,"concept":"K1-2-u4-C2","difficulty":2,"kind":"mc","stem":"지도서 평가 — 「개미와 비둘기」에서 가장 먼저 일어난 일은?","options":[{"t":"사냥꾼이 비둘기에게 몰래 총을 겨누었다","correct":true},{"t":"비둘기가 깜짝 놀라 날아갔다","mis":"K1-2-u4-X05"},{"t":"개미가 사냥꾼의 발꿈치를 물었다","mis":"K1-2-u4-X05"}],"explanation":["사냥꾼이 총을 겨눈 일이 처음이에요.","그다음 개미가 물고, 비둘기가 날아갔어요.","지도서 203쪽이에요."],"asset":{"type":"passage","lines":["비둘기가 나뭇가지 위에 앉아 있었습니다.","이것을 본 사냥꾼이 비둘기에게 몰래 총을 겨누었습니다.","‘저런, 비둘기가 위험하다.’","그 모습을 본 개미가 사냥꾼의 발꿈치를 따끔하게 물었습니다.","“앗, 따가워!” 사냥꾼이 소리를 지르자 비둘기가 깜짝 놀라 날아갔습니다.","“개미야, 고마워. 네가 아니었으면 큰일 날 뻔했구나.”"],"title":"지도서 203쪽 — 개미와 비둘기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_d#16','kor',1,2,'u4','','g1_2_kor_u4_review_d','unit_review','K1-2-u4-C5',2,'ox','auto','만화 영화에 나오는 인물의 말을 그대로 외워서 말하는 것이 생각이나 느낌을 말하는 방법이에요.',ARRAY['K1-2-u4-X11']::text[],false,'{"seq":16,"concept":"K1-2-u4-C5","difficulty":2,"kind":"ox","stem":"만화 영화에 나오는 인물의 말을 그대로 외워서 말하는 것이 생각이나 느낌을 말하는 방법이에요.","answer":"X","reason_options":[{"t":"외운 말이 아니라 장면에 대한 내 생각이나 느낌을 말해야 하니까","correct":true},{"t":"외워서 말하면 정확하니까","mis":"K1-2-u4-X11"}],"mis":"K1-2-u4-X11","explanation":["있었던 일에 대한 생각이나 느낌을 말해요.","인물의 말을 외우는 것은 느낌이 아니에요.","135쪽 3번이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_d#17','kor',1,2,'u4','','g1_2_kor_u4_review_d','unit_review','K1-2-u4-C2',3,'error','auto','「소금을 만드는 맷돌」을 「도둑이 맷돌을 훔쳤다 → 사람들이 시장에서 맷돌 이야기를 했다」로 정리했어요. 무엇이 잘못되었나요?',ARRAY['K1-2-u4-X05','K1-2-u4-X04']::text[],false,'{"seq":17,"concept":"K1-2-u4-C2","difficulty":3,"kind":"error","stem":"「소금을 만드는 맷돌」을 「도둑이 맷돌을 훔쳤다 → 사람들이 시장에서 맷돌 이야기를 했다」로 정리했어요. 무엇이 잘못되었나요?","options":[{"t":"차례가 바뀌었어요 — 사람들의 이야기를 듣고 도둑이 맷돌을 훔쳤어요","correct":true,"mis_target":"K1-2-u4-X05"},{"t":"잘 정리했어요","mis":"K1-2-u4-X05"},{"t":"시간을 나타내는 말을 빼야 해요","mis":"K1-2-u4-X04"}],"explanation":["어느 날 아침 이야기를 듣고, 깊은 밤에 훔쳤어요.","시간을 나타내는 말로 차례를 확인해요.","122쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_d#18','kor',1,2,'u4','','g1_2_kor_u4_review_d','unit_review','K1-2-u4-C4',3,'error','auto','만화 영화를 본 뒤 「화면이 몇 가지 색이었는지」를 정리했어요. 무엇이 잘못되었나요?',ARRAY['K1-2-u4-X08']::text[],false,'{"seq":18,"concept":"K1-2-u4-C4","difficulty":3,"kind":"error","stem":"만화 영화를 본 뒤 「화면이 몇 가지 색이었는지」를 정리했어요. 무엇이 잘못되었나요?","options":[{"t":"이야기와 상관없어요 — 누가 무엇을 했는지 정리해요","correct":true,"mis_target":"K1-2-u4-X08"},{"t":"잘 정리했어요","mis":"K1-2-u4-X08"},{"t":"영상 길이도 써야 해요","mis":"K1-2-u4-X08"}],"explanation":["색깔 수로는 있었던 일을 알 수 없어요.","인물과 한 일을 정리해요.","지도서 189쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_d#19','kor',1,2,'u4','','g1_2_kor_u4_review_d','unit_review','K1-2-u4-C5',3,'mc','auto','『국어』 135쪽 3번 — 만화 영화를 보고 생각이나 느낌을 말하는 방법으로 알맞은 것은?',ARRAY['K1-2-u4-X11']::text[],false,'{"seq":19,"concept":"K1-2-u4-C5","difficulty":3,"kind":"mc","stem":"『국어』 135쪽 3번 — 만화 영화를 보고 생각이나 느낌을 말하는 방법으로 알맞은 것은?","options":[{"t":"떠오르는 장면에 대한 느낌을 말한다","correct":true},{"t":"친구의 생각이나 느낌을 따라 말한다","mis":"K1-2-u4-X11"},{"t":"인물의 말을 그대로 외워서 말한다","mis":"K1-2-u4-X11"}],"explanation":["있었던 일이나 장면에 대한 내 생각이나 느낌을 말해요.","따라 말하거나 외워서 말하지 않아요.","135쪽 3번이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_d#20','kor',1,2,'u4','','g1_2_kor_u4_review_d','unit_review','K1-2-u4-C6',3,'mc','auto','친구와 같은 만화 영화를 그렸는데 장면이 달라요. 알맞은 생각은?',ARRAY['K1-2-u4-X12']::text[],false,'{"seq":20,"concept":"K1-2-u4-C6","difficulty":3,"kind":"mc","stem":"친구와 같은 만화 영화를 그렸는데 장면이 달라요. 알맞은 생각은?","options":[{"t":"감동을 주는 장면은 사람마다 다를 수 있어요","correct":true},{"t":"둘 중 하나는 틀렸어요","mis":"K1-2-u4-X12"},{"t":"같은 장면으로 다시 그려야 해요","mis":"K1-2-u4-X12"}],"explanation":["같은 만화 영화라도 감동 장면은 달라요.","서로 존중해요.","지도서 196쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_d#21','kor',1,2,'u4','','g1_2_kor_u4_review_d','unit_review','K1-2-u4-C7',3,'error','auto','「진희가 그림을 찹니다.」라고 썼어요. 무엇이 잘못되었나요?',ARRAY['K1-2-u4-X17']::text[],false,'{"seq":21,"concept":"K1-2-u4-C7","difficulty":3,"kind":"error","stem":"「진희가 그림을 찹니다.」라고 썼어요. 무엇이 잘못되었나요?","options":[{"t":"그림은 「그립니다」가 알맞아요","correct":true,"mis_target":"K1-2-u4-X17"},{"t":"잘 썼어요","mis":"K1-2-u4-X17"},{"t":"「그림을」을 빼야 해요","mis":"K1-2-u4-X17"}],"explanation":["공은 차고, 그림은 그려요.","진희가 그림을 그립니다.","136쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_d#22','kor',1,2,'u4','','g1_2_kor_u4_review_d','unit_review','K1-2-u4-C6',3,'match','auto','감동적인 장면 그리기 — 차례와 할 일을 이어 보세요.','{}'::text[],false,'{"seq":22,"concept":"K1-2-u4-C6","difficulty":3,"kind":"match","stem":"감동적인 장면 그리기 — 차례와 할 일을 이어 보세요.","pairs":[{"l":"①","r":"감동적인 장면을 친구들과 이야기하기"},{"l":"②","r":"감동적인 장면을 그림으로 표현하기"},{"l":"③","r":"그림을 전시하고 감상하기"}],"mis":"K1-2-u4-X05","explanation":["이야기하기 → 그리기 → 전시하고 감상하기예요.","차례대로 해요.","132쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_d#23','kor',1,2,'u4','','g1_2_kor_u4_review_d','unit_review','K1-2-u4-C7',4,'sa','auto','『국어』 136쪽 — 「재현이가 이를 ◯◯◯◯.」 빈칸에 알맞은 동작을 나타내는 말을 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K1-2-u4-C7","difficulty":4,"kind":"sa","stem":"『국어』 136쪽 — 「재현이가 이를 ◯◯◯◯.」 빈칸에 알맞은 동작을 나타내는 말을 쓰세요.","answer":["닦습니다","닦아요","닦는다"],"explanation":["재현이가 이를 닦습니다.","동작 말로 누가 무엇을 하는지 나타내요.","136쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_d#24','kor',1,2,'u4','','g1_2_kor_u4_review_d','unit_review','K1-2-u4-C4',4,'essay','teacher','「빨간 모자가 된 아이쿠」에서 있었던 일을 차례대로 세 문장으로 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K1-2-u4-C4","difficulty":4,"kind":"essay","stem":"「빨간 모자가 된 아이쿠」에서 있었던 일을 차례대로 세 문장으로 쓰세요.","answer_guide":{"answer":"예: 아이쿠가 할머니 댁에 가기로 했다. / 아이쿠와 비비가 꽃을 땄다. / 꽃을 받은 백작이 재채기를 했다. — 차례와 누가 무엇을이 맞으면 맞아요.","scoring_points":["누가 무엇을 했는지 썼는가","차례가 맞는가","있었던 일만 썼는가"]},"explanation":["127쪽 5번을 떠올려요.","먼저 있었던 일부터 써요.","127쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_d#25','kor',1,2,'u4','','g1_2_kor_u4_review_d','unit_review','K1-2-u4-C6',4,'essay','teacher','내가 본 만화 영화에서 그림으로 그리고 싶은 감동적인 장면을 「누가 무엇을 하는 장면」으로 쓰고, 그 까닭을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K1-2-u4-C6","difficulty":4,"kind":"essay","stem":"내가 본 만화 영화에서 그림으로 그리고 싶은 감동적인 장면을 「누가 무엇을 하는 장면」으로 쓰고, 그 까닭을 쓰세요.","answer_guide":{"answer":"예: 주인공이 넘어진 친구를 일으켜 주는 장면 — 친구를 돕는 마음이 따뜻하게 느껴져서. — 장면과 까닭이 있으면 맞아요.","scoring_points":["인물과 한 일이 드러나는가","까닭을 썼는가","문장이 자연스러운가"]},"explanation":["그릴 인물을 먼저 정해요.","왜 그 장면인지 써요.","132쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
